window.CARE_DATA={"cats":[{"code":"17800","grp":"專業科目","name":"身體照顧","n":191},{"code":"17800","grp":"專業科目","name":"生活照顧","n":103},{"code":"17800","grp":"專業科目","name":"家務處理","n":72},{"code":"17800","grp":"專業科目","name":"緊急及意外事件處理","n":88},{"code":"17800","grp":"專業科目","name":"家庭支持","n":102},{"code":"17800","grp":"專業科目","name":"職業倫理","n":69},{"code":"90006","grp":"共同科目","name":"職業安全衛生","n":100},{"code":"90007","grp":"共同科目","name":"工作倫理與職業道德","n":100},{"code":"90008","grp":"共同科目","name":"環境保護","n":100},{"code":"90009","grp":"共同科目","name":"節能減碳","n":100}],"qs":[{"c":0,"n":1,"q":"為預防泌尿道感染的措施，下列做法何者正確？","o":["建議案主盆浴","建議每 5～6 小時解尿一次","維持尿液的鹼性，以增加抑菌能力","在無特殊疾病的飲水禁忌情況下，一般案主每天飲水量至少 2000cc"],"a":4,"e":"足夠水分（每日約2000cc）可沖刷尿道減少細菌滯留；應淋浴、每2～3小時解尿，尿液偏酸性才有抑菌效果。"},{"c":0,"n":2,"q":"修剪指甲的原則，何者為不正確？","o":["手指甲剪成圓形","腳趾剪成平形","足部剪繭使用剪刀剪","指甲每兩週修剪一次"],"a":3,"e":"足部厚繭不可用剪刀剪，容易剪傷造成感染，應泡軟後用磨石或由醫護處理。"},{"c":0,"n":3,"q":"造成案主便秘的原因，下列何者不正確？","o":["身體活動量減少","定時給予腹部按摩","飲食中缺乏纖維素","麻醉、機械性的阻塞"],"a":2,"e":"腹部按摩能促進腸蠕動、改善便秘，不是造成便秘的原因。"},{"c":0,"n":4,"q":"腹瀉的護理措施，下列何者不正確？","o":["增加水分攝取量","預防肛門周圍皮膚破損","增加含纖維質食物之攝取","必要時需禁食"],"a":3,"e":"腹瀉時應減少高纖維食物，以免刺激腸蠕動加重腹瀉。"},{"c":0,"n":5,"q":"下列哪些被照顧者需執行床上沐浴？A.中風癱瘓者；B.意識不清者；C.早期的失智症患者；D.憂鬱症而無法自行沐浴者","o":["ABC","ABD","BCD","ACD"],"a":2,"e":"中風癱瘓、意識不清、憂鬱無法自理者需床上沐浴；早期失智者仍可在協助下自行沐浴。"},{"c":0,"n":6,"q":"照顧一位左手乏力的人，其褲帶最好是選擇何者？","o":["鬆緊帶","綁帶子","拉鍊","鈕扣"],"a":1,"e":"鬆緊帶褲頭不需雙手操作，單手乏力者最容易自行穿脫。"},{"c":0,"n":7,"q":"案主平躺時，髖關節極易向外翻，所以應給予案主使用：","o":["床板","毛毯，浴毯捲軸","垂足板","手握捲"],"a":2,"e":"以毛毯或浴毯捲成捲軸放在大腿外側，可防止髖關節外翻（外旋）。"},{"c":0,"n":8,"q":"下列有關舖床的姿勢，何者為正確？","o":["應盡量彎腰","兩腳盡量伸直","脊柱保持平直","重心放於背部"],"a":3,"e":"鋪床時脊柱保持平直、屈膝降低重心，才能避免腰背受傷。"},{"c":0,"n":9,"q":"下列有關臥床休息案主的陳述，何者不正確？","o":["臥床休息的案主不可以參與其日常活動","臥床休息有助於減輕疼痛及促進癒合","臥床休息的合併症包括壓瘡、便秘、尿路感染與肺炎","臥床休息不活動的案主，容易導致關節僵硬、肌肉萎縮"],"a":1,"e":"臥床休息者仍應在能力範圍內參與日常活動，以預防廢用與合併症。"},{"c":0,"n":10,"q":"當被照顧者使用留置導尿管時，下列哪一項敘述不正確？","o":["蓄尿袋務必保持在膀胱位置之下","遵守無菌技術之規則，清潔尿道口以下的導尿管","會陰護理每日至少一次","導尿管之固定，女性被照顧者貼於下腹部，男性被照顧者貼於大腿內側"],"a":4,"e":"導尿管固定方向相反：男性貼於下腹部（減少陰莖陰囊交接處受壓），女性貼於大腿內側。"},{"c":0,"n":11,"q":"會陰沖洗時，沖洗壺的壺嘴正確方向為","o":["朝向床頭","朝向床尾","朝向左邊","朝向右邊"],"a":2,"e":"壺嘴朝床尾，水流由上往下沖，避免污水逆流回尿道口。"},{"c":0,"n":12,"q":"幫案主執行會陰沖洗時，棉棒擦洗方式應","o":["由左側擦至右側","由右側擦至左側","由上往下擦至會陰","由會陰往上擦至恥骨聯合處"],"a":3,"e":"會陰清潔原則是由上往下、由前往後（由乾淨往污染處），每支棉棒只擦一次。"},{"c":0,"n":13,"q":"以鼻胃管灌食時，食物的溶液距胃的高度依食物濃稠度約","o":["5 公分以下","6～10 公分","35～45 公分","50 公分以上"],"a":3,"e":"灌食空針距胃約30～45公分，利用重力讓食物緩慢流入，太高流速過快、太低流不下。"},{"c":0,"n":14,"q":"長期臥床者皮膚照顧最需注意的問題是","o":["手足廢用","關節畸形","壓瘡","便秘"],"a":3,"e":"長期臥床最大風險是骨突處持續受壓造成壓瘡，需定時翻身。"},{"c":0,"n":15,"q":"舖床時照顧服務員應將身體的重心放於","o":["雙手上","雙腳上","雙肩上","臀部上"],"a":2,"e":"鋪床時兩腳分開、重心放雙腳，利用下肢力量而非腰背。"},{"c":0,"n":16,"q":"長時間不動對案主造成的問題不包括哪一項？","o":["姿勢性低血壓","排尿困難","腹瀉","骨質疏鬆"],"a":3,"e":"長期不動易造成便秘，而不是腹瀉。"},{"c":0,"n":17,"q":"女性案主會陰沖洗的正確姿勢為","o":["平躺仰臥","左側臥","右側臥","屈膝仰臥"],"a":4,"e":"女性會陰沖洗採屈膝仰臥（兩腿屈膝分開），方便清潔且舒適。"},{"c":0,"n":18,"q":"若被照顧者有一側肢體行動不便，穿脫衣服的順序何者較適宜？","o":["先脫健側","先脫患側","先穿健側","由被照顧者自己決定"],"a":1,"e":"穿脫衣原則「脫健穿患」：先脫健側，再脫患側；穿時先穿患側。"},{"c":0,"n":19,"q":"協助案主，穿脫衣服順序何者為宜？","o":["先穿遠側","先穿近側","先脫遠側","依案主喜好而定"],"a":1,"e":"協助穿衣時先穿遠側再穿近側，脫衣則先脫近側，可減少翻動。"},{"c":0,"n":20,"q":"有關執行個人衛生照護的目的，下列何者不正確？","o":["打發時間","促進血液循環","保持感覺清爽舒適","強化外觀與自尊"],"a":1,"e":"個人衛生照護的目的是清潔舒適、促進循環及維護自尊，不是打發時間。"},{"c":0,"n":21,"q":"尿失禁的敘述，何者不正確？","o":["非意識的控制下解出尿液","照護宜保持清潔與舒適的原則","給予排尿訓練或使用尿套、尿布等襯墊","每天訓斥病患要好好自我控制小便"],"a":4,"e":"尿失禁應給予排尿訓練與尊重，訓斥只會造成自尊受損與壓力。"},{"c":0,"n":22,"q":"身體容易發生壓瘡的部位是","o":["尾椎骨處","腹部","胸部","大腿"],"a":1,"e":"尾椎（薦骨）為骨突處且長期受壓，是最常見的壓瘡部位。"},{"c":0,"n":23,"q":"促進正常排便的方法，下列何者不正確？","o":["養成定時排便的習慣","攝取富含高蛋白質的食物","安排適當的排便姿勢","每日攝取 2000～3000 西西的液體"],"a":2,"e":"促進排便應多攝取高纖維食物；高蛋白飲食反而容易便秘。"},{"c":0,"n":24,"q":"一般協助案主維持個人衛生的原則，下列敘述何者不正確？","o":["注重個人隱私環境","維持室內溫度 22℃～27℃","於飯前或飯後 1 小時才做","需用力擦拭才能將身上的污垢去除"],"a":4,"e":"擦洗應輕柔，用力擦拭會傷害老人脆弱的皮膚。"},{"c":0,"n":25,"q":"用來協助案主支托身體的用物，下列何者不正確？","o":["枕頭","毛巾","彎盆","床單"],"a":3,"e":"彎盆是用來盛裝嘔吐物或用物的器具，不是支托身體的物品。"},{"c":0,"n":26,"q":"灌食的注意事項，下列何者不正確？","o":["應避免灌入空氣","灌食中若出現咳嗽不止，應立刻停止灌食","需抬高床頭再灌食，並確定胃管是否於胃內","灌食後立即採平躺臥姿"],"a":4,"e":"灌食後應維持半坐臥30～60分鐘，立即平躺易造成嘔吐與吸入性肺炎。"},{"c":0,"n":27,"q":"促進傷口癒合的措施，下列何者不正確？","o":["傷口保持清潔","勤於翻身，減少傷口受壓力的時間","注意營養補充","不可下床活動，儘量臥床休息"],"a":4,"e":"適度下床活動能促進血液循環與傷口癒合，一味臥床反而不利。"},{"c":0,"n":28,"q":"照顧服務員為案主洗頭時，搓揉頭髮及頭皮的適當方式","o":["使用指甲尖端","使用指腹","使用美容院常用的塑膠髮梳","使用按摩棒"],"a":2,"e":"應使用指腹搓揉頭皮，指甲會刮傷頭皮。"},{"c":0,"n":29,"q":"下列有關鋪床基本原則的敘述，何者不正確？","o":["髒床單避免放在地上","為了使床鋪更整齊，在鋪床前應先拍動床鋪","為減少對皮膚的刺激，橡皮中單上應加鋪布中單","鋪床時為節省時間與體力，應先鋪好一側再鋪另一側"],"a":2,"e":"鋪床前拍動床鋪會使灰塵與病菌飛揚，造成交叉感染。"},{"c":0,"n":30,"q":"由於老年人走路不方便且不願意到戶外曬太陽，容易導致何種營養素不足？","o":["維生素 D","鐵","維生素 B 群","鈉"],"a":1,"e":"曬太陽可讓皮膚合成維生素D，老人少外出容易缺乏。"},{"c":0,"n":31,"q":"下列有關頭髮糾結的處理方法，何者不正確？","o":["以剪刀剪掉糾結的部分","梳髮時以一手固定近髮根","以酒精或水先潤濕再梳","先梳髮尾再往上梳到髮根"],"a":1,"e":"頭髮糾結應用水或酒精潤濕後由髮尾往髮根慢慢梳開，不應直接剪掉。"},{"c":0,"n":32,"q":"移動案主時為方便省力應","o":["擺個漂亮姿勢","身體重心落於兩腳中間","不需注意姿勢，只要方便","不需顧到案主感受"],"a":2,"e":"兩腳分開、重心落在兩腳中間，可增加支撐面、穩定省力。"},{"c":0,"n":33,"q":"洗髮時之水溫以攝氏多少度合宜？","o":["冷水即可","與體溫同 36～37℃","略高於體溫，約 41～43℃","50～55℃"],"a":3,"e":"洗髮水溫約41～43℃，略高於體溫較舒適。"},{"c":0,"n":34,"q":"成人發燒的認定為腋溫","o":["36℃～36.5℃","36.6℃～37℃","37.1℃～37.4℃","37.5℃及以上"],"a":4,"e":"成人腋溫37.5℃以上視為發燒。"},{"c":0,"n":35,"q":"正常成人的心跳次數為每分鐘","o":["40～59 次","60～99 次","100～109 次","110 次及以上"],"a":2,"e":"成人正常心跳每分鐘60～100次。"},{"c":0,"n":36,"q":"依照2015年中華民國心臟學會與台灣高血壓學會對正常血壓的定義是","o":["收縮壓低於 120 ㎜ Hg 以及舒張壓低於 80 ㎜ Hg","收縮壓低於 140 ㎜ Hg 以及舒張壓低於 95 ㎜ Hg","收縮壓高於 150 ㎜ Hg 以及舒張壓高於 90 ㎜ Hg","收縮壓高於 160 ㎜ Hg 以及舒張壓高於 95 ㎜ Hg"],"a":1,"e":"2015年國內指引的正常血壓為收縮壓<120且舒張壓<80 mmHg。"},{"c":0,"n":37,"q":"成人每分鐘正常呼吸次數，下列何者正確？","o":["12～20 次／分","25～29 次 ／分","30～35 次／分","36～40 次／分"],"a":1,"e":"成人正常呼吸每分鐘12～20次。"},{"c":0,"n":38,"q":"下列情況，何者不適合用熱敷來減輕不適？","o":["月經痛","耳朵痛","膝關節痛","手臂酸痛"],"a":2,"e":"耳朵痛（可能為中耳炎等感染發炎）不宜熱敷，以免加重發炎。"},{"c":0,"n":39,"q":"當一個人發燒時會出現那些症狀？A.口渴B.臉色潮紅C.脈搏加速D.食慾不振E.呼吸慢而淺F.小便量增加G.皮膚乾燥而發燙","o":["ACDEF","CDEFG","ABCDG","BDEFG"],"a":3,"e":"發燒會口渴、臉紅、脈搏加快、食慾差、皮膚乾熱；呼吸會變快且尿量減少。"},{"c":0,"n":40,"q":"為案主做身體清潔時，水溫要比體溫","o":["低 5 度","一樣","略高","低 10 度"],"a":3,"e":"清潔身體的水溫應略高於體溫（約41～43℃），感覺溫暖舒適。"},{"c":0,"n":41,"q":"有關預防壓瘡的方法，下列何者不正確？","o":["均衡營養","保持皮膚乾爽","使用適當輔助用品","每四小時翻身一次"],"a":4,"e":"預防壓瘡至少每2小時翻身一次，4小時太久。"},{"c":0,"n":42,"q":"對於老年人皮膚之描述，下列何者不正確？","o":["易受細菌感染","皮脂腺萎縮造成皮膚乾燥","將皮膚塗擦乳霜或凡士林","皮膚易有色素沈著現象，稱為紫斑"],"a":4,"e":"老人皮膚出現的色素沈著是老人斑；紫斑是皮下出血造成，兩者不同。"},{"c":0,"n":43,"q":"下列那一個部位最常被用來測量脈搏？","o":["心尖脈","橈動脈","頸動脈","足背動脈"],"a":2,"e":"橈動脈位於手腕拇指側，最方便觸摸，是最常測量脈搏的部位。"},{"c":0,"n":44,"q":"有關呼吸治療的敘述，下列何者不正確？","o":["拍痰一天可 2～3 次","蒸氣治療的目的是讓痰液稀釋","治療時有頭暈，心跳加快、氣喘是正常現象","姿位引流將痰液最多區擺在最高位，並做區域拍鬆"],"a":3,"e":"呼吸治療中若出現頭暈、心悸、氣喘是異常反應，應立即停止並報告。"},{"c":0,"n":45,"q":"冰袋使用的目的，下列何者不正確？","o":["止血","消腫","減輕疼痛","促進血液循環"],"a":4,"e":"冰敷使血管收縮，可止血、消腫、止痛；促進血液循環是熱敷的作用。"},{"c":0,"n":46,"q":"踝關節扭傷的第一天，可做的處理方式有：A.按摩患肢B.固定患肢C.抬高患肢D.放低患肢E.冷敷扭傷部位F.熱敷扭傷部位","o":["ACE","ACF","BCE","BDE"],"a":3,"e":"扭傷急性期處理：固定、抬高、冰敷；不可按摩或熱敷。"},{"c":0,"n":47,"q":"依據您的判斷下列哪種情況應立即報告？","o":["耳溫 36.5℃","嬰兒脈搏 120 次/分","成人脈搏 90 次/分","成人脈搏 40 次/分"],"a":4,"e":"成人脈搏每分鐘少於60次屬心搏過緩，40次已明顯異常，應立即報告。"},{"c":0,"n":48,"q":"有關測量血壓時應注意事項，下列何者不正確？","o":["小枕頭支托，與心臟成水平","壓脈帶綁於上臂，愈緊愈準確","將聽診器腹面置於動脈搏動處","反覆再測量時，二次之間應間隔 3 分鐘以上"],"a":2,"e":"壓脈帶以可放入一指的鬆緊度為宜，綁太緊會使測得的血壓不準確。"},{"c":0,"n":49,"q":"下列何者是影響體溫下降的因素？","o":["因需檢查而禁食","強烈情緒反應","新陳代謝增加","肌肉活動增加"],"a":1,"e":"禁食使能量攝取減少、代謝降低，體溫會下降；其他選項都會使體溫上升。"},{"c":0,"n":50,"q":"下列何者不是長期臥床被照顧者常見的合併症？","o":["壓瘡","肺炎","昏迷","尿路感染"],"a":3,"e":"昏迷是原本疾病的狀態，不是臥床造成的合併症；壓瘡、肺炎、尿路感染才是。"},{"c":0,"n":51,"q":"欲觀察突發性昏迷案主的脈搏應該要測量的部位為下列何者？","o":["橈動脈","頸動脈","肱動脈","股動脈"],"a":2,"e":"突發昏迷時周邊脈搏可能摸不到，應測頸動脈最可靠。"},{"c":0,"n":52,"q":"皮膚的功能，下列何者不正確？","o":["分泌黏液","排汗、散熱","合成維生素","感受溫度的感覺器官"],"a":1,"e":"皮膚分泌汗液與皮脂，不分泌黏液（黏液是黏膜分泌的）。"},{"c":0,"n":53,"q":"下列何者是造成壓瘡的原因？","o":["均衡營養","固定不動","多變換姿勢","保持皮膚乾爽"],"a":2,"e":"長時間固定不動使局部持續受壓、缺血，是壓瘡的主因。"},{"c":0,"n":54,"q":"若關節剛不慎扭傷，導致疼痛、腫脹厲害，初步處理方法為？","o":["熱敷","冰敷","先熱敷再冰敷","先冰敷再熱敷"],"a":2,"e":"剛扭傷先冰敷，可收縮血管減少腫脹與疼痛。"},{"c":0,"n":55,"q":"給案主氧氣時的注意事項，下列何者不正確？","o":["濕化氧氣","懸掛禁止吸煙告示牌","看病人喘就給他氧氣","不可突然停止氧氣的供應"],"a":3,"e":"給氧必須依醫囑，不能看到喘就自行給氧，否則可能造成二氧化碳滯留。"},{"c":0,"n":56,"q":"皮膚長期受壓迫而外觀發紅，為壓傷分類的第幾級？","o":["第一級","第二級","第三級","第四級"],"a":1,"e":"皮膚完整但持續發紅、壓了不褪色，屬於第一級壓傷。"},{"c":0,"n":57,"q":"下列何者為促進有效呼吸的措施？","o":["避免飲水","多與家屬交談","深呼吸及有效的咳嗽","儘可能讓案主平躺，不要下床"],"a":3,"e":"深呼吸與有效咳嗽可擴張肺部、排出痰液。"},{"c":0,"n":58,"q":"下列何種情形會促使壓瘡產生？","o":["提供適當的營養","儘可能將案主抬起再移動，以免摩擦皮膚","鼓勵案主坐起，能坐多久就坐多久","經常幫助臥床案主翻身，減少身體組織持續受壓"],"a":3,"e":"長時間坐著，臀部與尾骶骨持續受壓，同樣會造成壓瘡。"},{"c":0,"n":59,"q":"有關氧氣治療的注意事項，下列何者不正確？","o":["需注意被照顧者的呼吸型態","被照顧者可自行調整氧氣濃度","給氧需依醫囑由護理人員執行","持續用氧的被照顧者不可突然停用"],"a":2,"e":"氧氣濃度與流量需依醫囑設定，被照顧者不可自行調整。"},{"c":0,"n":60,"q":"案主發燒時的照顧措施，下列何者不正確？","o":["增加水分攝取","降低室溫減少衣服被蓋","用熱水擦澡以免著涼","補充高營養易消化流質飲食"],"a":3,"e":"發燒時應用溫水拭浴散熱，熱水會使體溫更高。"},{"c":0,"n":61,"q":"當案主有服用毛地黃藥物時，應特別注意下列何種生命徵象？","o":["體溫","心跳","血壓","呼吸速率"],"a":2,"e":"毛地黃會使心跳變慢，服藥前需測心跳（脈搏），每分鐘低於60次應暫停並報告。"},{"c":0,"n":62,"q":"為臥床案主作關節活動時，順序應為","o":["先做健側","無特殊順序","由遠心端關節做起","由近心端關節做起"],"a":4,"e":"關節活動由近心端（肩、髖）往遠心端（手、腳）進行。"},{"c":0,"n":63,"q":"有關臥床案主預防壓瘡的方法，下列何者錯誤？","o":["壓瘡傷口多按摩","每 2 小時協助翻身","身體移位時應避免摩擦","以軟墊保護身體的骨突處"],"a":1,"e":"壓瘡傷口與發紅處不可按摩，按摩會加重組織損傷。"},{"c":0,"n":64,"q":"案主長期臥床固定不動時，形成的合併症有哪些？A.垂足B.憂鬱C.栓塞D.骨質疏鬆E.髖關節外旋、屈曲F.身體水腫G.血壓上升","o":["ABDFG","BCDEG","ACDEF","ABCDE"],"a":4,"e":"長期臥床會造成垂足、憂鬱、血栓、骨質疏鬆、髖關節外旋；水腫與血壓上升並非典型合併症。"},{"c":0,"n":65,"q":"關於糖尿病被照顧者的足部護理，下列描述何者不正確？","o":["不可赤足走路","每日清潔襪子","有穿鞋就好不必合腳","每日檢視雙足"],"a":3,"e":"糖尿病患者應穿合腳的鞋襪，鞋子不合腳容易磨傷，傷口不易癒合。"},{"c":0,"n":66,"q":"生命徵象的範圍包括那些？","o":["血壓、意識狀態","脈搏、疼痛反應","血壓、體溫、呼吸、脈搏","神經反射、意識狀態"],"a":3,"e":"生命徵象是體溫、脈搏、呼吸、血壓（TPR、BP）。"},{"c":0,"n":67,"q":"測量口溫時，口溫表放置的位置宜在","o":["舌上","用舌含住即可","舌下舌繫帶旁","請案主用牙齒咬住"],"a":3,"e":"口溫計應放在舌下舌繫帶兩旁的熱袋處，此處血流豐富，測量最準確。"},{"c":0,"n":68,"q":"為案主施行被動關節的活動時應注意","o":["案主應穿著緊身衣褲，效果加倍","鼓勵案主以健側協助患側做肢體活動","每天應操作 1-2 次，每個關節重覆越多次效果越好","案主表達有疼痛及不舒服反應時，應加強力道不要停止，以加強運動效果"],"a":2,"e":"鼓勵用健側協助患側活動，可增加參與感與自我照顧能力。"},{"c":0,"n":69,"q":"高血壓患者飲食需注意事項，下列何者正確？","o":["採用低油、低鹽的飲食","多喝牛奶、吃小魚乾","多吃動物性蛋白質的食物","植物性奶油因為是植物性的，多吃沒關係"],"a":1,"e":"高血壓飲食原則是低油、低鹽（低鈉）。"},{"c":0,"n":70,"q":"對於皮膚發癢的老年案主，下列哪一措施不適當？","o":["用指腹按摩患部","以中性的肥皂清潔","每天以熱水洗澡，清潔皮膚","協助塗抹醫師處方的止癢藥"],"a":3,"e":"天天用熱水洗澡會洗去油脂，使老人皮膚更乾癢。"},{"c":0,"n":71,"q":"幫案主執行沐浴清潔時須要注意的事項，下列何者是正確的？A.關閉門窗，調節室溫在22-26℃B.任何時間皆可執行清潔C.先清潔軀幹→四肢→頭頸部D.注意觀察案主的身體有無異常現象","o":["AB","BC","DC","AD"],"a":4,"e":"沐浴前應關窗、維持室溫22～26℃，並在過程中觀察皮膚有無異常。"},{"c":0,"n":72,"q":"協助案主由臥姿改為坐姿的步驟為：A.將案主抬起B.使案主仰臥，曲雙膝C.協助者托起案主肩及腰D.請案主雙手抱住協助者的頸後，其正確順序為","o":["B→C→D→A","A→C→B→D","B→D→C→A","C→A→D→B"],"a":3,"e":"正確順序：仰臥屈膝→案主雙手環抱協助者頸後→托起肩與腰→扶起。"},{"c":0,"n":73,"q":"有關執行被動運動的目的，下列何者不正確？","o":["預防患側肌肉攣縮","預防患側關節僵直","增進健側關節的活動度","增加患部肌肉協調能力"],"a":3,"e":"被動運動的對象是患側，目的在預防攣縮與僵直，不是增進健側活動度。"},{"c":0,"n":74,"q":"下列何者不是按摩的禁忌？","o":["惡性腫瘤","急性發炎","輕微水腫","靜脈栓塞"],"a":3,"e":"輕微水腫可以按摩促進回流；惡性腫瘤、急性發炎、靜脈栓塞都是按摩禁忌。"},{"c":0,"n":75,"q":"對手肘的關節活動可執行的動作，何者為正確？A.內收B.屈曲C.伸展D.外展","o":["AB","BC","CD","AD"],"a":2,"e":"手肘為屈戌關節，只能屈曲與伸展。"},{"c":0,"n":76,"q":"有關按摩的注意事項，下列何者不正確？","o":["服務員應保持雙手溫暖","可配合塗抹冷霜或滑石粉","動作應溫和而有頻率，並且注意案主的反應","於案主吃飽飯後馬上進行按摩可幫助消化"],"a":4,"e":"飯後馬上按摩會影響消化，應在飯後1小時再進行。"},{"c":0,"n":77,"q":"照顧服務員用兩手握住案主的手腕，旋轉案主手掌，轉向臉部，然後轉向足部，是屬於何種運動？","o":["肩部運動","大拇指運動","手腕迴轉運動","手腕前後彎曲運動"],"a":3,"e":"手掌向臉部再轉向足部的動作是手腕（前臂）旋轉運動。"},{"c":0,"n":78,"q":"下列哪個年齡層之體溫較低？","o":["成年","老年","青少年","幼兒"],"a":2,"e":"老年人基礎代謝率低，體溫較年輕人低。"},{"c":0,"n":79,"q":"使用熱水袋的目的有哪些？A.保暖B.減輕疼痛C.促進血液循環D.減輕發炎症狀","o":["ABD","ACD","BCD","ABC"],"a":4,"e":"熱水袋可保暖、減輕疼痛、促進循環；急性發炎時不宜使用熱敷。"},{"c":0,"n":80,"q":"糞便嵌塞的症狀，下列何者正確？","o":["血壓變低","腹部柔軟","呼吸變緩慢","噁心、嘔吐"],"a":4,"e":"糞便嵌塞會引起腹脹、噁心、嘔吐，甚至滲出水樣便。"},{"c":0,"n":81,"q":"便秘時應給予案主何種腹部按摩方式，以促進排便？","o":["無特定方向","由右往上橫向左側","由左往上橫向右側","左一次，右一次輪流方式"],"a":2,"e":"順著大腸走向（升結腸→橫結腸→降結腸）由右下往上、橫向左再往下，即順時鐘按摩。"},{"c":0,"n":82,"q":"幫案主灌腸時，應協助患者採何種臥位？","o":["仰臥並伸直其雙腳","仰臥並彎曲其雙腳","左側臥並彎曲其右腳","右側臥並彎曲其左腳"],"a":3,"e":"灌腸採左側臥、右腳彎曲，順著乙狀結腸與降結腸的走向，溶液較易流入。"},{"c":0,"n":83,"q":"固定尿管或鼻管的紙膠應多久更換一次？","o":["有脫落時再更換","每二天更換一次","至少每天更換一次","每一星期更換一次"],"a":3,"e":"紙膠至少每天更換並換位置黏貼，避免皮膚受損與管路滑脫。"},{"c":0,"n":84,"q":"關於口腔護理的目的，下列何者不正確？","o":["預防細菌在口腔滋生","可早期發現口腔疾病","只針對無法自行清理的病人","教導案主執行有效的口腔清潔方法"],"a":3,"e":"口腔護理適用所有人，不是只針對無法自理的案主。"},{"c":0,"n":85,"q":"被照顧者大便顏色出現黑色時，有可能發生的相關疾病為","o":["痔瘡","便秘","上腸胃道出血","下腸胃道出血"],"a":3,"e":"上消化道出血，血液經胃酸作用後會變成黑色柏油便。"},{"c":0,"n":86,"q":"為案主清潔牙齒刷牙的正確方式為","o":["刷毛與牙齒呈 45〜60 度角","由牙冠向牙齦刷","由左向右每次刷 5〜6 顆牙齒","不宜清除舌苔"],"a":1,"e":"刷牙時刷毛與牙齒呈45～60度，由牙齦往牙冠刷，並清潔舌苔。"},{"c":0,"n":87,"q":"協助案主獲得舒適的措施，下列何者不正確？","o":["保持身體清潔","維持合宜的姿勢","注意四周環境的清潔","用力拉平案主的衣服"],"a":4,"e":"用力拉扯衣服會造成皮膚摩擦受傷，應輕柔整理。"},{"c":0,"n":88,"q":"幫案主清潔臉部、修面鬍鬚，何者不正確？","o":["刀刃與剃薙的部位應成 60 〜70 度","先用溫熱毛巾敷臉，以軟化鬍鬚","一手繃緊皮膚，以順毛的方向剃","清潔完後可塗抹乳霜，增進舒適感"],"a":1,"e":"刮鬍刀與皮膚約成45度角，角度太大容易刮傷。"},{"c":0,"n":89,"q":"有關正常尿液特性，下列何者不正確？","o":["pH 呈弱鹼性","顏色為淡黃色","大約 4 小時解 1～2 次","每次解尿量約為 200～400 西西"],"a":1,"e":"正常尿液呈弱酸性（約pH 6），不是弱鹼性。"},{"c":0,"n":90,"q":"被照顧者解鮮紅色血便時，可能身體那個部位有異常？","o":["胃","小腸","肝臟","大腸"],"a":4,"e":"鮮紅色血便多來自下消化道，如大腸、直腸或痔瘡出血。"},{"c":0,"n":91,"q":"下列敘述何者不正確？","o":["男性案主會陰沖洗後應將包皮推回","協助案主使用便盆時，應注意個案的隱私，保暖與安全","會陰沖洗每次最多只能使用四支沖洗棉棒，以免皮膚因沖洗而破損","女性案主會陰沖洗的次序為：尿道口、陰道口、小陰唇、大陰唇、外陰部"],"a":3,"e":"會陰沖洗的棉棒數量依需要使用，每支只擦一次，沒有最多四支的限制。"},{"c":0,"n":92,"q":"身體的四大排泄途徑為：A.大腸B.皮膚C.心臟D.肺臟E.泌尿系統F.神經系統","o":["ABCD","ABCE","ABDE","CDEF"],"a":3,"e":"四大排泄途徑：大腸（糞便）、皮膚（汗）、肺（二氧化碳）、泌尿系統（尿）。"},{"c":0,"n":93,"q":"使用便盆的注意事項，下列何者正確？A.常用的便盆消毒是以酒精擦拭，B.案主使用便盆時，應給案主叫人鈴，C.傳染病的案主其便盆使用後，應放於公共便盆架上，以保持通風，D.若有不正常之排泄物，應將排泄物保留，以提供護理人員或醫師觀察","o":["BD","AD","AC","BC"],"a":1,"e":"使用便盆時應給叫人鈴，異常排泄物要保留給醫護觀察；傳染病患者的便盆應專用並消毒。"},{"c":0,"n":94,"q":"鋪換床單的原則，下列何者不正確？","o":["先鋪床頭再鋪床尾","換下的床單不可置於地上，也要避免抱在身上","工作者需保持良好姿勢，鋪床時應使用肩背的力量","避免以抽拉的方式換下床單，以免造成個案皮膚受損"],"a":3,"e":"鋪床應利用腿部力量並保持背部挺直，不是用肩背的力量。"},{"c":0,"n":95,"q":"下列哪一種案主不須要協助其執行口腔清潔？","o":["病重案主","意識不清者","早期的失智症案主","無法自行執行口腔清潔案主"],"a":3,"e":"早期失智症案主多半仍能自行刷牙，可以提醒、鼓勵自己做。"},{"c":0,"n":96,"q":"會陰清潔的目的，下列何者不正確？","o":["增進美觀","除去異味","預防感染","促進會陰部傷口的癒合"],"a":1,"e":"會陰清潔的目的是除臭、預防感染、促進癒合，不是為了美觀。"},{"c":0,"n":97,"q":"依馬斯洛學說，人類最低層次的需要是","o":["生理的需要","安全的需要","愛與所屬感的需要","自尊的需要"],"a":1,"e":"馬斯洛需求層次最基礎的是生理需要（飲食、排泄、睡眠等）。"},{"c":0,"n":98,"q":"對於夜間常常醒來上廁所的案主，下列何者為適當的照顧措施？","o":["給予安眠藥","這是老人的毛病，不要去理會","說明這是新入住住民的現象","鼓勵就寢前先上廁所，並準備移動式便器在床邊"],"a":4,"e":"睡前先上廁所、床邊放置便器，可減少夜間跌倒風險。"},{"c":0,"n":99,"q":"下列神經系統的構造中，何者可維持身體的平衡與運動功能？","o":["大腦","小腦","腦幹","間腦"],"a":2,"e":"小腦負責維持平衡與協調動作。"},{"c":0,"n":100,"q":"案主噁心嘔吐時，下列那一項措施不適當？","o":["嘔吐後給予清潔口腔","房間內噴灑除臭劑","避免突然移動案主","協助案主採側臥姿勢"],"a":2,"e":"嘔吐後應開窗通風，噴除臭劑的刺激氣味可能加重噁心。"},{"c":0,"n":101,"q":"有關案主咳嗽的照顧措施，下列那一項不適當？","o":["給予喝溫熱開水","依醫囑給止咳藥","喝止咳藥水後，立刻喝大量開水","讓案主坐起輕輕拍他的背部"],"a":3,"e":"喝止咳糖漿後不宜立刻大量喝水，以免沖淡藥效。"},{"c":0,"n":102,"q":"有關壓瘡的照護措施，下列何者有誤？","o":["減少皮膚受壓的時間","衣服和床單保持平整與乾燥","利用枕頭、墊子以減輕骨突處受壓","露出潰瘍處皮膚以利其乾燥"],"a":4,"e":"壓瘡傷口應依醫護指示覆蓋敷料保持濕潤環境，不應暴露。"},{"c":0,"n":103,"q":"有關體溫上升的原因，下列何者正確？","o":["會受測量部位、年齡與環境的影響","與憤怒、恐懼、緊張的情緒無關","與體內荷爾蒙的釋放量無關","不受細菌或病毒入侵的影響"],"a":1,"e":"體溫會因測量部位、年齡與環境而有差異。"},{"c":0,"n":104,"q":"有關脈搏的敘述，下列何者有誤？","o":["年齡愈小，脈搏愈快","男性脈搏比女性快","壓力大，情緒激動時脈搏加快","平躺時脈搏次數減少"],"a":2,"e":"一般女性脈搏略快於男性，「男性比女性快」是錯的。"},{"c":0,"n":105,"q":"鼓勵被照顧者參與日常活動的目的，下列哪一項不正確？","o":["可減輕照顧者的體力消耗","有助被照顧者早日恢復健康","避免筋骨退化萎縮","保持皮膚的完整性"],"a":1,"e":"鼓勵參與日常活動是為了被照顧者的健康與功能，不是為了減輕照顧者負擔。"},{"c":0,"n":106,"q":"有關使用輪椅的敘述，下列何者不適宜？","o":["經常檢查輪胎中的空氣量","輪胎軸承和轉動部分常加潤滑劑","坐輪椅的姿勢，背部要平直","坐輪椅前，先踩腳踏板後坐下"],"a":4,"e":"坐輪椅前應先將腳踏板翻起並固定煞車，踩著腳踏板坐下容易翻倒。"},{"c":0,"n":107,"q":"正確的洗手步驟為：A.沖；B.搓；C.溼；D.捧；E.擦，下列組合順序，何者正確？","o":["ABCDE","ACBDE","ADCBE","CBADE"],"a":4,"e":"洗手口訣「濕、搓、沖、捧、擦」。"},{"c":0,"n":108,"q":"老人最易缺乏的礦物質為","o":["鈣","磷","鉀","鐵"],"a":1,"e":"老人最容易缺乏鈣質，易造成骨質疏鬆。"},{"c":0,"n":109,"q":"一般老年人的營養攝取，下列何者不適宜？","o":["攝取多樣化食物","食用不飽和高脂肪酸的植物油","避免攝取大量動物內臟、魚卵、貝類","食用少纖維、精製食品"],"a":4,"e":"老人應攝取高纖維、未精製的食物，少纖維精製食品容易便秘。"},{"c":0,"n":110,"q":"預防骨骼鈣質的流失，除了鼓勵多吃小魚乾、乳製品外，還需要攝取","o":["鉀","鎂","維生素 D","維生素 K"],"a":3,"e":"維生素D能幫助腸道吸收鈣質。"},{"c":0,"n":111,"q":"有關安全照顧措施的描述，下列何者不正確？","o":["工作前後都洗手","室內防輻射與噪音","用正確的護理技術照顧病人","病人單位都放高劑量消毒水"],"a":4,"e":"消毒水依需要適量使用，高劑量會刺激呼吸道與皮膚。"},{"c":0,"n":112,"q":"下列那一項照顧措施可能會傷害案主？","o":["協助案主下床時降低床高度","未立即回應病人的呼叫","地板的水立即擦乾","提供以案主為中心的照顧"],"a":2,"e":"未立即回應呼叫，可能使案主自行下床而跌倒，或延誤處理。"},{"c":0,"n":113,"q":"下列何者是口腔清潔的目的：A.盡量刺激口腔粘膜或牙肉，以增強咀嚼肌肉；B.促進唾液的分泌；C.使義齒較好用；D.將口內食物殘渣清除以免細菌繁殖","o":["AB","BC","BD","AD"],"a":3,"e":"口腔清潔可促進唾液分泌、清除食物殘渣以免細菌孳生。"},{"c":0,"n":114,"q":"被照顧者睡不著，適當的處理方法為？","o":["吃晚餐後給予洗腳","給予指壓、按摩，使被照顧者身心放鬆","白天不准午睡","告訴被照顧者深夜時他都在睡"],"a":2,"e":"指壓、按摩能幫助身心放鬆，較容易入睡。"},{"c":0,"n":115,"q":"對睡眠有問題者的照顧措施，何者不適當？","o":["白天帶他活動到耗盡體力","白天給予休閒活動，舒解情緒","睡前沐浴或泡腳","在床旁陪伴增進安全感"],"a":1,"e":"白天活動到耗盡體力反而會過度疲累、影響睡眠，應適度活動。"},{"c":0,"n":116,"q":"有關協助病人身體舒適的措施，下列何者最完整？A.保持身體的清爽；B.調節適當的室溫；C.多認識病房的工作人員；D.維持良好姿勢","o":["AB","BC","ABC","ABD"],"a":4,"e":"舒適措施包括身體清爽、適當室溫、良好姿勢；認識工作人員與身體舒適無關。"},{"c":0,"n":117,"q":"滅菌後的物品不再度污染乃指？","o":["送物品去消毒","送物品去洗淨","將滅菌後的東西不與未消毒物接觸","不要使任何人摸到物品"],"a":3,"e":"滅菌物品保持無菌，就是不和未消毒的物品接觸。"},{"c":0,"n":118,"q":"用酒精作消毒液的濃度為下列何者較佳？","o":["100％","95％","85％","75 ％"],"a":4,"e":"75%酒精的殺菌效果最好；濃度太高會使菌體表面蛋白質迅速凝固，反而無法滲入殺菌。"},{"c":0,"n":119,"q":"有關手術後放置導尿管案主的照顧，下列何者適當？","o":["尿內有浮游物，請醫師即時沖洗膀胱","準確記錄輸出入量表","避免清洗會陰部","指導案主盡量不要喝水"],"a":2,"e":"導尿管案主應準確記錄攝入量與排出量。"},{"c":0,"n":120,"q":"人體的呼吸中樞位於","o":["下視丘","延腦","小腦","中腦"],"a":2,"e":"呼吸中樞位於延腦。"},{"c":0,"n":121,"q":"有關大小便失禁案主的護理，下列何者不適當？","o":["整天包紙尿褲比較衛生","每日至少協助案主下床一次","案主應避免便秘情形","定時協助案主入廁"],"a":1,"e":"整天包尿褲易使皮膚潮濕發炎並失去排尿訓練機會，應定時如廁。"},{"c":0,"n":122,"q":"檢查成人是否有耳垢時應輕輕將耳朵","o":["向上向後拉","向下向後拉","向上向前拉","向下向前拉"],"a":1,"e":"成人檢查耳道時將耳廓向上向後拉，可拉直耳道；兒童則向下向後拉。"},{"c":0,"n":123,"q":"執行成人心肺復甦術(CPR)及自動體外心臟除顫器(AED)時，下列處置何者正確？a.只有一位施救者時，先請人打電話求救，再進行五個循環的CPR b.若沒有呼吸或幾乎沒有呼吸，即放棄胸外按摩c.AED到達後，黏上貼片，打開機器，聽從AED指示操作d.壓胸深度，至少要超過6公分","o":["ab","bc","ac","bd"],"a":3,"e":"單人施救時先求救、取得AED；AED到達後貼片開機並依語音操作。沒有正常呼吸正是需要壓胸的指標；壓胸深度約5～6公分。"},{"c":0,"n":124,"q":"有關口腔衛生方面，下列何者正確？a.最好每餐飯後立即刷牙或漱口；b.每天最少刷牙一次；c.含糖份的飲料應儘快喝完並漱口；d.插胃管的案主不必執行口腔清潔","o":["abc","acd","bcd","abd"],"a":1,"e":"每餐飯後刷牙漱口、每天至少刷牙一次、喝含糖飲料後漱口；插鼻胃管者仍需口腔清潔。"},{"c":0,"n":125,"q":"有關心臟病案主的照護，下列敘述何者正確？a.不可以運動b.依醫囑在可忍受範圍內運動c.依每日情況決定吃藥種類d.依醫囑按時服藥","o":["ab","ac","bc","bd"],"a":4,"e":"心臟病患者應依醫囑在可忍受範圍內運動，並依醫囑按時服藥。"},{"c":0,"n":126,"q":"有關糖尿病案主的照護，下列敘述何者正確？","o":["只要有頭暈的現象，就表示血糖低","絕不可吃糖","只要多運動並注意飲食，就可不吃藥","要經常監測血糖"],"a":4,"e":"糖尿病照護最重要的是經常監測血糖。"},{"c":0,"n":127,"q":"接受定期洗腎(血液透析)被照顧者的飲食應注意事項A.盡量選用天然食物，禁用醃製、罐頭及加工食品；B.可以大吃大喝；C.注意高鉀食物，如楊桃汁勿食；D.依醫囑限水","o":["ABC","BCD","ACD","ABD"],"a":3,"e":"洗腎患者應少吃加工食品、避免高鉀食物（楊桃也可能有毒性），並依醫囑限水。"},{"c":0,"n":128,"q":"糖尿病案主有低血糖發生時，下列處置何者不正確？","o":["立即給予單糖","案主清醒時請他吃一份正常餐","送醫處理","立即服用降血糖藥"],"a":4,"e":"低血糖時再吃降血糖藥會使血糖更低，非常危險。"},{"c":0,"n":129,"q":"老年案主晚上睡不著覺時，下列處置何者不正確？","o":["立即給予安眠藥","在不影響他人情況下，起床活動筋骨","在不影響他人情況下，看書或看電視","喝杯溫熱牛奶以幫助睡眠"],"a":1,"e":"失眠不應立刻給安眠藥，應先用非藥物方法，用藥需依醫囑。"},{"c":0,"n":130,"q":"有關糖尿病案主的照護，下列何者組合正確？a.不定期監測血糖b.定時服藥c.規律運動d.飲食控制","o":["abc","bcd","acd","abd"],"a":2,"e":"糖尿病照護：定時服藥、規律運動、飲食控制，並要「定期」監測血糖。"},{"c":0,"n":131,"q":"案主的大便沾鮮血時，可能的原因為：a.痔瘡b.便秘c.胃出血d.食道出血","o":["ab","bc","ac","ad"],"a":1,"e":"大便表面沾鮮血多為痔瘡或便秘造成的肛門裂傷；胃、食道出血會呈黑便。"},{"c":0,"n":132,"q":"案主解黑色便時可能的原因為：a.綠色蔬菜吃太多b.上腸胃道出血c.吃鐵劑d.吃鴨血糕","o":["abc","acd","bcd","abd"],"a":3,"e":"上消化道出血、服用鐵劑、吃鴨血糕都可能使大便變黑。"},{"c":0,"n":133,"q":"預防案主（非限水個案）便秘的方法包括下列哪些？a.多喝水、b.多吃高纖維食物、c.多吃精緻食品、d.多運動","o":["abc","acd","bcd","abd"],"a":4,"e":"預防便秘：多喝水、多吃高纖食物、多運動；精緻食品纖維少。"},{"c":0,"n":134,"q":"下列有關案主排便的敘述，何者正確？","o":["每天應解便一次","一天沒解便就是便秘","只解三次稀便不稱為腹瀉","每個人有不同的解便習慣，應先瞭解再判斷"],"a":4,"e":"每個人排便習慣不同，應先了解平時習慣再判斷是否異常。"},{"c":0,"n":135,"q":"下列有關被照顧者的進食水分的敘述何者不正確？","o":["平常每天應喝水 2000-2500cc","特殊需限水的被照顧者應依照醫囑指示","多吃水果，且越多越好","菜湯或稀飯都應納入每日飲水量的計算"],"a":3,"e":"水果吃太多會攝取過多糖分，腎臟病患者還要注意鉀，並非越多越好。"},{"c":0,"n":136,"q":"使用留置尿管的被照顧者，滲尿的可能原因，何種不正確？","o":["大便嵌塞","尿管太小","尿管被折或壓到","腹壓增加"],"a":2,"e":"尿管太小不是滲尿原因；大便嵌塞、管路受壓、腹壓增加才會造成滲尿。"},{"c":0,"n":137,"q":"使用留置尿管的案主，滲尿時的處理方法，以下何者不正確？","o":["將尿管的氣球再打些空氣/水進去","檢查尿管通路","給案主一個舒適位置","檢查大便紀錄"],"a":1,"e":"尿管水球的水量不可由照服員自行增加，應報告護理人員處理。"},{"c":0,"n":138,"q":"有關失智症案主床的設置，下列何者正確？","o":["不論案主病情均須以床欄保護，以防跌落","高度與案主的病情配合","依一般標準床高度","附約束帶"],"a":2,"e":"床的高度應配合病情；不是一律使用床欄或約束。"},{"c":0,"n":139,"q":"與失智症案主相處時，下列何者正確？","o":["尊重案主，給予多重事項的選擇","為防走失，均給予約束","當案主固執在某一觀點時，應矯正其錯誤","談話時多使用肯定句，而非模擬兩可"],"a":4,"e":"與失智者說話要簡單明確，多用肯定句，避免讓他做太多選擇。"},{"c":0,"n":140,"q":"給予案主沐浴的適當時間為何？","o":["餐後立即洗","餐後半小時洗","餐後 1 小時洗","任何時間洗"],"a":3,"e":"沐浴宜在餐後1小時，避免影響消化。"},{"c":0,"n":141,"q":"有關案主發燒在家的一般處理原則，下列何者不正確？","o":["立即給予退燒藥","多喝水","給冰枕","調整衣服被蓋"],"a":1,"e":"發燒不應立即自行給退燒藥，應先物理降溫並依醫囑處理。"},{"c":0,"n":142,"q":"當血壓下降時脈搏","o":["會改變","不會改變","因人而異","因時而異"],"a":1,"e":"血壓下降時，身體會代償使脈搏加快，因此脈搏會改變。"},{"c":0,"n":143,"q":"脈搏不規則的被照顧者，至少應測量脈搏","o":["60 秒","30 秒","15 秒","5 秒"],"a":1,"e":"脈搏不規則時要測量滿60秒才準確。"},{"c":0,"n":144,"q":"案主坐輪椅時，下列組合何者正確a.將臀部移入輪椅內側b.每小時讓臀部壓力紓解約1分鐘c.坐多久隨案主決意d.雙腳平放於地面或踏板","o":["abc","acd","bcd","abd"],"a":4,"e":"坐輪椅時臀部要坐到底、每小時減壓約1分鐘、雙腳平放在踏板；不能讓案主想坐多久就坐多久。"},{"c":0,"n":145,"q":"幫案主翻身時，a.應卸下近身側床欄b.為案主安全不可卸下任何床欄c.儘量遠離案主身體以免弄髒衣服d.先告知要幫忙翻身，以下組合何者正確？","o":["ab","ac","ad","cd"],"a":3,"e":"翻身前先告知案主，並卸下靠近自己這側的床欄以便操作。"},{"c":0,"n":146,"q":"尿褲使用案主，在多日腹瀉下，導致臀部肛門口發紅，以下處理方式何者不對？","o":["以清水棉紙清洗肛門口及臀部","以衛生紙塞住肛門口，以減少清洗次數","在顧及案主隱私下，以尿片取代尿褲，讓臀部透風","在發紅部位擦上氧化鋅護膚霜"],"a":2,"e":"用衛生紙塞住肛門口會刺激黏膜並造成感染，是錯誤做法。"},{"c":0,"n":147,"q":"訓練排便最好的時間","o":["早餐後","午餐後","晚餐後","任何時間"],"a":1,"e":"早餐後有胃結腸反射，腸蠕動最強，是訓練排便的最佳時機。"},{"c":0,"n":148,"q":"照顧下肢水腫被照顧者時，下列何者不正確？","o":["教導坐下時將腳抬高","教導躺下時將腳抬高於心臟","由遠心端朝近心端按摩","由近心端向遠心端按摩"],"a":4,"e":"按摩應由遠心端往近心端，順著靜脈回流方向。"},{"c":0,"n":149,"q":"移動案主時為免照服員受傷，下列何者不正確？","o":["卸下床欄","身體重心落於兩腳中間","儘量靠近案主","儘量拉長腰"],"a":4,"e":"移動案主時應靠近、保持背部挺直、屈膝，不可拉長腰部。"},{"c":0,"n":150,"q":"照顧意識不清被照顧者，下列組合何者不正確？A.不必與他談話；B.雖沒反應仍要跟他說話；C.隨自己高興，決定說話與否；D.有他人在時不可與他談話以免被認為神經病","o":["ABC","BCD","ACD","ABD"],"a":3,"e":"意識不清者仍可能聽得到，應持續與他說話；A、C、D都是錯誤觀念。"},{"c":0,"n":151,"q":"案主多久沒解小便就應注意","o":["2 小時","4 小時","6 小時","8 小時"],"a":2,"e":"超過4小時沒有排尿就應注意，是否有尿液滯留或攝水不足。"},{"c":0,"n":152,"q":"案主腹瀉時，應注意a.味道b.顏色型態c.量d.次數e.軟硬，下列何種組合正確？","o":["abcd","bcde","acde","abde"],"a":1,"e":"腹瀉時要觀察糞便的味道、顏色性狀、量與次數。"},{"c":0,"n":153,"q":"當腹瀉發生時，應採取下列哪一個方法？","o":["增加食物攝入","刺激腸蠕動","加速病菌的排出","減少食物攝入"],"a":4,"e":"腹瀉時應減少食物攝入，讓腸道休息。"},{"c":0,"n":154,"q":"被動運動下列敘述何者正確？","o":["對案主是有益的","每次執行時間越久越好","沒用的","每天做一次即可"],"a":1,"e":"被動運動可維持關節活動度，對無法自主活動者有益。"},{"c":0,"n":155,"q":"使用熱水袋應注意事項，下列何者錯誤？","o":["注意使用時間","放於需使用的部位","禁止用於頭、胸部","不必注意案主反應"],"a":4,"e":"使用熱水袋必須隨時觀察案主反應，避免燙傷。"},{"c":0,"n":156,"q":"老年人易得骨質疏鬆症的原因有a.血壓高b.鈣質攝取不夠c.缺乏運動d.賀爾蒙改變，下列何者組合正確？","o":["abc","bcd","acd","abd"],"a":2,"e":"骨質疏鬆與鈣質不足、缺乏運動、荷爾蒙改變有關，與高血壓無關。"},{"c":0,"n":157,"q":"導致高血壓的因素很多，下列何者屬於內在因素A.血液黏稠度高B.情緒激動C.高膽固醇D.高三酸甘油酯","o":["ABC","BCD","ACD","ABD"],"a":3,"e":"血液黏稠、高膽固醇、高三酸甘油酯屬內在因素；情緒激動屬外在因素。"},{"c":0,"n":158,"q":"發現案主解的大便是黏液狀，可能原因是","o":["腸胃脹氣","糞便填塞","大便失禁","痔瘡"],"a":2,"e":"糞便填塞時，上方的液狀或黏液狀糞便會從周圍滲出。"},{"c":0,"n":159,"q":"易得血栓靜脈炎的因素有a.長期臥床不動；b.血液黏稠度高；c.血管硬化；d.多執行主動運動或被動運動","o":["abc","bcd","acd","abd"],"a":1,"e":"長期臥床、血液黏稠、血管硬化都是血栓的危險因素；運動則能預防。"},{"c":0,"n":160,"q":"以鼻胃管為案主灌食牛奶後，沖洗鼻胃管最合適的水量為","o":["10cc","100cc","200cc","至無牛奶殘留於管壁"],"a":4,"e":"灌食後要以溫開水沖淨管壁至無牛奶殘留，以免阻塞與細菌孳生。"},{"c":0,"n":161,"q":"協助被照顧者作被動運動時應A.採取舒適姿勢；B.運動部位盡量靠近自己，以免費力、拉扯；C.運動部位前後關節應予適當支托；D.背向被照顧者以免尷尬","o":["ABC","BCD","ACD","ABD"],"a":1,"e":"被動運動時採舒適姿勢、運動部位靠近自己、支托關節前後；應面向被照顧者觀察反應。"},{"c":0,"n":162,"q":"協助案主作被動運動時應","o":["時間越久越好","力量越大越好","幅度越大越好","規律運動"],"a":4,"e":"被動運動貴在規律持續，不是越久、越大力越好。"},{"c":0,"n":163,"q":"單側下肢乏力案主上下階梯時應教導","o":["患肢先上","隨自喜好","健肢後上","健肢先上"],"a":4,"e":"上樓「好腳先上」，下樓「壞腳先下」。"},{"c":0,"n":164,"q":"容易導致壓瘡的情境，下列何者不正確？","o":["長時間臥床不動","皮膚衛生不良","營養不良","床鋪太平整"],"a":4,"e":"床鋪平整可減少摩擦與局部受壓，不會導致壓瘡。"},{"c":0,"n":165,"q":"有關老人皮膚系統，下列敘述何者不正確？","o":["汗腺數量增加","癒合速度減慢","皮膚容易破皮","指甲變厚易脆"],"a":1,"e":"老人汗腺數量減少，排汗與散熱能力下降。"},{"c":0,"n":166,"q":"呼吸系統的老化改變，下列敘述何者正確？","o":["肺餘容積減少","肺活量減少","氣體交換容量增加","咳嗽有效性增加"],"a":2,"e":"老化使肺彈性下降，肺活量減少、肺餘容積增加。"},{"c":0,"n":167,"q":"老人的感覺功能會有下列那些改變？","o":["需要較暗的光線避免刺激","內耳神經元增加以避免聽力喪失","神經功能退化速度不一","全部的老人都有聽力喪失的現象"],"a":3,"e":"老化程度因人而異，各種神經功能退化速度也不一樣。"},{"c":0,"n":168,"q":"有關人類認知功能的改變，下列敘述何者不正確？","o":["精神活動在 20 歲的高峰之後穩定下降","每位老人都有認知功能障礙的情形","老人記憶減退是可藉由言語或書面提示來協助","老人的空間知覺感較年輕人差"],"a":2,"e":"不是每位老人都有認知障礙，認知退化存在個別差異。"},{"c":0,"n":169,"q":"老人血管系統的變化，下列敘述何者不正確？","o":["動脈的伸張與擴張能力下降","動脈壁管徑變小","動脈管壁變厚","血壓值的記錄方式為舒張壓/收縮壓"],"a":4,"e":"血壓記錄方式是「收縮壓/舒張壓」。"},{"c":0,"n":170,"q":"處理案主便秘的問題，下列措施何者不適當？","o":["臥床的案主，抬高床頭可幫助排便","每日攝取 2000~3000 cc 的液體","解便時由下往上按摩腹部","維持隱密性"],"a":3,"e":"按摩應順結腸方向（右下往上→橫向左→往下），不是由下往上。"},{"c":0,"n":171,"q":"有關老人呼吸系統的敘述，下列何者不正確？","o":["正常範圍是 12〜20 次/分","呼吸與脈博之比約為 1：4","溫度高時，呼吸次數會減少","若大量失血，呼吸次數會增加"],"a":3,"e":"體溫升高時代謝增加，呼吸次數會增加，不會減少。"},{"c":0,"n":172,"q":"促進有效咳嗽的步驟，下列敘述何者不適當？","o":["採取坐姿","利用枕頭支托胸部及腹部","深呼吸後，連續咳嗽 5 次","腦損傷的案主要特別注意"],"a":3,"e":"有效咳嗽是深呼吸後用力咳2～3次，連續咳5次會太疲累。"},{"c":0,"n":173,"q":"有關褥瘡的敘述，下列何者不適當？","o":["失禁的病人容易發生","受壓時間的長短是主要影響因素","坐輪椅的病人發生褥瘡的機會較低","與營養不足有關"],"a":3,"e":"坐輪椅者臀部與尾骶骨長期受壓，同樣容易發生褥瘡。"},{"c":0,"n":174,"q":"下列何者不是急性心肌梗塞的症狀？","o":["胸痛","出汗","臉色發紅","血壓下降"],"a":3,"e":"心肌梗塞常見胸痛、冒冷汗、血壓下降，臉色多為蒼白，不是發紅。"},{"c":0,"n":175,"q":"下列有關發燒的臨床表徵，何者有誤？","o":["口渴","倦怠","代謝率增加","尿量增加"],"a":4,"e":"發燒時水分經皮膚與呼吸流失，尿量會減少。"},{"c":0,"n":176,"q":"王老先生腹漲不適，下列哪項處理措施不適當？","o":["進食時鼓勵放輕鬆","鼓勵多喝牛奶","避免豆類食品","避免使用吸管"],"a":2,"e":"很多老人有乳糖不耐，喝牛奶容易脹氣；腹脹時應避免。"},{"c":0,"n":177,"q":"用餐時王媽媽表示想上廁所，以下處理何者正確？","o":["告知吃飯時間說這個很不衛生","告知吃飽飯再去","立即帶去廁所","告知已包了尿褲直接尿下去就行了"],"a":3,"e":"案主想上廁所應立即協助，延遲可能造成失禁或尊嚴受損。"},{"c":0,"n":178,"q":"下列何者為排便的三大要素？A.直腸收縮力；B.腹壓；C.重力；D.自然反射","o":["ABC","ACD","BCD","ABD"],"a":1,"e":"排便三要素：直腸收縮力、腹壓、重力。"},{"c":0,"n":179,"q":"下列觀念何者正確？","o":["老王因年齡較長感覺變遲鈍、尿道括約肌較鬆弛，所以應給予穿尿褲","巴金森氏症患者即使可感覺尿液，但因無法馬上行動，應給予尿褲使用","失智症患者應給予尿褲使用","半身癱瘓的中風患者可提供排尿訓練"],"a":4,"e":"半身癱瘓的中風患者仍可接受排尿訓練，不應一律包尿褲。"},{"c":0,"n":180,"q":"協助坐在桌旁的案主用餐的最好位置是在","o":["坐在案主旁邊","坐在案主對面","站著以利移動","隨意，方便即可"],"a":1,"e":"坐在案主旁邊協助用餐，方便操作與觀察，也比較不會有壓迫感。"},{"c":0,"n":181,"q":"協助餵食時a.讓案主身體往前微傾b.食物由上往下餵c.食物由下往上餵d.給予時間慢慢咀嚼","o":["abc","acd","bcd","abd"],"a":2,"e":"餵食時身體微前傾、食物由下往上送入口中、給予足夠時間咀嚼。"},{"c":0,"n":182,"q":"活動假牙的清潔a.每餐後以軟毛牙刷清洗；b.漱口即可；c.用假牙清潔劑泡即可；d.與醫師討論晚上是否卸下假牙","o":["ab","ac","bc","ad"],"a":4,"e":"活動假牙每餐飯後以軟毛牙刷清洗，晚上是否取下要與醫師討論。"},{"c":0,"n":183,"q":"影響血壓的外在因素有A.情緒；B.睡眠；C.溫度；D.測量技術，下列何者組合正確？","o":["ABC","ACD","BCD","ABD"],"a":1,"e":"情緒、睡眠、溫度是影響血壓的外在因素；測量技術影響的是測量值的準確度。"},{"c":0,"n":184,"q":"照服員服務案主時應","o":["有事弟子服其勞，不讓案主動手做事","尊重案主自主權，從旁協助","隨意，案主叫的時候才去幫忙","家屬在時，盡力幫忙"],"a":2,"e":"應尊重案主自主權，能自己做的讓他自己做，從旁協助。"},{"c":0,"n":185,"q":"下列吞嚥的哪幾期是無法自主性控制？A.口腔準備期B.口腔期C.咽喉期D.食道期","o":["AB","BC","CD","BD"],"a":3,"e":"咽喉期與食道期屬反射動作，無法自主控制。"},{"c":0,"n":186,"q":"下列哪一現象表示個案可能有吞嚥困難？","o":["很口渴","體重減輕","體重增加","腹脹"],"a":2,"e":"吞嚥困難使進食量減少，會出現體重減輕。"},{"c":0,"n":187,"q":"吃東西時食物會掉在臉頰內(齒頰)兩側，這是哪一期的吞嚥困難？","o":["口腔準備期","口腔期","咽喉期","食道期"],"a":2,"e":"食物殘留在兩頰，是舌頭運送食物有困難的口腔期問題。"},{"c":0,"n":188,"q":"吃東西後，喉嚨癢癢的想咳嗽且咳出食物，這是哪一期的吞嚥困難？","o":["口腔準備期","口腔期","咽喉期","食道期"],"a":3,"e":"進食後喉嚨癢想咳、咳出食物，是咽喉期吞嚥反射不良，食物誤入呼吸道。"},{"c":0,"n":189,"q":"當食物或液體掉入個案呼吸道時，最不容易辨識的狀況為何？","o":["個案可能不會出現任何症狀","個案可能會嗆咳","個案可能手握頸部","個案可能會停止進食"],"a":1,"e":"「安靜型吸入」可能沒有任何症狀，最不容易察覺，風險最高。"},{"c":0,"n":190,"q":"不同疾病會有不同症狀反應，失智症個案最常見者為","o":["阿茲海默型失智症","血管型失智症","路易氏體型失智症","額顳葉型失智症"],"a":1,"e":"阿茲海默型失智症是最常見的失智症類型。"},{"c":0,"n":191,"q":"有關行為精神症狀的敘述，下列何者正確？A.行為障礙事出有因B.身體不適會造成行為障礙C.對有幻覺的個案，應說服這是假象D.為安撫個案情緒，哄騙是最好的方法","o":["AB","BC","CD","AD"],"a":1,"e":"失智者的行為問題通常事出有因，身體不適也會引發；不應說服、爭辯或哄騙。"},{"c":1,"n":1,"q":"有關老人用藥安全的一般性原則，何者為不正確？","o":["保存時應注意溫度與防潮","不要與他人分食","藥物雖過期，只要不變色、不潮濕，仍可使用","應依醫師指示服用"],"a":3,"e":"過期藥物即使外觀正常，藥效與安全性都無法保證，不可使用。"},{"c":1,"n":2,"q":"以下哪一項不是照顧服務的工作內容？","o":["協助案主購買保險","協助翻身、拍背、肢體關節活動","陪同代購生活必需用品","協助進食"],"a":1,"e":"購買保險屬於個人財務決定，不在照顧服務範圍內。"},{"c":1,"n":3,"q":"對於處於憤怒且可能出現暴力行為的案主，照顧服務員應採取的合宜態度為","o":["不予理會他","予以反擊","予以責難，伺機報復","暫時離開情境，尋求協助"],"a":4,"e":"面對可能出現暴力的案主，應先確保自身安全、暫時離開，並尋求協助。"},{"c":1,"n":4,"q":"以下為更換床單的一般原則，何者不正確？","o":["更換床單前後皆要洗手","勿過度翻動案主","墊單必須平整，所以舖床時可以抖動床單，避免因皺折而造成案主壓瘡","避免以抽拉方式更換床單，以免案主皮膚受損"],"a":3,"e":"抖動床單會使灰塵與病菌飛揚；床單要平整，應靠拉緊固定。"},{"c":1,"n":5,"q":"以下何者不正確？","o":["溝通時與案主保持面對面，以利讀唇並保持視線的接觸","老人通常有聽覺障礙，所以和老人說話音調要提高","與老人溝通時說話速度和緩且清楚","不要在老人視線範圍內與他人耳語"],"a":2,"e":"老人多為高頻聽力受損，提高音調反而聽不清楚，應以低沉、和緩的聲音說話。"},{"c":1,"n":6,"q":"照顧服務的敘述，何者不正確？","o":["尊重案主以及案家的意願和生活方式","提昇案主自我照顧及自立的能力","為了工作方便及效率，幫案主做好他所有的事情","有效率、愉悅、平靜地完成工作"],"a":3,"e":"全部替案主做好會降低他的自我照顧能力，應鼓勵自立。"},{"c":1,"n":7,"q":"與老人談話時，哪一種方式較為合適？","o":["以低頻率交談","以高頻率交談","附於耳旁大聲說","不用特別注意"],"a":1,"e":"老人對高頻聲音較聽不清楚，以低頻、和緩的聲音交談較合適。"},{"c":1,"n":8,"q":"與老人建立關係，下列哪一項態度不適合？","o":["接納","支持","同情","不批判"],"a":3,"e":"同情帶有居高臨下的意味，應以接納、支持、不批判的同理態度相處。"},{"c":1,"n":9,"q":"疥瘡屬於接觸性傳染，發現疑似感染者，下列措施何者不正確？","o":["隔離","通報警察局","藥物治療","疑似感染者使用後的床單、衣物應煮沸 10～ 30 分鐘"],"a":2,"e":"疥瘡應隔離、治療、煮燙衣物，屬一般傳染病處理，不需通報警察局。"},{"c":1,"n":10,"q":"若案主為開放性肺結核患者，下列哪一項是錯誤的處理方式？","o":["接納照顧他","住處需緊密門窗","協助提供足夠的營養","注意不中斷藥物治療至少半年"],"a":2,"e":"肺結核經空氣傳染，住處應保持通風，緊閉門窗會增加傳染風險。"},{"c":1,"n":11,"q":"王爺爺需要他人餵飯，餵飯時下列哪一事項比較不需要特別注意？","o":["食慾","餵食速度","飯菜的冷熱程度","天氣"],"a":4,"e":"餵飯要注意食慾、速度、溫度；天氣與餵食關係最小。"},{"c":1,"n":12,"q":"協助老年案主洗澡時，最需要幫忙洗的身體部位是","o":["後背","前胸","隱私處","臀部"],"a":1,"e":"老人手部活動受限，最難自己洗到後背。"},{"c":1,"n":13,"q":"行動不太方便的案主常因上廁所需要人扶，因此不敢多喝水，下列哪一項是合適的？","o":["鼓勵他喝水，定時帶他上廁所","如他所想，儘量不要多喝水","鼓勵他用紙尿褲","沒有關係，不強迫"],"a":1,"e":"水分不足易造成泌尿道感染與便秘，應鼓勵喝水並定時協助如廁。"},{"c":1,"n":14,"q":"案主拒絕服藥時，下列措施何者較適宜？","o":["將藥混在飯中一起吃","耐心的勸他服藥","尊重他的意見，不勉強他服藥","將藥混在果汁中服用"],"a":2,"e":"應耐心了解原因並勸導服藥；未經同意偷偷混藥不尊重案主，也可能影響藥效。"},{"c":1,"n":15,"q":"最適合服用飯前藥的時間為","o":["給了藥以後，立刻可以吃飯","飯前 1 小時就要吃","飯前 30 分鐘就要吃","飯前 5 分鐘就要吃"],"a":3,"e":"飯前藥一般在飯前30分鐘至1小時服用，題庫答案採30分鐘。"},{"c":1,"n":16,"q":"最適合服用飯後藥的時間為下列何者？","o":["吃飯後立刻吃","飯後 10 分鐘吃","飯後 30 分鐘吃","飯後 1 小時吃"],"a":3,"e":"飯後藥一般在飯後30分鐘內服用。"},{"c":1,"n":17,"q":"最合適用來服藥的液體是下列何者？","o":["果汁","茶","菜湯","開水"],"a":4,"e":"服藥應配溫開水；果汁、茶、湯可能與藥物產生交互作用。"},{"c":1,"n":18,"q":"王奶奶使用鼻胃管灌食，每次灌食前一定要先做的事為下列何者？","o":["反抽看看確認管子在胃中及胃中食物之消化情形","轉動一下鼻胃管，重新固定，以免滑脫","先清洗鼻胃管","先灌開水，再灌食"],"a":1,"e":"灌食前先反抽，確認管子在胃內並評估消化情形，可避免誤灌入氣管。"},{"c":1,"n":19,"q":"鼻胃管灌食每次最適當的灌食量為","o":["100～200 西西","300～500 西西","600～700 西西","800～900 西西"],"a":2,"e":"每次灌食量約300～500cc，太多易造成腹脹嘔吐。"},{"c":1,"n":20,"q":"每餐灌完食物後，要再灌多少水，讓食物都進入胃部？","o":["30cc","100cc","150cc","200cc"],"a":1,"e":"灌食後再灌約30～50cc溫開水，沖淨管內殘留食物。"},{"c":1,"n":21,"q":"灌食速度太快時，被照顧者容易出現什麼狀況？","o":["嗆到","咳嗽","心跳加速","脈搏減慢"],"a":3,"e":"灌食太快會使胃快速膨脹，引起不適與心跳加速等反應。"},{"c":1,"n":22,"q":"胃管灌食時食物的適當溫度為幾度？","o":["28℃","32～35℃","38～40℃","45 ℃"],"a":3,"e":"灌食溫度約38～40℃，接近體溫，不刺激腸胃。"},{"c":1,"n":23,"q":"下列何者為灌食空針的適當處理方式？","o":["用完馬上用清水清洗","用完即丟","用完後再用酒精消毒","用完擺放妥當，下次再用"],"a":1,"e":"灌食空針用後立即以清水洗淨、晾乾，避免奶垢孳生細菌。"},{"c":1,"n":24,"q":"如果灌食時有嘔吐情形，下列處理措施何者為宜？","o":["立即停止灌食，並觀察其呼吸、心跳","沒關係","立即打 119 求救","改變案主姿勢"],"a":1,"e":"灌食時嘔吐應立即停止，並觀察呼吸、心跳，預防吸入性肺炎。"},{"c":1,"n":25,"q":"灌食時案主的適當姿勢為","o":["平躺","半坐臥約 30～45 度","左側臥","依案主喜好選擇姿勢"],"a":2,"e":"灌食時採半坐臥30～45度，以利重力流入並減少逆流。"},{"c":1,"n":26,"q":"灌食之奶類在室溫中，擺置時間以下列何者為宜？","o":["0.5 小時","1 小時","2 小時","3 小時"],"a":1,"e":"配好的奶類在室溫放置不宜超過30分鐘，以免細菌孳生。"},{"c":1,"n":27,"q":"將案主由床鋪扶到輪椅上，下列哪一項是最優先要做的？","o":["先將輪椅固定好","在案主身上找到固定的施力點","先試試看能不能搬得動","先找來另一個人以備協助"],"a":1,"e":"移位前一定先固定輪椅煞車，避免輪椅滑動造成跌倒。"},{"c":1,"n":28,"q":"如果案主仍保有部分移動能力，在您協助案主由椅子上返回床鋪時，下列何者較不合適？","o":["保護案主在安全之原則下，鼓勵他嚐試自行移位","為了避免意外，將案主抱回床鋪","給予部份協助","鼓勵案主配合移位的動作並給予適時的讚美"],"a":2,"e":"應鼓勵案主發揮剩餘能力；直接抱回床鋪會使能力退化，也容易傷到照顧者。"},{"c":1,"n":29,"q":"協助案主由床鋪移到輪椅時，輪椅與床鋪的角度下列何者較合適？","o":["平行","45°～60°","90°","100°～135°"],"a":2,"e":"輪椅與床呈30～45度（題庫答案為45～60度），移位轉身的距離最短。"},{"c":1,"n":30,"q":"如果在被照顧者移位的過程中出現意外事故時，下列何者為最優先的措施？","o":["就近尋求協助","趕快清理現場，當作沒發生","維護被照顧者的安全","打電話通知家屬"],"a":3,"e":"發生意外時，第一優先是維護被照顧者的安全。"},{"c":1,"n":31,"q":"在協助案主製作餐點時，若照顧服務員使用微波爐，下列哪一項是不正確的？","o":["金屬製之餐具不得放入微波爐","保麗龍餐具不得放入微波爐","避免站在近距離","避免用來溫熱牛奶"],"a":4,"e":"微波爐可以溫熱牛奶，只需注意容器材質與加熱時間。"},{"c":1,"n":32,"q":"協助被照顧者移位時，被照顧者身上最容易用來使力的點是","o":["肢體的遠端，如手掌","肢體，如手臂","軀幹","頭頸部"],"a":3,"e":"移位時應施力於軀幹（如腰部、肩胛），拉扯手腳容易造成脫臼。"},{"c":1,"n":33,"q":"如果您要單獨一個人協助案主由椅子上移位到床鋪時，哪一項為不適當措施？","o":["先排除床與椅子間的障礙物","事先向案主說明步驟","移位時要逐步再叮嚀","事先告知案主要小心萬一發生意外要自行負責"],"a":4,"e":"事先要求案主自負意外責任並不恰當，照顧者應做好安全措施。"},{"c":1,"n":34,"q":"照顧案主最有效的預防感染措施是哪一項？","o":["洗手","戴口罩","穿圍裙","戴手套"],"a":1,"e":"洗手是預防感染最簡單也最有效的方法。"},{"c":1,"n":35,"q":"協助案主坐上輪椅時，輪椅應放在他的哪個方向？","o":["健側","患側","前方","無特殊方向"],"a":1,"e":"輪椅放在案主健側，讓他能用有力的一側支撐、轉身。"},{"c":1,"n":36,"q":"為案主烹調膳食時，需要注意六大類食物之均衡，其中以供應蛋白質為主的是","o":["魚、肉、豆、蛋、奶類","蔬菜、水果類","五穀、根莖類","油脂類"],"a":1,"e":"蛋白質主要來自豆魚蛋肉類及乳品類。"},{"c":1,"n":37,"q":"以擔架搬運被照顧者時，下列哪種情況必須使其頭在前、腳在後運送？A.抬上救護車B.下樓梯時C.上樓梯時D.平面移動。","o":["AB","AC","BC","CD"],"a":2,"e":"上救護車與上樓梯時頭在前，讓頭部位置較高；平地與下樓則腳在前。"},{"c":1,"n":38,"q":"下列敘述何者正確？","o":["老年人因為對生理需求較不敏感，容易缺乏食慾，故應把食物煮鹹一點來促進他的食慾","老人牙齒不好，所以喝菜湯就好","老人腸胃消化差，盡量不要吃油炸的食物","老人因為上廁所不方便，所以儘量不給他喝太多水"],"a":3,"e":"老人腸胃消化較差，應少吃油炸食物；不宜過鹹，也不應限水。"},{"c":1,"n":39,"q":"所照顧的案主罹患高血壓，在調製飲食必須注意之事項為","o":["多喝牛奶、吃小魚乾","低動物性油、低鹽的飲食","多吃動物性蛋白質的食物","植物性奶油因為是植物性的，多吃沒關係"],"a":2,"e":"高血壓飲食原則是低油（低動物性脂肪）、低鹽。"},{"c":1,"n":40,"q":"有關營養不良的症狀，下列何者不正確？","o":["體重明顯下降","皮膚蒼白","容易疲憊","皮膚紅潤"],"a":4,"e":"營養不良會使皮膚蒼白，不會紅潤。"},{"c":1,"n":41,"q":"下列何者可增加案主之食慾？A.單獨進餐以免分心；B.去除環境異味、避免不舒適的感覺；C.工作人員的態度親切；D.加重食物鹹度，以刺激食慾","o":["AB","CD","AD","BC"],"a":4,"e":"環境無異味、工作人員態度親切能增加食慾；加重鹹味有害健康。"},{"c":1,"n":42,"q":"在案家工作時，照顧服務員的工作範圍包括A.案主本身B.案主個人所使用的範圍C.案主所居住的空間D.案主鄰居E.案主親戚，下列何者組合正確？","o":["ABE","BCD","ABD","ABC"],"a":4,"e":"照顧服務範圍為案主本人、其使用的物品，以及其居住空間。"},{"c":1,"n":43,"q":"下列何者是構成感染的要素：A.環境；B.氣候；C.致病菌；D.宿主","o":["ABC","ACD","BCD","ABD"],"a":2,"e":"感染要素包括致病菌、宿主與環境（傳播途徑）。"},{"c":1,"n":44,"q":"下列有關內科無菌之敘述，何者不正確？","o":["內科無菌技術就是應用醫療技術預防致病菌從一處傳播到另一處","洗手是常見的內科無菌技術","只要泡鑷罐空間足夠拿取方便，可以同時放多把敷料鉗","清洗用物或病床時，應往遠離身體和制服的方向擦拭"],"a":3,"e":"泡鑷罐一次只能放一把敷料鉗，以免取用時互相污染。"},{"c":1,"n":45,"q":"致病原可由多種方式來傳播，下列有關傳播途徑之敘述，何者正確？","o":["接觸傳染又可分為直接接觸、間接接觸以及空氣傳染","AIDS 是屬於病媒傳染","痢疾是屬於飛沫傳染","食物和水的傳染是指人類食用已被污染的食物及水等，而造成疾病"],"a":4,"e":"食物與飲水傳染是吃到被污染的食物或水而致病；空氣傳染不屬接觸傳染，痢疾屬糞口傳染。"},{"c":1,"n":46,"q":"有關對於「洗手」的敘述，下列何者不正確？","o":["正確的洗手技術可降低院內感染的發生率","只要遵守洗手步驟，不需要處理手部傷口也可達到預防感染的目的","需在流動的水中洗手","洗手時必須脫下首飾，以免無法完全洗淨"],"a":2,"e":"手部有傷口應先處理並覆蓋，否則洗手也無法完全預防感染。"},{"c":1,"n":47,"q":"下列關於用藥安全的敘述何者不正確？","o":["給藥時應遵守「五對」法：被照顧者正確、藥物正確、劑量正確、給藥時間正確、給藥途徑正確","給予口服懸浮藥液時需與量杯刻度平視倒入，再使用吸管將懸浮藥液搖勻後服用","服用酸、鐵、碘劑藥水需用吸管服用","藥物若變色、變味或變質，均不得使用"],"a":2,"e":"懸浮液應先搖勻再倒入量杯，不是倒出後再用吸管攪勻。"},{"c":1,"n":48,"q":"關於照顧服務員在飲食服務的職責上，下列敘述何者不正確？","o":["應具有營養與食物分類的基本知識","協助案主盡量食用改善疾病的治療飲食","觀察案主的進食情況，並記錄食入量及剩餘量","對於案主要求的食物應盡量滿足"],"a":4,"e":"案主要求的食物要考量疾病與營養需求，不能一味滿足。"},{"c":1,"n":49,"q":"當被照顧者有腸胃道急性發炎及腹瀉時，應採用何種飲食：","o":["流質飲食","軟質飲食","一般飲食","半流質飲食"],"a":1,"e":"腸胃急性發炎時採流質飲食，讓腸道休息。"},{"c":1,"n":50,"q":"下列有關鼻胃管灌食之敘述，何者不正確？","o":["將床頭搖高 30～60 度","灌食前先反抽胃液","反抽之胃液不必打回胃內","每次灌食量約 250～ 350cc"],"a":3,"e":"反抽出的胃液含電解質與消化液，應打回胃內。"},{"c":1,"n":51,"q":"下列何者不正確？","o":["使用肛門塞劑協助案主塞入肛門時，宜鼓勵案主深呼吸放鬆肛門","服用油性藥品後，可給予果汁或餅乾，以去除味道","服用咳嗽藥水後，可給予開水以減少藥味","傷口塗抹藥物時，應由傷口中心向四周環形塗抹"],"a":3,"e":"咳嗽藥水服用後不宜馬上喝水，以免沖淡在喉部的藥效。"},{"c":1,"n":52,"q":"有關四腳助行器的使用，下列何者不正確：A.四隻腳皆使用安全具有附著力的橡皮墊；B.助行器合適之高度應為使手肘能彎至約30度；C.穿上不會滑溜且安全的鞋子；D.可以讓案主單獨使用助行器","o":["A","B","C","D"],"a":4,"e":"使用助行器初期應有人在旁陪同，不可讓案主單獨使用。"},{"c":1,"n":53,"q":"協助案主以柺杖下樓梯時，其順序為：A.將柺杖下至較低的階梯；B.先站穩；C.健肢跟進；D.患肢下","o":["A→B→C→D","A→B→D→C","B→A→C→ D","B→A→D→C"],"a":4,"e":"拄拐杖下樓：先站穩→拐杖放到下一階→患肢下→健肢跟上。"},{"c":1,"n":54,"q":"下列何者不屬於助行器的種類？","o":["護腰","柺杖","四腳助行器","四腳拐杖"],"a":1,"e":"護腰屬於支撐輔具，不是助行器。"},{"c":1,"n":55,"q":"陪同視力模糊的案主就醫時應注意的事項，下列何者不正確？","o":["就醫前可先預約掛號，以減少在醫院內等待的時間","就醫前應先備妥所需的證件","交通工具盡量以無線電叫計程車為宜","返家後，將藥物直接交予案主自行服用"],"a":4,"e":"視力模糊者無法看清藥袋，應協助核對並說明，不能直接交給他自行服用。"},{"c":1,"n":56,"q":"有關協助案主下床坐入輪椅之注意事項，下列何者不正確？","o":["輪椅放在床尾，與床尾平行或呈 45 度角","應藉助身體轉身的力量將案主移位，以達省力作用","可多使用自己的力量抬起案主，來幫助案主移位","移位時兩腿分開，可增加底面積及穩定度"],"a":3,"e":"移位應運用身體力學與轉身的力量，硬用自己的力量抬起容易受傷。"},{"c":1,"n":57,"q":"協助長期臥床的案主下床活動，下列何者正確？","o":["案主想下床就下床","先在床緣坐穩並觀察案主生命徵象穩定，才下床","為趕時間迅速下床","配合生活安排，即刻下床"],"a":2,"e":"長期臥床者應先在床緣坐穩，確認生命徵象穩定、沒有頭暈，再下床。"},{"c":1,"n":58,"q":"陪同被照顧者就醫時，除備齊相關證件外，以下哪一項是最重要的？","o":["就醫過程中注意被照顧者的安全","趕時間快快看完","讓被照顧者坐在待診椅上，逕自去領藥較方便","急需如廁，讓被照顧者坐輪椅上，在廁所外等候"],"a":1,"e":"陪同就醫最重要的是全程注意被照顧者的安全。"},{"c":1,"n":59,"q":"流行性感冒流行期間，下列何者不正確？","o":["住院被照顧者應特別注意呼吸道感染控制","勤洗手、戴口罩","注意監測被照顧者的體溫變化","趁被照顧者睡覺時，找其他的服務員聊天"],"a":4,"e":"流感期間應加強感染控制並持續照顧，不可擅離職守。"},{"c":1,"n":60,"q":"嚴重急性呼吸道症候群(SARS)的流行期間，下列敘述那一項是錯誤？","o":["進出醫院的人都需要測體溫","案主因住家中不必特別監控體溫的變化","與發燒者接觸的人要特別監控體溫","照顧服務員因接觸各種不同的人，更要監控體溫"],"a":2,"e":"SARS期間在家中的案主也應監測體溫。"},{"c":1,"n":61,"q":"為能促進被照顧者睡眠，下列那一項是錯誤的？","o":["盡可能保有被照顧者就寢前的習慣","如肚子餓了可喝杯溫牛奶","不斷的和被照顧者講話","給予被照顧者背部按摩"],"a":3,"e":"不斷講話會干擾睡眠，應營造安靜的環境。"},{"c":1,"n":62,"q":"照顧使用導尿管的案主，為了避免感染，下列那一項是錯誤的？","o":["工作前後均應洗手","不能讓他洗澡","每日徹底清潔導尿管及尿道口","鼓勵多喝水"],"a":2,"e":"導尿管案主可以淋浴，保持清潔反而能降低感染。"},{"c":1,"n":63,"q":"為案主修剪趾甲，下列那一項動作是正確的？","o":["先行以溫水泡腳，軟化趾甲後再行修剪","為減少修剪次數一次就把趾甲剪得很短","擔心案主受傷而不要修剪較好","選擇尖頭剪刀較易修剪"],"a":1,"e":"先泡溫水軟化趾甲再修剪，趾甲應剪平，不要剪太短。"},{"c":1,"n":64,"q":"案主感染疥瘡時，在處理用物時，下列何者錯誤？","o":["以蓋過用物的水加熱到攝氏 50 度以上，煮 30 分鐘以上","無法水煮的物品可置於日光下，直接曝曬八小時以上","將所有的物品沖洗乾淨即可","以合宜比例的稀釋漂白水，擦拭家俱及清潔環境"],"a":3,"e":"疥瘡污染的物品必須煮燙或日曬消毒，只沖洗無法殺死疥蟲。"},{"c":1,"n":65,"q":"協助案主吃藥時，以下哪一項是正確的？","o":["醫師開的藥放心吃","反正案主年紀那麼大那懂什麼，給他吃就是","每天吃例行的藥不需再向案主說明","需告訴案主所服用的藥物種類及作用"],"a":4,"e":"服藥前應向案主說明藥物種類與作用，尊重知的權利。"},{"c":1,"n":66,"q":"案主可以自解小便，但因行動不方便，為避免來不及上廁所，下列方法何項為正確？","o":["給予穿紙尿褲","放置尿壼在床邊以備不時之需","限制案主喝水","順其自然"],"a":2,"e":"床邊放置尿壺方便案主自行解尿，也維持他的自主能力。"},{"c":1,"n":67,"q":"對於清醒的案主，灌食前一定要做的事，下列何項是正確的？","o":["反抽胃管胃液，以確認胃管在胃中及胃中食物消化的情形","把胃管抽出 5 公分看看有無在胃中，並消毒後再灌食","先灌 100 ㏄開水看管子是否在胃中","胃管用清水多清洗幾次，再灌食"],"a":1,"e":"灌食前必須反抽確認胃管位置與消化情形。"},{"c":1,"n":68,"q":"灌食時，案主有咳嗽或不舒服時，以下處理何者正確？","o":["沒關係一下就好了","打 119 求救","立即停止灌食並觀察案主呼吸、心跳及檢查胃管，並迅速連絡護理人員","改變案主坐姿為平臥"],"a":3,"e":"灌食時咳嗽可能是嗆入或管子移位，應立即停止並報告護理人員。"},{"c":1,"n":69,"q":"給案主用藥在安全上一般原則下列何者不正確？","o":["存放時應注意避免潮濕及高溫","注意藥物的有效期","飯後 30 分鐘才可給藥","多的藥可分給別人吃"],"a":4,"e":"藥物不可分給他人服用，因個人病情與體質不同。"},{"c":1,"n":70,"q":"當案主需使用熱水袋時，下列何者錯誤？","o":["密切觀察案主的反應情形","不管使用時間，等涼了再裝熱水繼續使用","熱水袋的水溫約 40~46℃","不可使用在腹痛（確定經痛者除外）"],"a":2,"e":"熱水袋使用時間需控制，每次約20～30分鐘，並要觀察皮膚。"},{"c":1,"n":71,"q":"案主使用冰袋時，下列何者不正確？","o":["局部有發紫、麻木或劇痛時應暫停使用","冰枕不可直接接觸皮膚，應套上墊套","不使用時，為保持乾爽可放在陽光下曝曬","頭部用冰袋時，其他部位應保暖，以免發生寒顫"],"a":3,"e":"冰袋不可曝曬，會使材質老化破裂，應晾乾後陰涼處存放。"},{"c":1,"n":72,"q":"為方便老年案主穿脫衣褲，採用的衣褲下列何者不適當？","o":["多採用鬆緊帶的褲頭","衣服前襟可用魔術帶","衣服前襟可用交叉式帶子","用鈕釦較傳統"],"a":4,"e":"鈕釦需要手指精細動作，老人不易操作。"},{"c":1,"n":73,"q":"協助有留置導尿管的案主移位時，下列措施那一項是正確的？","o":["尿袋不可高於膀胱","只要方便移位就好了","先移位，尿袋自然會拖過去","尿已滿袋，但不用擔心，移好位子再倒尿"],"a":1,"e":"移位時尿袋要保持低於膀胱，避免尿液逆流造成感染。"},{"c":1,"n":74,"q":"對罹患高血壓的案主，為了瞭解藥物的效果，照顧服務員應做的事項之一，下列何者是正確的？","o":["定時為案主測量血壓並做記錄","收集血壓的資料是醫師專屬的工作，無關照顧服務員的事","照顧服務員事情忙，有空再為案主測量","案主想測量時再測量"],"a":1,"e":"定時測量並記錄血壓，可協助醫護評估藥效。"},{"c":1,"n":75,"q":"使用無菌有蓋容器，在提起蓋子的方法，下列那一項錯誤？","o":["保持蓋口朝下，離開容器上方，使用完畢後應盡速蓋好","蓋子內面應朝上放置桌上","不可對著蓋子內面吹氣或咳嗽","只要打開蓋子就好了，不需特別講究技術"],"a":4,"e":"取用無菌容器時，蓋內面朝上、蓋口朝下、勿對著吹氣，都有一定技術要求。"},{"c":1,"n":76,"q":"正確的洗手法，下列那一項是錯誤的？","o":["將衣袖捲至手肘以上並取下飾物及手錶","遵守濕、搓、沖、捧、擦的洗手原則","將手掌面、手背、指尖與指縫的每一表面至少搓洗 5 次以上","洗完手以手捧水沖水龍頭流水口"],"a":4,"e":"洗完手應以擦手紙包住水龍頭關閉，或先捧水沖水龍頭再關；選項4是題庫判定的錯誤敘述。"},{"c":1,"n":77,"q":"協助案主由平臥改為坐姿，下列何者不正確？","o":["案主很胖，趕快扶起以免太累","觀察案主的脈搏、呼吸有無異常","觀察案主的臉色有無蒼白、盜汗等情形","確定是否坐穩，並為案主整容"],"a":1,"e":"改變姿勢要慢，避免姿位性低血壓，不能因為案主很胖就急著扶起。"},{"c":1,"n":78,"q":"協助案主移位下床時，照顧服務員的姿勢下列那一項是正確的？","o":["照顧服務員運用身體力學的原理搬運案主","服務員很有力氣，將案主由床上抱起較快","彎下腰用力抱起案主","從案主背後抱起案主"],"a":1,"e":"搬運時應運用身體力學原理，不可彎腰硬抱。"},{"c":1,"n":79,"q":"以輪椅推送案主，為保護案主的安全，下列那一項是錯誤？","o":["在斜坡路下坡時，要調整輪椅之走向，以椅背先行的原則","在斜坡路下坡時，要調整輪椅之走向，以坐椅口前行的原則","隨時注意案主的生命徵象","隨時注意路面狀況"],"a":2,"e":"下坡時輪椅應倒退（椅背朝前）慢慢下，以免案主往前跌出。"},{"c":1,"n":80,"q":"更換固定尿管或鼻胃管紙膠的時間，下列哪一項正確？","o":["有脫落再更換","每二天更換一次","至少每天更換一次","每一星期更換一次"],"a":3,"e":"紙膠至少每天更換並換位置黏貼。"},{"c":1,"n":81,"q":"照顧服務員為被照顧者洗頭時，搓揉頭髮及頭皮的適當方式下列何者為正確？","o":["用指甲尖端","用手指指腹","用塑膠髮梳","用按摩棒"],"a":2,"e":"洗頭時用指腹搓揉，避免指甲刮傷頭皮。"},{"c":1,"n":82,"q":"協助服用口服藥物時應注意a.潮濕或變色不可用b.只要沒拆封過的都可服用c.服用時間與方法d.服用的劑量","o":["abc","bcd","acd","abd"],"a":3,"e":"服藥要注意藥物是否變質，以及服用時間、方法與劑量；沒拆封也可能過期。"},{"c":1,"n":83,"q":"當吞嚥困難個案進食速率很慢時，工作人員應","o":["用灌食空針餵食","給個案吸管，以便喝液體時快些","協助個案依其速率進食","使用較大湯匙餵食"],"a":3,"e":"吞嚥困難者應依他的速度慢慢進食，催促容易嗆咳。"},{"c":1,"n":84,"q":"下列何者適用於吞嚥困難個案的餵食？","o":["提供他們喜歡的食物即可","在支持其雙足下，上半身坐直","無限量給予稠化飲料","避免使用當季食品"],"a":2,"e":"進食時雙腳著地支持、上半身坐直，可降低嗆咳風險。"},{"c":1,"n":85,"q":"為何協助吞嚥困難個案進行口腔清潔很重要？","o":["吞嚥困難個案通常不刷牙","吞嚥困難個案通常有麻痺現象，無法使用雙手","口腔內的細菌會增加吸入性肺炎的危險","這些個案通常沒有牙齒，故不需做口腔護理"],"a":3,"e":"口腔細菌若隨唾液或食物誤吸入肺，容易引起吸入性肺炎。"},{"c":1,"n":86,"q":"給予吞嚥困難個案流質時，最安全的方式為","o":["用吸管吸食，以能足量攝取","用杯子喝，不必限制量","吞嚥困難個案通常不能給予流質","一次喝一小匙，慢慢喝"],"a":4,"e":"吞嚥困難者喝流質應一次一小匙、慢慢喝。"},{"c":1,"n":87,"q":"發現案主誤服過量藥物時，應如何處理？A.案主意識清楚時可請他喝大量開水；B.誤服強酸、強鹼或腐蝕性藥物時不要催吐；C.將案主和剩下的藥物或空瓶一併送醫；D.若無不適症狀不需要送醫","o":["ABC","BCD","ACD","ABD"],"a":1,"e":"誤服藥物：清醒者可喝水稀釋；強酸鹼不可催吐；帶藥瓶送醫。即使沒有症狀也要就醫。"},{"c":1,"n":88,"q":"下列何種藥品需經由醫師開立處方才能拿藥？","o":["成藥","指示藥","草藥","處方藥"],"a":4,"e":"處方藥必須由醫師開立處方才能取得。"},{"c":1,"n":89,"q":"忘記吃藥時正確處理方式為？A.忘記就算了B.才剛過服藥時間，可立刻補吃C.等下次服藥時再補吃藥量來彌補D.補吃藥物的方法依藥物種類、服藥頻率、想到的時間而有所不同","o":["AB","BD","AC","CD"],"a":2,"e":"剛過服藥時間可立即補吃；若已接近下一次就不要補，依藥物種類決定，絕不可加倍。"},{"c":1,"n":90,"q":"醫師開立處方一天四次用藥，一般的服藥時間指","o":["每七小時吃一次","任何時間都可以","三餐及睡前各吃一次","凌晨 4 點、午餐、下午 4 點、睡前"],"a":3,"e":"一天四次一般指三餐飯後與睡前各一次。"},{"c":1,"n":91,"q":"口服藥物正確服用方式為？A.以適量開水配服，勿配茶、咖啡、果汁、牛奶B.將制酸錠咬碎的藥效較好C.發泡錠應加適量水溶解後再服用D.腸衣錠應咬碎、磨粉後再服用","o":["ABC","BCD","ABD","ACD"],"a":1,"e":"服藥應配開水；制酸錠嚼碎效果較好；發泡錠先溶水再服用；腸衣錠不可咬碎。"},{"c":1,"n":92,"q":"關於藥物保存下列何者錯誤？","o":["放在小孩拿不到的地方","藥物冷藏比常溫保存來的好","藥物不要存放在浴室、廚房或陽台邊","口服藥與外用藥應該要分開保存"],"a":2,"e":"多數藥物室溫保存即可，只有註明需冷藏的才放冰箱。"},{"c":1,"n":93,"q":"若醫師處方同時使用眼藥水及眼藥膏，協助案主使用的方法何者正確？A.先給眼藥膏，再用眼藥水B.先給眼藥水，再給眼藥膏C.協助頭後仰，塗(或滴)於眼角膜處D.兩種藥物應間隔8-10分鐘","o":["AC","AD","BC","BD"],"a":4,"e":"先點眼藥水，再塗眼藥膏，兩者間隔數分鐘，以免藥膏阻擋藥水吸收。"},{"c":1,"n":94,"q":"正確的藥袋標示內容，不含以下何者？","o":["病人姓名、性別","疾病診斷資料","調劑者姓名、地點","藥名及含量"],"a":2,"e":"藥袋標示包括姓名、藥名、劑量、用法、調劑者等；疾病診斷不一定要標示。"},{"c":1,"n":95,"q":"胃乳等懸浮劑使用前需搖一搖的原因為","o":["藥水產生氣泡比較好喝","增強藥效","使藥品劑量較均勻","避免副作用產生"],"a":3,"e":"懸浮劑放久會沉澱，搖勻才能確保每次劑量一致。"},{"c":1,"n":96,"q":"帶領視障朋友走路時，下列描述何者正確？","o":["用力拉或推他前進","以口述方式引導他前進","將他的手放在你的手上臂處或肩上前進","催促快速前進"],"a":3,"e":"引導視障者時，讓他扶著你的上臂或肩膀，你走半步在前。"},{"c":1,"n":97,"q":"與智能不足者相處時，下列服務方式何者為正確？","o":["多同情他，凡事都幫他做好","嚴厲要求他學習自我照顧","多示範少指揮，多給練習的機會","任其自由發展"],"a":3,"e":"多示範、少指揮、多給練習機會，可以提升智能障礙者的自理能力。"},{"c":1,"n":98,"q":"不同障別的高齡身心障礙者的照顧需求並不完全相同，其照顧原則何者最合適？","o":["以「個案為中心」依據其需求規劃照顧計畫","依照顧老人方式照顧","依照顧身障者方式照顧","最佳方式是進入機構照顧"],"a":1,"e":"以個案為中心，依個別需求規劃照顧計畫。"},{"c":1,"n":99,"q":"處理失智者定向力障礙的措施，下列何者最適當？","o":["放置月曆，請長者看到整個月的日期","於牆上公告當天為幾月幾號星期幾","經常詢問，你記得我是誰嗎？以協助其熟悉環境","請長者記得家中物品放置位置，以協助記憶"],"a":2,"e":"每天公告日期，可協助失智者維持時間定向感。"},{"c":1,"n":100,"q":"對待失智長者，下列何者最適當？","o":["可約定出門時間，請長者預先準備","所有失智長者均統一照顧方式","以對待小孩的態度對待失智長者，表達親切","盡量鼓勵長者盡其所能，發揮長處"],"a":4,"e":"鼓勵失智長者盡其所能、發揮長處，可以維持功能與自尊。"},{"c":1,"n":101,"q":"有關失智者居家飲食，下列何者正確？A.建立規律用餐時間；B.若忘記進食而不斷要求時應告知已進食過；C.若拒絕進食時應先了解原因；D.調製新鮮食物口味提升長者的新鮮感","o":["AB","BC","CD","AC"],"a":4,"e":"建立規律用餐時間；拒食時先了解原因，可能是牙痛、便秘或情緒等。"},{"c":1,"n":102,"q":"失智的王奶奶今天因找不到錢包而大叫「有人偷走我的錢包」，下列反應何者最適當？","o":["「這裡很安全，沒人會偷你的錢包」","「你一定忘在哪裡了，您再想想」","「不要擔心，我們會幫您找出來」","誘導王奶奶自己找到錢包"],"a":4,"e":"（本題已刪題）面對失智者的被偷妄想，可陪他一起找，引導他自己找到錢包，避免爭辯。","d":1},{"c":1,"n":103,"q":"失智的陳先生經常被發現在客廳便溺，下列措施何者為宜？A.協助改為穿尿布；B.協助長者換上有拉鍊的褲子；C.在廁所門口貼上「馬桶」的圖片；D.掌握排泄習慣引導並去廁所","o":["AB","BC","CD","AC"],"a":3,"e":"在廁所門口貼馬桶圖片、掌握排泄習慣並定時引導，可減少在客廳便溺。"},{"c":2,"n":1,"q":"為案主提供餐飲服務下列事項何者為不正確？","o":["價錢合理","以重口味為主","注意營養均衡且以清淡為原則","符合案主喜好"],"a":2,"e":"餐飲應清淡、營養均衡，不宜重口味。"},{"c":2,"n":2,"q":"下列何者不包括在照顧服務之項目？","o":["居家環境清潔","更換鼻胃管","協助服藥","陪同就醫"],"a":2,"e":"更換鼻胃管屬醫療行為，由護理人員執行。"},{"c":2,"n":3,"q":"當為案主整理家務時，基於個人衛生安全，需要自行準備的是：A.可替換的衣物B.掃帚C.口罩D.手套E.拖把","o":["ABC","CDE","ACD","BDE"],"a":3,"e":"照服員應自備替換衣物、口罩、手套保護自己；掃帚、拖把由案家提供。"},{"c":2,"n":4,"q":"協助案主購買外食最需注意事項為何？","o":["衛生","菜色","價錢","口味"],"a":1,"e":"購買外食最重要的是衛生，避免食物中毒。"},{"c":2,"n":5,"q":"丟棄案主物品前首先需注意何事？","o":["通知環保局","丟入垃圾車","請案主再次確認","由家人處理"],"a":3,"e":"物品是案主的財產，丟棄前要請案主再次確認。"},{"c":2,"n":6,"q":"工作前後，為了減少發生感染現象，照顧服務員需作下列哪一件事？","o":["洗手","更換衣服","洗臉","為案主擦拭雙手"],"a":1,"e":"工作前後洗手可減少交叉感染。"},{"c":2,"n":7,"q":"為案主從事環境清潔最主要的目的為何？","o":["確保案主生活在清潔、衛生及安全的環境中","維持照顧服務員工作收入","遵從主管指示","減輕家屬負擔"],"a":1,"e":"環境清潔的主要目的是讓案主生活在清潔、衛生、安全的環境。"},{"c":2,"n":8,"q":"此圖案代表意義為何？","o":["垃圾分類","資源回收","箭牌口香糖","衛生安全食品標示"],"a":2,"e":"三個箭頭循環的圖案是資源回收標誌。","img":"img/q301.png"},{"c":2,"n":9,"q":"掃地是清潔工作的基本技能，以下何種方式才是正確執行掃地工作？","o":["以掃把將垃圾掃到屋外","一手拿掃把一手拿畚箕，清理有垃圾的地方","以掃把從屋外往屋內清掃","以掃把從屋內裡側角落掃起，逐步清掃屋內地面，避免有遺漏之處"],"a":4,"e":"掃地由屋內角落往外掃，才不會遺漏或把灰塵帶回。"},{"c":2,"n":10,"q":"拖地時應注意事項為何？","o":["拖把要濕一點否則不易達到乾淨標準","拖把沾水不可太濕預防案主跌倒","從門口開始拖向房間裡","要大支拖把才能快速完成工作"],"a":2,"e":"拖把應擰乾，地面太濕容易使案主滑倒。"},{"c":2,"n":11,"q":"為案主清洗衣物時，如何保護案主衣物不受損傷？","o":["依據照顧服務員個人經驗","依據案主的習慣","依據衣服上的洗滌標示","為保護衣物，能不洗就不洗"],"a":3,"e":"依衣服上的洗滌標示清洗，才不會損傷衣物。"},{"c":2,"n":12,"q":"在案家做家務清掃工作時，哪一項是合理的做法？","o":["隨便掃一掃就可以了","髒的地方先清，其他的有空再掃","按部就班，由裡到外的清掃","由外到裡清潔，以免污染環境"],"a":3,"e":"按部就班、由裡往外清掃，才能確實又不重複污染。"},{"c":2,"n":13,"q":"為案主準備膳食時，除了洗手還要注意些什麼？","o":["食物及器皿的衛生","鍋子及碗盤的數目","洗槽的大小","過濾器的適用性"],"a":1,"e":"準備膳食要注意食物與器皿的衛生。"},{"c":2,"n":14,"q":"被照顧者口味重無法接受清淡食物時，照顧服務員該如何處理？","o":["為了被照顧者健康著想，強迫被照顧者改變口味","以逐漸減少調味料方式來改善","為了不影響雙方關係就維持被照顧者喜好","被照顧者不改變，照顧服務員也無能為力"],"a":2,"e":"口味要逐漸減少調味料慢慢調整，比強迫改變容易接受。"},{"c":2,"n":15,"q":"食物料理方式需考慮哪些因素？","o":["依照食譜烹調","有口感嚼勁夠","重口味有味道","被照顧者咀嚼及吞嚥能力"],"a":4,"e":"料理方式要配合被照顧者的咀嚼與吞嚥能力。"},{"c":2,"n":16,"q":"為減少垃圾量，照顧服務員要協助被照顧者家庭做什麼？","o":["垃圾分類","不製造垃圾","將垃圾帶回自家中","將垃圾放置在他人垃圾袋中"],"a":1,"e":"垃圾分類可回收資源、減少垃圾量。"},{"c":2,"n":17,"q":"當照顧服務員正在案家服務時，發現案家附近有濃煙及焦味，疑似發生火災，照顧服務員該如何處理？","o":["打電話通知家屬","趕快去救火","通知 119","趕快往外逃"],"a":3,"e":"發現疑似火災應立即通報119。"},{"c":2,"n":18,"q":"照顧服務員在案家清潔環境時，發現案主遺失的財物，照顧服務員該如何處理？","o":["收為己有","報警","交還案主","帶回機構由督導處理"],"a":3,"e":"拾獲案主財物應交還案主，維持誠信。"},{"c":2,"n":19,"q":"餐食備妥後切記的一件事為何？","o":["食物趁熱食用","關閉瓦斯及各項烹調電器開關","清潔廚房","向案主報告可用餐了"],"a":2,"e":"烹調完成後要記得關閉瓦斯與電器，避免火災。"},{"c":2,"n":20,"q":"協助案主代購物品後，需向案主說明清楚何事？","o":["東西都買回來了","市場人好多買東西真不易","幫忙代購物品很費心神","請案主一一確認物品及價錢支出情形"],"a":4,"e":"代購後請案主逐一確認物品與花費，可避免財務糾紛。"},{"c":2,"n":21,"q":"下列何者不屬於照顧服務員的工作？","o":["協助購物","更換尿管","協助身體清潔","準備餐食"],"a":2,"e":"更換尿管屬醫療護理行為，由護理人員執行。"},{"c":2,"n":22,"q":"照顧服務員如何充分且有效的運用時間為案主服務？","o":["不與案主聊天，埋頭努力工作","一邊用洗衣機洗衣服一邊清潔環境","邊做菜邊唱歌","一邊為案主洗澡一邊清潔浴室"],"a":2,"e":"使用洗衣機時同時清潔環境，可有效運用時間。"},{"c":2,"n":23,"q":"整理被照顧者文件後為方便被照顧者找尋，照顧服務員將如何處理？","o":["重新分類放於不同的抽屜","放於固定位置且擺設整齊","以日期先後排放","另找一個盒子置放"],"a":2,"e":"文件放在固定位置並擺放整齊，案主才找得到。"},{"c":2,"n":24,"q":"照顧服務員至案家服務時，首先要做到的事為何？","o":["先有禮貌稱呼案主並告知服務開始","詢問工作項目","不打擾案主默默工作","讚美案主"],"a":1,"e":"到案家先有禮貌地稱呼案主並告知服務開始，建立信任關係。"},{"c":2,"n":25,"q":"資源回收的項目不包括下列何類？","o":["紙類","布類","塑膠類","玻璃類"],"a":2,"e":"一般資源回收項目為紙類、塑膠、玻璃、金屬等；布類（舊衣）另有回收管道。"},{"c":2,"n":26,"q":"清洗衣物時，照顧服務員應有的做法為何？","o":["全部丟下去一起洗","依衣服的種類、顏色區分再洗","放多一點清潔劑及漂白水","放入一般洗衣粉即可"],"a":2,"e":"依衣服的種類與顏色分開洗，避免染色或損傷。"},{"c":2,"n":27,"q":"家務服務內容安排的依據為何？","o":["照顧服務員自行規劃","家屬的要求","案主的需求","照顧服務員的專長"],"a":3,"e":"家務服務依案主的需求安排。"},{"c":2,"n":28,"q":"家務服務工作方式是依據下列哪項訂定？","o":["案主的生活習慣與標準","照顧服務員的習慣與標準","社會大眾所認定的標準","認真的照顧服務員自有工作方法"],"a":1,"e":"家務服務方式依案主的生活習慣與標準，尊重他的生活方式。"},{"c":2,"n":29,"q":"使用微波爐加熱食物，為避免水分蒸發，照顧服務員要如何處理？","o":["食物上覆蓋耐熱膠膜或蓋子","食物中加一些開水","轉盤中加一杯冷水","只短短幾秒鐘不要那麼麻煩"],"a":1,"e":"覆蓋耐熱膠膜或微波蓋，可防止水分蒸發與食物噴濺。"},{"c":2,"n":30,"q":"去除微波爐內異味的方法，可以用一杯水加上下列那項物品，一起放入爐內加熱一分鐘，並趁熱用乾布擦拭？","o":["檸檬汁一湯匙","酒一湯匙","黑醋一湯匙","洗潔精 1/5 杯"],"a":1,"e":"檸檬汁加水加熱產生的蒸氣，可去除異味並軟化污垢。"},{"c":2,"n":31,"q":"維護洗衣機清潔最基本的工作為何？","o":["不定期打開洗槽蓋讓槽內晾乾，以防止黴菌孳生","用抹布擦乾外殼","使用漂白水消毒","曝曬在陽光下"],"a":1,"e":"洗衣後打開洗槽蓋讓槽內通風晾乾，可防止黴菌孳生。"},{"c":2,"n":32,"q":"冰箱冷凍室及冷藏室最好多久清潔一次？","o":["每個月","2～3 個月","4～5 個月","每半年"],"a":1,"e":"冰箱冷凍、冷藏室最好每個月清潔一次。"},{"c":2,"n":33,"q":"突然停電時，冰箱冷藏室內的食物在多久時間內，原則上不會變質？","o":["8 小時","2～3 小時","3～4 小時","4～6 小時"],"a":2,"e":"停電時不開冰箱門，冷藏室約可維持2～3小時。"},{"c":2,"n":34,"q":"冰箱背部及側面易積塵埃，至少間隔多久將塵埃清除？","o":["半年","一年","一年半","二年"],"a":1,"e":"冰箱背面與側面的灰塵至少半年清除一次，可維持散熱效能。"},{"c":2,"n":35,"q":"浴室的牆壁磁磚長出令人討厭的霉斑，可使用何種安全物品擦拭在磁磚及隙縫間即可輕易消除？","o":["稀釋洗衣服用的漂白劑","通樂","洗髮精","沐浴精"],"a":1,"e":"稀釋的漂白水可去除磁磚霉斑，使用時要通風、戴手套。"},{"c":2,"n":36,"q":"瓦斯爐面常會被油漬湯汁濺得髒兮兮，應該如何清潔？","o":["最好是烹煮完後趁瓦斯爐還有餘熱用濕布擦拭","等爐子冷卻用濕布擦拭","用中性清潔劑與較粗的菜瓜布刷洗","使用鋼刷用力刷洗"],"a":1,"e":"烹煮後趁爐面餘溫用濕布擦拭，油漬最容易去除。"},{"c":2,"n":37,"q":"海帶營養豐富，但是海帶不容易煮爛，有一訣竅是在烹煮的時候加入何種調味料就能很快的把海帶煮的柔軟可口了？","o":["一茶匙鹽","半茶匙味精","一湯匙酒","幾滴醋"],"a":4,"e":"加幾滴醋可以軟化海帶的纖維。"},{"c":2,"n":38,"q":"當案主病情已改善，如何處理剩下的舊藥？","o":["分送給其他病患","保存起來以利日後使用","送回醫院領藥處或社區藥局","堆放在桌子抽屜內，以備不時之需"],"a":3,"e":"剩餘舊藥應送回醫院或社區藥局回收，不可分送他人。"},{"c":2,"n":39,"q":"一般口罩正確丟棄法為何？","o":["丟在公園的垃圾桶內","依照脫、摺、捲、綁、丟的順序處理","為減少感染，脫下後直接放置於垃圾桶中","脫下口罩後，將口鼻接觸面向內摺，並立即丟入垃圾桶中"],"a":2,"e":"口罩丟棄依「脫、摺、捲、綁、丟」處理，避免污染。"},{"c":2,"n":40,"q":"陪同被照顧者就醫時，需協助被照顧者備妥哪二項基本證件？","o":["勞保單與身分證","駕駛執照與身分證","健保卡與身分證","悠遊卡與身分證"],"a":3,"e":"就醫需帶健保卡與身分證。"},{"c":2,"n":41,"q":"為清理案主家的上層窗戶，照顧服務員可以採用何種方法？","o":["雙腳爬上窗戶手拿抹布擦拭","以長柄桿子綁上抹布擦拭","以手伸直之高度為限，超過此高度的部分不清理","為安全著想不安排此項服務"],"a":2,"e":"用長柄桿子綁抹布擦拭，可避免攀高跌倒。"},{"c":2,"n":42,"q":"照顧服務員至案家從事家務服務時，最妥善的工作方法為何？","o":["依照服務員個人家務處理經驗工作","依照一般長輩的工作方法提供服務","先詢問案主每項家務處理的工作方式並依照辦理","依照督導員指示提供家務服務"],"a":3,"e":"先詢問案主的處理方式並照著做，尊重案主的生活習慣。"},{"c":2,"n":43,"q":"陪同案主外出坐車時，如何安排案主坐進計程車？","o":["頭腳先進入車內，屁股再轉入車座","屁股先坐進車內，再將頭腳移入車內","請案主手扶前座椅背，一腳先進入車內，然後頭、屁股依序進入","依照案主的習慣"],"a":2,"e":"上計程車時先讓臀部坐入，再轉身將頭腳移入，最安全。"},{"c":2,"n":44,"q":"照顧服務員為了對飲食衛生做徹底的把關，除了養成隨手清潔砧板的習慣外，最好要經常定期以何種方法來消毒砧板？","o":["浸泡鹽醋水一小時","浸泡糖醋水一小時","浸泡菜汁水一小時","浸泡清水一小時"],"a":1,"e":"以鹽醋水浸泡砧板，有殺菌效果。"},{"c":2,"n":45,"q":"協助案家掃除工作時，為使動線流暢之最高指導方針為何？","o":["由下而上、由外而內","由上而下、由外而內","由上而下、由內而外","由下而上、由內而外"],"a":3,"e":"掃除原則由上而下、由內而外，避免已清潔處再被弄髒。"},{"c":2,"n":46,"q":"家務處理之基本原則為安全、衛生清潔、便利舒適、經濟節約，其中最重要之二項為何？","o":["便利舒適與經濟節約","安全與衛生清潔","衛生清潔與便利舒適","安全與經濟節約"],"a":2,"e":"家務處理最重要的是安全與衛生清潔。"},{"c":2,"n":47,"q":"有關壓瘡的照顧，下列何者有誤？","o":["翻身","使用氣墊床","定期檢查皮膚","抬高床頭"],"a":4,"e":"抬高床頭會使身體下滑，增加尾骶部的剪力與摩擦，容易形成壓瘡。"},{"c":2,"n":48,"q":"家務處理的功能不包含下列哪一項？","o":["營造一個安全、清潔的環境","降低案主家中感染的發生","增加案主的收入","提昇案主的身心健康"],"a":3,"e":"家務處理是維護環境與健康，不會增加案主收入。"},{"c":2,"n":49,"q":"協助案主整理環境時，案主要求丟棄大型家俱，照顧服務員可以聯絡哪一單位協助處理？","o":["社會局","民政局","公園路燈管理處","環保局"],"a":4,"e":"丟棄大型家具應聯絡環保局（清潔隊）處理。"},{"c":2,"n":50,"q":"照顧服務員欲丟棄案家物品時，需徵得何者同意並請其檢查後，方可丟棄？","o":["案主及其家人","里長","里幹事","警察局"],"a":1,"e":"丟棄物品前要經案主及家人同意並檢查。"},{"c":2,"n":51,"q":"下列哪一項不是照顧服務員處理案主家務的基本原則？","o":["檢查並確認當日工作項目及內容","準備當日工作項目用具","每一次皆要確實完成工作任務","服務內容及方式由照顧服務員決定"],"a":4,"e":"服務內容與方式應依照照顧計畫與案主需求，不是由照服員決定。"},{"c":2,"n":52,"q":"家務處理不包括下列哪一項工作？","o":["廚房清潔","整理儲藏室","準備餐食","清潔浴室"],"a":2,"e":"整理儲藏室不屬於一般家務處理的服務範圍。"},{"c":2,"n":53,"q":"照顧服務員結束環境清潔工作後，下列何者不屬於善後處理之工作？","o":["將清潔工具洗淨並放回原位","將垃圾倒置在垃圾袋中並綁好","將搬動過的物品歸回適當位置","灑水防灰塵"],"a":4,"e":"結束清潔後應歸位工具、整理垃圾、物品歸位；灑水防塵不是善後工作。"},{"c":2,"n":54,"q":"照顧服務員為案主準備膳食前，首先應注意下列何者事項？","o":["需先洗手，並注意食物器皿的清潔與衛生","注意安全，關閉瓦斯","關閉電源","清潔地板"],"a":1,"e":"備餐前先洗手，並注意食物與器皿衛生。"},{"c":2,"n":55,"q":"餐食準備完成時，其善後工作何者為最重要？","o":["打開抽油煙機","關閉瓦斯及各項電器開關","清洗圍裙","清洗鍋蓋"],"a":2,"e":"備餐後最重要的是關閉瓦斯與電器開關。"},{"c":2,"n":56,"q":"下列有關衣物清洗之敘述何者有誤？","o":["先將污衣以顏色及質料分類","放入適當的洗衣劑及水量","依照衣服之洗標處理","隔夜浸泡有利於洗淨衣物"],"a":4,"e":"衣物隔夜浸泡容易滋生細菌、產生異味或褪色。"},{"c":2,"n":57,"q":"陪同被照顧者購物時，需注意下列何者事項？","o":["需注意折扣物品","需隨時注意被照顧者身心狀況及行的安全","需注意自己的皮包及錢財","協助被照顧者殺價"],"a":2,"e":"陪同購物時要隨時注意被照顧者的身心狀況與行走安全。"},{"c":2,"n":58,"q":"丟棄打破之玻璃或陶瓷物品時，應如何正確處理？","o":["小心放入垃圾袋中","用報紙包好放入資源回收桶","可集中在不易穿透的容器中，並以膠帶密封用紅筆註明危險","直接埋入泥土中避免刺傷人"],"a":3,"e":"碎玻璃或陶瓷應裝入不易穿透的容器並封好、標示危險，以免清潔人員受傷。"},{"c":2,"n":59,"q":"如何有效去除衣物中之尿漬？","o":["洗衣時加入氨水或醋酸","洗衣時加入鹽","用酒精清洗","使用去漬油清洗"],"a":1,"e":"尿漬呈酸性，可用氨水中和；題庫答案為加入氨水或醋酸。"},{"c":2,"n":60,"q":"照顧服務員擔心獨居案主的安危，應如何處理最為妥善？","o":["將案主帶回家中照顧","將自己的電話留給案主，方便案主求救","協助案主與鄰居建立良好人際互動關係","通報稅捐處"],"a":3,"e":"協助獨居案主與鄰居建立良好互動，緊急時有人可以照應。"},{"c":2,"n":61,"q":"工作過程中發現案主健康狀況有異狀時，下列何者為最不適當的處理？","o":["向機構督導或家屬反應","請案主先上床休息再做處理","詢問案主身體狀況後再做處理","請案主多運動以利逼出汗水"],"a":4,"e":"案主身體異常時應休息並通報，不可要求運動逼汗。"},{"c":2,"n":62,"q":"照顧服務員在烹煮食物時，欲試嚐味道應如何處理？","o":["洗雙手，以食指來沾嚐湯汁","用鍋鏟盛湯汁就口試嚐","先將湯汁盛在小碗中試嚐","以量匙盛湯汁試嚐"],"a":3,"e":"試味時先盛在小碗中，避免污染整鍋食物。"},{"c":2,"n":63,"q":"較髒的領口、袖口或其他污垢，最佳處理方式為下列哪一項？","o":["於洗衣前先使用去污劑刷洗後，再加以洗滌","直接在洗衣機中加入漂白劑清洗","在水中浸泡 30 分鐘後，再放入洗衣機清洗","於洗衣機中加入檸檬有助漂白"],"a":1,"e":"較髒的領口、袖口應先用去污劑刷洗，再放入洗衣機。"},{"c":2,"n":64,"q":"有關老人飲食的敘述，下列何者不正確？","o":["經常檢查儲存食物的有效期","定期清除冰箱內食物，以免老人誤食","少量多餐，少油、少鹽","多吃豬肉以增加動物性蛋白質"],"a":4,"e":"老人應攝取優質蛋白質，如魚、豆類，不宜多吃高脂肪的豬肉。"},{"c":2,"n":65,"q":"照顧服務員如何處理衣物中之糞漬？","o":["將衣物直接丟棄，避免感染","浸泡於加有洗衣劑及氨水的溫水中 30 分鐘後，再洗清","浸泡在冷洗精中消毒後，再清洗","以稀釋鹽酸液沖洗後，再以漂白水洗淨"],"a":2,"e":"糞漬衣物可浸泡在加有洗衣劑與氨水的溫水中30分鐘，再清洗。"},{"c":2,"n":66,"q":"照顧服務員清掃案家天花板時，應如何處理最安全？","o":["以長柄拖把清理","爬上梯子用手擦拭","爬上櫥櫃用手擦拭","踩在桌子上以雞毛撢子除塵"],"a":1,"e":"用長柄拖把清理天花板，避免攀爬跌倒。"},{"c":2,"n":67,"q":"照顧服務員該如何處理金屬類及塑膠類容器之回收物？","o":["先割開攤平，再放入資源回收桶","打洞穿繩成串後，丟入資源回收桶","先清洗後再壓扁放入資源回收桶","直接放入回收袋由清潔人員統一處理"],"a":3,"e":"回收容器先清洗再壓扁，可避免異味並節省空間。"},{"c":2,"n":68,"q":"陪同案主外出購物前，應準備之工作下列何者為錯誤？","o":["協助案主穿著適當衣鞋","自備環保袋","備妥購物明細","為案主穿戴金項鍊及金戒指"],"a":4,"e":"外出不宜穿戴貴重飾品，以免遺失或遭搶。"},{"c":2,"n":69,"q":"陪同被照顧者就醫或檢查時，照顧服務員應備證件不包含下列那一項？","o":["身分證","健保卡","勞保卡","預約單"],"a":3,"e":"就醫需要身分證、健保卡、預約單；勞保卡與就醫無關。"},{"c":2,"n":70,"q":"照顧服務員替被照顧者至郵局或銀行領錢時，下列何者為正確？","o":["代替被照顧者於領款單上簽名","與被照顧者當面點清錢數，並請其簽收","保管被照顧者圖章及存摺","隨身攜帶被照顧者的提款卡"],"a":2,"e":"代領錢後應與被照顧者當面點清並請他簽收；不可代簽名或保管存摺、印章。"},{"c":2,"n":71,"q":"照顧服務員為被照顧者整理案家環境時，以達到下列哪一項目標為最重要？","o":["地面要光滑照人","傢具要光亮如鏡","寢室要無塵、無異味","水龍頭要無水漬，光亮如新"],"a":3,"e":"環境整理以寢室無塵、無異味最重要，與健康直接相關。"},{"c":2,"n":72,"q":"案主為一單身獨居失能老人，為了維護案主的財產安全，其存摺與印章可由何種方式代管？","o":["由照顧服務員幫忙保管","由社會局老人福利科保管","由里長代管","經由法律途徑辦理財產信託"],"a":4,"e":"獨居失能老人的財產應經法律途徑辦理信託，照服員不可代為保管。"},{"c":3,"n":1,"q":"急救時應採取下列何項措施？A.翻動傷患，以評估其肢體活動度、B.脫除傷患衣服，以檢查傷口、C.疏散人群，以免防礙急救進行、D.意識不清的傷患，禁給飲料","o":["AB","CD","AC","BD"],"a":2,"e":"急救時應疏散圍觀人群；意識不清者禁止給予飲料，以免嗆入呼吸道。不可隨意翻動傷患。"},{"c":3,"n":2,"q":"中風案主若有嘔吐現象，應採取何種姿勢？","o":["平躺仰臥","平躺腳抬高","半坐臥","側臥"],"a":4,"e":"嘔吐時採側臥，讓嘔吐物流出，避免吸入呼吸道。"},{"c":3,"n":3,"q":"進行急救時，最重要的原則是","o":["儘速送醫","評估傷患處理順序","擺放傷患於正確姿勢","安全第一"],"a":4,"e":"急救首要原則是安全第一，確保施救者與傷患都不會再受傷。"},{"c":3,"n":4,"q":"高血壓案主突然臉色潮紅，意識不清，應採取下列何項姿勢？","o":["平躺仰臥","平躺頭肩墊高","膝胸臥式","平躺腳抬高"],"a":2,"e":"疑似腦出血時平躺並墊高頭肩，可降低顱內壓。"},{"c":3,"n":5,"q":"心臟衰竭的案主出現呼吸很喘時，應採下列何項姿勢？","o":["半坐臥","平躺腳抬高","側臥","平躺仰臥"],"a":1,"e":"心衰竭呼吸喘時採半坐臥，可減少回心血量、利於橫膈擴張。"},{"c":3,"n":6,"q":"案主抱怨腹痛不適，可協助案主採取下列那一種姿勢？","o":["屈膝仰臥","俯臥","側臥","平躺頭肩墊高"],"a":1,"e":"屈膝仰臥可放鬆腹肌，減輕腹痛。"},{"c":3,"n":7,"q":"執行口對口人工呼吸時，下列敘述何者不正確？","o":["吹氣時，一手捏緊被照顧者鼻子，將氣體由被照顧者口腔內吹入","吹氣後，將手及口移開，讓被照顧者肺部內氣體排出","在吹氣時要同時注意被照顧者胸部起伏程度","一旦被照顧者有頸動脈跳動後，即可停止吹氣"],"a":4,"e":"恢復頸動脈搏動不代表恢復呼吸，必須有自發性呼吸才能停止吹氣。"},{"c":3,"n":8,"q":"執行胸外心臟按摩時，施救者的掌跟應置於案主何處？","o":["劍突上二橫指","劍突處","劍突下二橫指","劍突左側胸骨緣"],"a":1,"e":"按壓位置在胸骨下半段，約劍突上兩橫指處（兩乳頭連線中點）。"},{"c":3,"n":9,"q":"施行人工呼吸時，若案主胸部沒有起伏，應立刻採取下列何項措施？","o":["準備執行腹戳法","檢查心跳，看案主是否已死亡","清除案主口腔內異物","重新調整患者頭部位置，提下巴壓額再試一次"],"a":4,"e":"吹氣時胸部沒有起伏，多是呼吸道未打開，應重新壓額抬下巴再試一次。"},{"c":3,"n":10,"q":"若案主出現下列何種症狀，即可停止胸外心臟按摩？","o":["瞳孔散大","膚色轉紅潤","有自發性心跳，每分鐘 40 次","有自發性呼吸，每分鐘 12 次"],"a":4,"e":"恢復有效的自發性呼吸與循環才停止CPR；心跳每分鐘40次不足以維持循環。"},{"c":3,"n":11,"q":"一個人心肺停止多久，腦細胞就會造成永久性損傷？","o":["3~5 秒","1~3 分鐘","4~5 分鐘","6 分鐘及以上"],"a":4,"e":"心肺停止約4～6分鐘腦細胞開始受損，超過6分鐘可能造成永久性損傷（依題庫答案）。"},{"c":3,"n":12,"q":"施行胸外心臟按摩時，成人下壓深度應為多少為宜？","o":["1〜2 公分","3〜4 公分","5〜6 公分","7〜8 公分"],"a":3,"e":"成人胸外按壓深度5～6公分。"},{"c":3,"n":13,"q":"下列何者為急救時需第一優先處理的狀況？","o":["維持呼吸道通暢","控制出血","預防及治療休克","固定骨折"],"a":1,"e":"急救的第一優先是維持呼吸道通暢（ABC中的A）。"},{"c":3,"n":14,"q":"在執行心肺復甦術時，若施救者只有一人，則每分鐘胸外心臟按摩之速率為","o":["60 次","80 次","100 次","130 次"],"a":3,"e":"成人按壓速率每分鐘100～120次。"},{"c":3,"n":15,"q":"在急救過程中，以抬下巴壓額法維持被照顧者呼吸道通暢後，接著應執行的步驟為何？","o":["協助被照顧者側臥","執行推腹法","立刻進行人工呼吸","評估呼吸"],"a":4,"e":"打開呼吸道後，接著要評估有沒有正常呼吸。"},{"c":3,"n":16,"q":"在一個人施救情形下，執行心肺復甦術時，胸外心臟按摩與人工呼吸的比例為","o":["5：1","10：2","20：2","30：2"],"a":4,"e":"成人CPR，單人或雙人施救都是按壓30次、吹氣2次。"},{"c":3,"n":17,"q":"兩人施救法時，胸外心臟按摩的速率，下列何者正確？","o":["60 次/分","80 次 /分","100 次/分","130 次/分"],"a":3,"e":"雙人施救的按壓速率同樣是每分鐘100～120次。"},{"c":3,"n":18,"q":"有關胸外心臟按摩的敘述，下列何者正確？","o":["雙手十指互扣，下手掌手指緊壓胸部以施力","按摩時雙手臂不能彎曲","胸骨下壓 1-3 公分深度","按壓後，雙手離開被照顧者胸部以利血液回流"],"a":2,"e":"按壓時手肘打直，利用上半身的重量垂直下壓；掌根不離開胸部。"},{"c":3,"n":19,"q":"若案主有出血、骨折及呼吸停止時，第一優先要採取的措施為","o":["止血","人工呼吸","固定","送醫"],"a":2,"e":"呼吸停止會直接危及生命，應最優先處理。"},{"c":3,"n":20,"q":"心肺復甦術進行口對口人工呼吸要吹幾口氣？","o":["1","2","3","4"],"a":2,"e":"每30次按壓後吹氣2口。"},{"c":3,"n":21,"q":"孕婦食物哽噎時應使用","o":["胸戳法","腹戳法","拍背法","咳嗽法"],"a":1,"e":"孕婦腹部大，不可壓腹部，應改用胸戳法。"},{"c":3,"n":22,"q":"只有一人施行心肺復甦術，下列何者不正確？","o":["每壓 30 下吹 2 口氣","大聲數出按壓的次數","每壓 15 下吹 1 口氣","進行心肺復甦術後約二分鐘檢查脈搏"],"a":3,"e":"成人CPR比例是30：2，不是15：1。"},{"c":3,"n":23,"q":"對於居家照顧的案主，下列哪一種狀況得優先做處理？","o":["出血","活動量不足","營養狀況不佳","情緒不好"],"a":1,"e":"出血可能危及生命，應優先處理。"},{"c":3,"n":24,"q":"下列何者為最佳止血法？","o":["直接加壓法","抬高傷肢法","止血點止血法","止血帶止血法"],"a":1,"e":"直接加壓止血法最簡單、有效又安全。"},{"c":3,"n":25,"q":"下列何者為固定四肢關節的繃帶包紮法？","o":["緩螺旋包紮法","環狀包紮法","八字型包紮法","急螺旋型包紮法"],"a":3,"e":"八字型包紮法適用於關節部位，如肘、膝、踝。"},{"c":3,"n":26,"q":"對於繃帶包紮法之螺旋形包紮法，下列敘述何者正確？","o":["用於鼠蹊部、拇指處之包紮","用於包紮粗細不一之部位","用於限制關節活動","用於頭部或截肢後殘肢的包紮"],"a":2,"e":"螺旋形包紮用於粗細不一的部位，如前臂、小腿。"},{"c":3,"n":27,"q":"下列何者是適當的繃帶結帶固定處？","o":["肢體內側","關節處","傷口處","肢體外側平滑處"],"a":4,"e":"結帶應固定在肢體外側平滑處，避開傷口、關節與內側。"},{"c":3,"n":28,"q":"繃帶包紮肢體若出現下列哪些現象應立刻鬆開繃帶？A.肢體發癢B.肢體蒼白C.肢體活動較慢D.肢體刺痛","o":["AB","CD","AD","BD"],"a":4,"e":"包紮後出現肢體蒼白、刺痛、麻木，表示太緊，應立即鬆開。"},{"c":3,"n":29,"q":"當繃帶包紮時，案主肢體出現下列何種現象時，表示繃帶過緊，需要鬆開重新包紮？","o":["結帶固定帶處繃帶脫落","肢體溫度上升","肢體皮膚發紅","肢體感覺發麻"],"a":4,"e":"肢體發麻表示血液循環或神經受壓，繃帶太緊。"},{"c":3,"n":30,"q":"在使用繃帶包紮時，下列原則何者正確？","o":["包紮時，應逆向人體循環方向，由遠心端向近心端包紮","包紮肢體時，應包括肢體末端，以使壓力平均","包紮的肢體若有傷口，繃帶可直接與傷口接觸","包紮時，每包覆第二周時，應覆蓋前一周之 1/4～1/3"],"a":1,"e":"包紮由遠心端往近心端，順著靜脈回流方向。"},{"c":3,"n":31,"q":"執行繃帶包紮時，下列何者不恰當？","o":["傷口先蓋上敷料後再包紮","包紮時要注意傷肢的功能位置","包紮由肢體近心端往肢體末端包紮","包紮肢體時，需露出肢體末端以利觀察"],"a":3,"e":"包紮應由遠心端往近心端，不是由近往遠。"},{"c":3,"n":32,"q":"當您以彈性繃帶為案主做手部包紮，30分鐘後案主抱怨指頭有刺痛感，指頭顏色變白，下列措施何者正確？","o":["這是包紮後初期現象，久了就習慣了","待包紮時間滿 2 小時後再鬆開","立即鬆開繃帶，再重新包紮","繼續觀察，再決定下一步行動"],"a":3,"e":"指頭刺痛、變白代表血液循環受阻，必須立即鬆開重新包紮。"},{"c":3,"n":33,"q":"若案主有大出血情形，其脈搏可能出現","o":["洪脈","絲脈且快","絲脈且慢","正常脈"],"a":2,"e":"大出血時血量減少，心臟代償加快，脈搏變得細弱又快速。"},{"c":3,"n":34,"q":"若懷疑被照顧者有休克現象，應讓被照顧者採取何種臥姿？","o":["平躺頭肩墊高","半坐臥","平躺腳抬高","左側臥"],"a":3,"e":"休克時平躺並抬高腳，增加回心血量與腦部血流。"},{"c":3,"n":35,"q":"下列何者不是休克案主的早期症狀？","o":["臉色潮紅","冒冷汗","噁心、嘔吐","躁動不安"],"a":1,"e":"休克早期臉色蒼白、冒冷汗、躁動、噁心；臉色潮紅不是休克症狀。"},{"c":3,"n":36,"q":"陳先生在下床時，不小心扭傷了左腳踝，下列緊急處理措施何者正確？","o":["於腳踝處使用熱水袋熱敷，以減輕疼痛","於腳踝處濕熱敷，以促進傷口癒合","於腳踝處使用冰袋與熱水袋交替使用","於腳踝處冰敷，減輕局部腫脹"],"a":4,"e":"扭傷初期應冰敷，減輕腫脹與疼痛。"},{"c":3,"n":37,"q":"預防手部感染的最有效方法是","o":["擦抗菌乳液","戴手套","勤洗手","使用藥物"],"a":3,"e":"勤洗手是預防手部感染最有效的方法。"},{"c":3,"n":38,"q":"張先生在家中跌倒而致左腿骨折，此時的初步處理何者正確？","o":["清洗左腿傷口","固定傷處","將骨折復位","通知家屬"],"a":2,"e":"骨折先固定傷處，避免移位與二次傷害；不可自行復位。"},{"c":3,"n":39,"q":"肌肉骨骼損傷的初步處理，其第一步是下列何者？","o":["休息","熱敷","固定","抬高"],"a":3,"e":"肌肉骨骼損傷的第一步是固定，避免再受傷。"},{"c":3,"n":40,"q":"張太太在做運動時不慎扭傷右腳踝，下列何者為正確的處理方式？A.冷敷；B.熱敷；C.抬高；D.放低；E.按摩；F.固定","o":["ACE","BCE","ACF","BDE"],"a":3,"e":"扭傷處理：冷敷、抬高、固定；不可熱敷或按摩。"},{"c":3,"n":41,"q":"案主骨折部位以夾板固定後，若案主覺得不舒服，其處理為","o":["立即鬆綁","更換夾板","改用繃帶固定","繼續觀察"],"a":1,"e":"夾板固定後感到不適，可能太緊影響循環，應立即鬆綁並重新調整。"},{"c":3,"n":42,"q":"下列對於肢體脫臼的處理，何者不恰當？","o":["先做復位，以免傷到神經","冰敷並抬高傷處","以三角巾或繃帶固定傷處","儘速送醫"],"a":1,"e":"脫臼不可自行復位，以免傷及神經血管，應固定後送醫。"},{"c":3,"n":43,"q":"張先生吃飯時，因右手不靈活，導致喝湯時，不慎弄翻碗燙到右腳，此時最合宜的處理措施為何？","o":["立即送醫","在右腳塗以消炎藥膏","以冷水沖右腳 15〜30 分鐘","以乾淨衣物覆蓋右腳"],"a":3,"e":"燙傷應立即沖冷水15～30分鐘，降溫並減輕組織損傷。"},{"c":3,"n":44,"q":"張太太炒菜時，因油外溢而致鍋子起火，右手遭灼傷，此時的緊急處理步驟為A.沖冷水B.泡冷水C.水中脫衣服D.蓋住傷口E.送醫","o":["A→B→C→D →E","A→B→D→C→E","A→C→B→D→E","A→C→D→B→E"],"a":3,"e":"燙傷五步驟：沖→脫→泡→蓋→送。"},{"c":3,"n":45,"q":"油鍋起火時，下列何項是不恰當的處理措施？","o":["關閉瓦斯","潑水入鍋內","將鍋蓋蓋住油鍋","使用滅火器"],"a":2,"e":"油鍋起火潑水會使油火噴濺擴大，應關火後蓋鍋蓋。"},{"c":3,"n":46,"q":"災害發生時，緊急疏散脊椎受傷案主，下列何種方式不恰當？","o":["以硬板運送","以擔架運送","以椅子代用擔架","以毯子拖拉"],"a":4,"e":"脊椎受傷者需平穩固定運送，以毯子拖拉會使脊椎扭動。"},{"c":3,"n":47,"q":"火場逃生時，應立即協助案主採取下列那一種方式？","o":["走向樓梯間","低俯姿勢","直立姿勢","開窗呼救"],"a":2,"e":"火場中煙往上竄，採低姿勢可減少吸入濃煙。"},{"c":3,"n":48,"q":"在緊急情況下，您要將一位中風臥床案主由房間迅速移至安全場所，若只有您自己一人時，則下列何種緊急搬運法是較有效且省力的方法？","o":["肩扛搬運法","毛毯拖曳法","懸吊搬運法","抱持法"],"a":2,"e":"單人搬運臥床案主，毛毯拖曳法最省力且有效。"},{"c":3,"n":49,"q":"有關火災發生時的緊急處理，下列敘述何者錯誤？","o":["電線走火時，在電源切掉後才可以用水滅火","水是最好的滅火劑，所以任何情況下都可使用","電線走火時，應以乾粉滅火器滅火","離開火場時儘可能注意有無其他人員受傷或無法自行逃生者，應予適切之協助"],"a":2,"e":"電器或油類火災不可用水撲滅，水不是任何情況都適用。"},{"c":3,"n":50,"q":"有關發生火警時的緊急處理，下列何者有誤？","o":["滅火","報警","逃生","攜帶貴重物品"],"a":4,"e":"火警時不可為了攜帶貴重物品而延誤逃生。"},{"c":3,"n":51,"q":"有關肢體扭、撞傷時的處理措施，下列何者是正確的？","o":["立即熱敷按摩","立即冰敷","24 小時內都可以熱敷","48 小時後才可以冰敷"],"a":2,"e":"扭撞傷初期應立即冰敷，24～48小時後才可考慮熱敷。"},{"c":3,"n":52,"q":"有關跌倒者的協助措施，下列何者有誤？","o":["請案主動動手腳","請案主轉動脖子","請案主抬高手腳","把案主趕緊扶起"],"a":4,"e":"跌倒後不可急著扶起，應先評估意識與有無骨折等傷害。"},{"c":3,"n":53,"q":"在大樓火警逃生遇到緊閉的門時，下列措施何者正確？","o":["立即打開門以利逃走","立即離開尋找其他逃生口","先觀察門下，如有煙霧竄出表示不可以打開門","碰觸門把是熱的時，表示是可以打開門"],"a":3,"e":"門縫有煙或門把發燙，代表門外有火，不可開門，應另尋出路。"},{"c":3,"n":54,"q":"有關預防跌倒的安全照護措施，下列何者不當？","o":["使用鎮靜劑者，勿自行外出","限制曾經跌倒之被照顧者外出","密切巡視高齡者、心智障礙、意識不清等高危險的被照顧者","地面、走道、盥洗室需保持乾燥，並有防滑設施"],"a":2,"e":"限制外出會影響生活品質，應改善環境並加強陪伴，而不是限制。"},{"c":3,"n":55,"q":"有關地震時的避難措施，下列何者不正確？","o":["立即關閉電源","遠離窗戶以防玻璃震破受傷","叫案主即刻衝出戶外及使用電梯","逃生時穿鞋並以物品保護頭部"],"a":3,"e":"地震時不可衝出戶外，也不可搭電梯，應就地掩護。"},{"c":3,"n":56,"q":"以下傷患何者應優先送醫？","o":["扭傷","脫臼","多處骨折","開放性腹部傷害者"],"a":4,"e":"開放性腹部傷害可能有內臟損傷與大出血，應優先送醫。"},{"c":3,"n":57,"q":"下列何者不適合當漱口水？","o":["茶水","菜水","無糖檸檬水","多貝爾溶液"],"a":2,"e":"菜水含油與殘渣，不適合當漱口水。"},{"c":3,"n":58,"q":"意外災難時，運送中風或體重過重的案主，下列方法何者為宜？","o":["毛毯拖拉法","抱持法","背負法","肩負法"],"a":1,"e":"中風或體重過重的案主，以毛毯拖拉法運送最省力。"},{"c":3,"n":59,"q":"面對緊急事故，下列處理何者不適當？","o":["態度沉著","尋求支援","迅速離開現場","報告主管"],"a":3,"e":"遇到緊急事故不可擅自離開，應沉著處理、求援並報告。"},{"c":3,"n":60,"q":"照顧植物人，下列措施何者不適？","o":["不必跟他說話","固定時間翻身","給予背部按摩","給予四肢關節被動運動"],"a":1,"e":"植物人仍可能有聽覺，應持續與他說話、給予刺激。"},{"c":3,"n":61,"q":"王婆婆今早泡腳時不慎燙傷，雙腳出現紅腫、起水泡及強烈疼痛的情形，試問王婆婆燙傷程度為何？","o":["第一度燙傷","淺第二度燙傷","深第二度燙傷","第三度燙傷"],"a":2,"e":"紅腫、起水泡、劇痛是淺二度燙傷的表現。"},{"c":3,"n":62,"q":"有關灼燙傷的處理，下列何者不正確？","o":["立即沖冷水，水流不宜過強過大，但化學藥物燒傷除外","在水中脫衣服以避免對受損皮膚造成二度傷害","泡冷水可一直泡至不痛為止","眼睛灼傷時，宜使用大量清水由眼睛外角向內角沖洗"],"a":4,"e":"眼睛灼傷應由內眼角往外眼角沖洗，避免污水流進另一眼。"},{"c":3,"n":63,"q":"有關骨折之固定，下列何者為正確？","o":["用以固定骨折處之夾板，其長度必須超過骨折近端及遠端的關節","夾板與皮膚間應先墊柔軟的護墊","使用三角巾固定上肢時，手掌宜高於手肘約 10-15 公分","以上皆是"],"a":4,"e":"（本題已刪題）骨折固定的夾板要超過上下兩個關節、加襯墊，上肢懸吊時手掌略高於手肘。","d":1},{"c":3,"n":64,"q":"有關包紮之注意事項，下列何者為正確？","o":["為預防患者受寒，繃帶包紮時應裹住肢體末端","繃帶應打結固定於傷口部位內側平滑處","包紮時由遠心端往近心端方向包紮","對於胸骨骨折患者，應在患者吸氣時以彈性繃帶固定胸部"],"a":3,"e":"包紮應由遠心端往近心端，並露出肢體末端以便觀察。"},{"c":3,"n":65,"q":"下列何種姿勢適合於能自行呼吸，但無意識且脊椎未受損之昏迷傷患？","o":["平躺姿勢","半坐臥姿勢","復甦姿勢","頭低腳高姿勢"],"a":3,"e":"有呼吸但無意識、無脊椎損傷者採復甦姿勢（側臥），保持呼吸道通暢。"},{"c":3,"n":66,"q":"執行成人心肺復甦術之胸部按壓，下列敘述何者不正確？","o":["次數 100 次/ 分","按壓位置於劍突處","手勢採雙手互扣","按壓深度 5〜6 公分"],"a":2,"e":"按壓位置是胸骨下半段，不是劍突處，壓劍突可能造成內臟損傷。"},{"c":3,"n":67,"q":"成人自救腹戳法其雙手放置的位置為何處？","o":["劍突上兩橫指","兩乳頭連線終點","肚臍與劍突之間","乳頭連線下一橫指處"],"a":3,"e":"腹戳法的施力位置在肚臍與劍突之間。"},{"c":3,"n":68,"q":"下列何種姿勢適用於暈倒、休克患者？","o":["平躺、仰臥","平躺、腳墊高","半坐臥","側臥"],"a":2,"e":"暈倒、休克者平躺並抬高腳，可增加腦部血流。"},{"c":3,"n":69,"q":"依傷患救治和送醫優先順序原則，下列何種患者須第一優先，立即送醫處理？","o":["藥物中毒","開放性或多處骨折","已死亡傷患","急性心肌梗塞"],"a":4,"e":"急性心肌梗塞會危及生命，必須第一優先送醫。"},{"c":3,"n":70,"q":"急救時需最優先處理的狀況為何？","o":["維持呼吸道通暢","控制出血","固定骨折","預防休克"],"a":1,"e":"急救首要是維持呼吸道通暢。"},{"c":3,"n":71,"q":"下列何者為進行急救中，最重要原則？","o":["立即評估傷患","盡速安排傷患送醫","確定傷患和施救者處於安全無危險環境","將傷患置於正確、適當的姿勢"],"a":3,"e":"最重要的原則是確保傷患與施救者都在安全環境中。"},{"c":3,"n":72,"q":"有關擔架運送法之敘述，下列敘述何者不正確？","o":["適用於虛弱、昏迷患者","上下樓時，病人的腳部均在高處","上坡時頭在前，下坡時腳在前","脊椎損傷者宜使用硬板擔架"],"a":2,"e":"擔架運送時頭部應在較高處，上樓頭在前、下樓腳在前。"},{"c":3,"n":73,"q":"下列病人運送法，何者不適用於長距離運送者：","o":["抱持法","背負法","肩負法","以上皆非"],"a":1,"e":"抱持法只適合短距離搬運，長距離容易疲累。"},{"c":3,"n":74,"q":"下列何種病人運送法，適用於緊急運送體重比工作者重、中風臥床且無脊椎受傷之患者？","o":["毛毯拖拉法","抱持法","背負法","肩負法"],"a":1,"e":"毛毯拖拉法適合搬運比自己重、無脊椎損傷的臥床者。"},{"c":3,"n":75,"q":"地震時的避難措施，下列敘述何者不正確？","o":["立即關閉電源","立即衝出戶外","以墊子、枕頭或雙手保護頭部","躲避在樑柱或牆角邊"],"a":2,"e":"地震時立刻衝出戶外容易被掉落物砸傷，應先就地掩護。"},{"c":3,"n":76,"q":"有關高樓逃生之要訣，下列敘述何者不正確？","o":["利用繩索或被單、窗簾連接成滑帶逃生","使用繩索逃生時，上半身與腳部保持 L 型，背向牆壁","可逃至鄰近屋頂等待救援","勿冒險從高樓跳下"],"a":2,"e":"繩索逃生時應面向牆壁，雙腳抵住牆面慢慢下降。"},{"c":3,"n":77,"q":"發現火災的立即措施，下列敘述何者不正確？","o":["打開呼叫警鈴，叫醒所有的人","立即疏散所有的人","老弱婦孺需優先疏散","運送病人時打開室內的窗"],"a":4,"e":"運送病人時開窗會使空氣流入、助長火勢與濃煙。"},{"c":3,"n":78,"q":"下列何者是為不正確的火場逃生要訣？","o":["低姿勢","沿牆壁","向上逃","勿跳樓"],"a":3,"e":"火場逃生應往下逃，往上逃會遇到上竄的濃煙。"},{"c":3,"n":79,"q":"對於久病厭世、有自殺意念的案主，其照顧內容下列何者正確？","o":["勿讓其獨處","經常探視及提供心理支援","檢查及移去案主身邊的危險物品","以上皆是"],"a":4,"e":"自殺意念者不可讓他獨處、要經常探視支持、移除危險物品，以上皆是。"},{"c":3,"n":80,"q":"意外事件報告單，通常於意外發生的幾個小時內報告？","o":["24 小時","36 小時","48 小時","72 小時"],"a":1,"e":"意外事件應在發生後24小時內完成報告。"},{"c":3,"n":81,"q":"下列何者非跌倒的高危險群？","o":["高齡者","心智障礙","中風","入住機構時間較長的住民"],"a":4,"e":"入住機構時間較長、已熟悉環境的住民，不是跌倒高危險群。"},{"c":3,"n":82,"q":"有關預防跌倒之要點，下列何者為是？","o":["叫人鈴放置於病人隨手可得之處","調整合宜病床高度","盥洗室安置防滑墊","以上皆是"],"a":4,"e":"（本題已刪題）叫人鈴放在隨手可及處、調整床高、浴室放防滑墊，都是預防跌倒的要點。","d":1},{"c":3,"n":83,"q":"下列何種繃帶包紮法，其適用於較長或粗細不同的肢體？","o":["八字行包紮法","螺旋回反包紮法","螺旋包紮法","環狀包紮法"],"a":2,"e":"較長或粗細不同的肢體，可用螺旋回反包紮法，使繃帶服貼。"},{"c":3,"n":84,"q":"有關開放性骨折之緊急處理，下列敘述何者正確？","o":["於開放性傷口止血，但不要清洗傷口及塗藥","試著將突出骨頭推回復位","為避免再度受傷，維持受傷肢體平放","熱敷傷處以減輕疼痛"],"a":1,"e":"開放性骨折要止血、覆蓋傷口，但不要清洗、塗藥，也不要把骨頭推回。"},{"c":3,"n":85,"q":"有關脫臼之處理，下列敘述何者不正確？","o":["勿試著將脫臼骨頭推回復位","抬高脫臼肢體","冰敷脫臼處","使用三角巾包紮固定時，宜將結帶打結固定在肢體內側"],"a":4,"e":"結帶應打在肢體外側平滑處，不是內側。"},{"c":3,"n":86,"q":"下列那些傷患不適合採口對口人工呼吸法？","o":["農藥中毒","溺水","急性心肌梗塞","中風"],"a":1,"e":"農藥中毒者口中可能殘留毒物，口對口吹氣會使施救者中毒。"},{"c":3,"n":87,"q":"有關使用止血帶之注意事項，下列敘述何者不正確？","o":["勿使用金屬線、繩索作為止血帶","將止血帶放置在傷口","每隔 15-20 分鐘鬆開止血帶 15 秒","止血帶的部位須露出衣外"],"a":2,"e":"止血帶應綁在傷口上方（近心端），不可直接放在傷口上。"},{"c":3,"n":88,"q":"對於呼吸困難的患者，其適合之臥位為何？","o":["平躺、仰臥","平躺、腳墊高","半坐臥","側臥"],"a":3,"e":"呼吸困難時採半坐臥，使橫膈下降，有利呼吸。"},{"c":4,"n":1,"q":"當服務中遇到困難時，下列何種處理方式最好？","o":["自己處理","回報機構尋求協助","不去理會","找親友訴苦"],"a":2,"e":"服務遇到困難應回報機構尋求協助。"},{"c":4,"n":2,"q":"當案主提出與服務內容不符之過分要求時，應如何處理？","o":["立即要求結案","與案主對立、抗爭","委曲求全","婉轉溝通再通知機構"],"a":4,"e":"案主提出超出服務範圍的要求，應婉轉溝通並通知機構。"},{"c":4,"n":3,"q":"照顧被照顧者時，因協調溝通不良，最好的處理方法","o":["馬上離開不再溝通","結案","再溝通","不理會"],"a":3,"e":"溝通不良時應再次溝通，找出誤解所在。"},{"c":4,"n":4,"q":"有效的溝通技巧不包括","o":["不斷的解釋","傾聽","同理心","專注行為"],"a":1,"e":"有效溝通重在傾聽、同理與專注，不斷解釋反而會造成防衛。"},{"c":4,"n":5,"q":"與失能長輩溝通時須注意的事項很多，其中不包括","o":["彼此語言和文化差異","以高亢快速的聲音與長輩交談","耐心聽完長輩的敘述","請案家從旁協助"],"a":2,"e":"與失能長輩說話要低沉、緩慢，高亢快速的聲音會聽不清楚。"},{"c":4,"n":6,"q":"與被照顧者家屬溝通時，下列何種方式錯誤？","o":["設身處地感受家屬的照顧壓力","積極給予家屬建議並要求家屬依照建議改變","擔任被照顧者與家屬間的橋樑","真心關懷"],"a":2,"e":"應尊重家屬的決定，不可強迫家屬照你的建議改變。"},{"c":4,"n":7,"q":"下列哪一項無助於良好的溝通？","o":["和案主視線接觸","身體前傾表達出關心和注意","提高音量大聲講話","鼓勵案主多表達感受"],"a":3,"e":"大聲講話會讓人感到被責備，應以適中音量、清楚緩慢地說話。"},{"c":4,"n":8,"q":"下列敘述何者正確？","o":["照顧過程案主容易出現不好的情緒，這是可以被接受與同理的","照顧服務員已受過職前訓練，以後從事服務工作可以不需要再進修與準備","照顧服務員可以任意和同伴討論案主及其家庭的隱私以便經驗交流","每一位中風案主的需求和照顧方式都是一樣的"],"a":1,"e":"照顧過程中案主出現負面情緒是正常的，應接納並同理。"},{"c":4,"n":9,"q":"對於表現異常的機構住民，照顧服務員應採取的合宜態度為","o":["指責住民不是，不予理會","伺機報復予以刁難","暫時離開現場，向機構反映","若被打則應抵抗反擊"],"a":3,"e":"面對異常行為，應暫時離開現場以確保安全，並向機構反映。"},{"c":4,"n":10,"q":"服務時為避免性騷擾，照顧服務員應有的態度，下列何者錯誤？","o":["轉移案主不合宜的行為或話題","滿足案主需要","維持專業上的人際關係","請其他專業人員協調"],"a":2,"e":"面對性騷擾應轉移話題、維持專業界線並尋求協助，不可滿足其要求。"},{"c":4,"n":11,"q":"有關服務內容的制定，以下何者正確？","o":["係機構規定，不需與被照顧者溝通","與付費的家屬溝通即可，不需瞭解被照顧者的看法","政府補助的部份一切按規定辦理，不需與被照顧者討論","須事先與被照顧者及被照顧者家屬充分溝通和說明，取得共識"],"a":4,"e":"服務內容應事先與被照顧者及家屬充分溝通，取得共識。"},{"c":4,"n":12,"q":"下列有關人際關係的敘述何者不正確？","o":["每個人皆需要人際關係","親子關係不屬於人際關係的一環","美好的人際關係可以創造生命延年益壽","人際關係可說是人類生活的主要核心"],"a":2,"e":"親子關係也是人際關係的一部分。"},{"c":4,"n":13,"q":"當案主主訴或表情顯現不舒服時，照顧服務員可以做的是","o":["安撫案主睡覺","不予理會","自行給案主吃藥","收集症狀資料並通知家屬"],"a":4,"e":"案主不舒服時應收集症狀資料並通知家屬，不可自行給藥。"},{"c":4,"n":14,"q":"長期照顧的目的在於","o":["協助案主維持日常生活中所需的功能","為了案主的舒適和照顧服務員的效率，凡事都由照顧服務員替案主完成","由照顧服務員取代家人的照顧角色","建立案主的信任關係，使其完全依賴照顧服務員"],"a":1,"e":"長期照顧的目的是協助案主維持日常生活功能。"},{"c":4,"n":15,"q":"下列何者並非可能造成老年人心理調適困難的因素？","o":["地位、權勢改變趨於弱勢","子孫滿堂","功能衰退，變孤單","面對死亡的來臨"],"a":2,"e":"子孫滿堂是支持因素，不會造成心理調適困難。"},{"c":4,"n":16,"q":"長期不活動所造成的現象，不包括哪一項？","o":["感覺改變","自律神經系統安定","情緒障礙","肌肉萎縮"],"a":2,"e":"長期不活動會使自律神經失調，不會變得安定。"},{"c":4,"n":17,"q":"下列何者才算身心障礙者權益保障法所涵蓋之對象？","o":["失智症者","糖尿病患","心臟病患","高血壓患者"],"a":1,"e":"失智症者可經鑑定取得身心障礙證明，屬於身權法保障的對象。"},{"c":4,"n":18,"q":"常見的有關失智症十大症狀之描述何者為非？","o":["近期記憶喪失","失去定向感","情緒及個性改變","肌肉僵直"],"a":4,"e":"肌肉僵直是巴金森氏症的症狀，不屬於失智症十大警訊。"},{"c":4,"n":19,"q":"如何協助身體功能障礙者增進生活適應？","o":["使其完全臥床","完全順從案主的意思","使用適當的輔具","大量給予刺激以利復原"],"a":3,"e":"使用適當的輔具，可以幫助功能障礙者提升生活自理能力。"},{"c":4,"n":20,"q":"下列哪一項會妨礙與聽力障礙者之溝通？","o":["保持昏暗的光線","輪流發言，不要同時說話","儘量保持環境的單純","儘量在聽障者面前說話"],"a":1,"e":"光線昏暗時聽障者無法讀唇與看表情，會妨礙溝通。"},{"c":4,"n":21,"q":"下列何者並非智能不足者的溝通特徵？","o":["語言理解能力不足","有限的口語能力或無口語能力","口語清晰度不足","溝通內容多為抽象不具體的"],"a":4,"e":"智能不足者的溝通內容多為具體事物，較難理解抽象概念。"},{"c":4,"n":22,"q":"下列有關脊髓損傷的描述，何者不正確？","o":["外傷性傷害或腫瘤皆可能造成","容易發生在老年人","影響所及包括心跳、血壓、呼吸、排汗、大小便控制及性功能等","心理挫折、經濟問題等也跟著浮現"],"a":2,"e":"脊髓損傷多發生在年輕人（如車禍、運動傷害），並非好發於老年人。"},{"c":4,"n":23,"q":"照顧者在照顧過程中須承受許多壓力，易罹患下列何種疾病？","o":["痛風","白內障","骨折","胃潰瘍"],"a":4,"e":"長期壓力容易造成胃潰瘍等身心症。"},{"c":4,"n":24,"q":"家庭照顧者採取下列何種紓解壓力的方式不妥當？","o":["參加家屬支持團體","鍛鍊體力","設定合理的照顧目標及自我期待","對照顧服務員發洩、出氣"],"a":4,"e":"向照顧服務員發洩是不當的紓壓方式，會破壞合作關係。"},{"c":4,"n":25,"q":"下列哪一項並非家庭照顧者所承受與照顧壓力有關的壓力來源？","o":["照顧知識不足","股市漲跌","缺少社會支持","生活作息受限制"],"a":2,"e":"股市漲跌與照顧工作無關，不是照顧壓力的來源。"},{"c":4,"n":26,"q":"有關壓力的描述何者不正確？","o":["壓力處理得宜，會成為助力","過度的壓力會引起身心的疾病","再大的壓力都要自己解決無須求助專業協助","同一個人第一次及第二次面對壓力的反應不盡相同"],"a":3,"e":"壓力大時應適時尋求專業協助，不必獨自承擔。"},{"c":4,"n":27,"q":"壓力調適的方法不包括","o":["認識問題","對自己有信心","處理問題的行動意願","一昧躲避不去面對"],"a":4,"e":"一味逃避問題無法調適壓力，應面對並處理。"},{"c":4,"n":28,"q":"預防厭世案主自殺，以下處置方式何者不合適？","o":["注意其行為是否有異於平常","注意其談話內容，是否常提到死","移除案主身邊危險物品","讓他獨處冷靜，不要吵他"],"a":4,"e":"有自殺念頭者不可讓他獨處，應密切陪伴。"},{"c":4,"n":29,"q":"人臨終前，最後消失的感覺器官是？","o":["味覺","嗅覺","聽覺","視覺"],"a":3,"e":"臨終時聽覺通常最後消失，家人可以持續和他說話。"},{"c":4,"n":30,"q":"照顧服務員照顧臨終被照顧者時，應如何感受家屬的心理","o":["同理心","同情心","決心","否定心"],"a":1,"e":"以同理心感受家屬的心理，給予支持。"},{"c":4,"n":31,"q":"下列何者不是安寧照顧的精神？","o":["只尊重案主的個人感受，不需顧及家屬","強調要活得有尊嚴","緩和及支持治療","注重全人、全家、全程、全隊四全照顧"],"a":1,"e":"安寧照顧強調全人、全家、全程、全隊，也要照顧家屬。"},{"c":4,"n":32,"q":"對於臨終案主的協助方法，何者錯誤？","o":["儘可能減輕案主的不適","照顧服務員自己對瀕死過程的態度並不重要，不需處理","給予案主情緒支持","支持臨終案主的家屬"],"a":2,"e":"照顧者自己對死亡的態度會影響照顧品質，也需要處理與調適。"},{"c":4,"n":33,"q":"下列何人不是安寧療護主要醫療團隊之成員？","o":["醫師","神職人員","社工師","語言治療師"],"a":4,"e":"安寧團隊包括醫師、護理師、社工師、宗教人員等；語言治療師不是主要成員。"},{"c":4,"n":34,"q":"臨終關懷的目標不包括以下哪一項？","o":["讓每個人免於死亡的痛苦","讓每個人享有安詳去世的人權","讓案主安樂死以得到解脫","讓每個人生死無悔"],"a":3,"e":"臨終關懷的目標是善終，不包括安樂死（我國不合法）。"},{"c":4,"n":35,"q":"安寧療護的四全照顧指的是什麼？","o":["全人、全家、全程、全隊","全心、全意、全部、全職","全人、全家、全心、全意","全心、全意、全程、全隊"],"a":1,"e":"安寧四全照顧：全人、全家、全程、全隊。"},{"c":4,"n":36,"q":"下列何者並不是癌末臨終者初期心理反應所經過的階段？","o":["震驚","解脫","否認","生氣"],"a":2,"e":"臨終心理反應包括震驚、否認、憤怒、討價還價、憂鬱、接受；解脫不在其中。"},{"c":4,"n":37,"q":"下列何者並不是屍體護理的正確做法？","o":["身體拉直，取下假牙","頭肩部以枕頭墊高，避免血液停留而改變臉部顏色","擦拭身體，清潔傷口，減少異味","為預防大小便失禁，使用尿布包好"],"a":1,"e":"題庫判定選項1錯誤；屍體護理時假牙應裝回以維持面容，並使身體呈平躺姿勢。"},{"c":4,"n":38,"q":"下列何者不符合『DNR（不予急救）之規定』？","o":["醫師應將治療方針詳盡告知病人，病人意識昏迷時則應告知家屬，以保障其權益","應有意願人簽署之意願書","未成年人簽署意願書時，應得其法定代理人之同意","應由三至四位醫師診斷確為末期病人"],"a":4,"e":"DNR規定為2位專科醫師診斷為末期病人，不是3～4位。"},{"c":4,"n":39,"q":"當照顧服務員發現案主出現瀕死症狀時，以下何種措施不正確？","o":["持續密切觀察其生命徵象","通知家屬或機構","提醒家人通知殯葬禮儀公司","維持案主身體清潔及舒適"],"a":3,"e":"發現瀕死症狀時，通知殯葬業者是家屬的決定，照服員不應主動提醒。"},{"c":4,"n":40,"q":"對照顧多年植物人案家，最適當的支援是那一項？","o":["聽家中照顧者的辛苦經","提供社會資源諮詢","詢問最愛吃什麼","請多多加油"],"a":2,"e":"提供社會資源諮詢，可以實際減輕長期照顧家庭的負擔。"},{"c":4,"n":41,"q":"有關醫療照護機構聘用照顧服務員真正的意義，下列何者不正確？","o":["減少家人照顧的壓力","減少案主意外事故的發生率","取代護理人力","案主能得到全責照顧"],"a":3,"e":"照顧服務員是協助日常生活照顧，不能取代護理人力。"},{"c":4,"n":42,"q":"與案家發生服務項目爭議時，下列行為何者正確？A.指責案主及案家B.坦然接受C.共同閱讀約定的服務內容D.請主管代為解釋","o":["AB","BC","CD","AD"],"a":3,"e":"發生服務爭議時，應共同閱讀約定的服務內容，必要時請主管說明。"},{"c":4,"n":43,"q":"對睡不好且夜間常常醒來就上廁所的案主，何者為適當的照顧？","o":["給予安眠藥","這是老人的老毛病，不要去理會","說明這是新入住的人常有的現象","就寢前請上廁所並準備移動式便器在床邊"],"a":4,"e":"睡前先上廁所、床邊放置便器，可以減少夜間起床跌倒。"},{"c":4,"n":44,"q":"與高齡者的溝通，下列何者不適宜？","o":["依案主的步調行動","案主有錯誤行為立即指責糾正","每一動作每一次指導，強調重點","態度誠懇，友善對待案主"],"a":2,"e":"案主有錯誤行為時應溫和引導，立即指責會傷害自尊。"},{"c":4,"n":45,"q":"對被告知罹患癌症的案主之照顧措施，哪一項是適當的溝通法？","o":["將病名再確認一次","一直沈默，等案主開口","解釋癌症末期的症狀","觸摸案主的手、肩，直到案主情緒穩定"],"a":4,"e":"以觸摸手、肩等非語言方式陪伴，可以給予情緒支持。"},{"c":4,"n":46,"q":"住在安養院的失智老人抱怨錢不見了，下列何者為適當的處理？","o":["告訴他這裡不會丟錢","指責他有病","一齊尋找並轉移話題","不要理會他"],"a":3,"e":"陪失智老人一起找並轉移注意力，可以安撫情緒、避免爭辯。"},{"c":4,"n":47,"q":"有關溝通的內容，下列何者不適當？","o":["以被照顧者的健康照顧需要為主","一次教導多項的知識","重覆敘述重要的訊息","不要只說被照顧者失敗的事"],"a":2,"e":"一次只教一件事，失智或高齡者才記得住。"},{"c":4,"n":48,"q":"因照顧案主而有挫折感、憂鬱感，是屬於下列何種負荷？","o":["社會羞恥負荷","負向情緒負荷","病患依賴負荷","人際關係負荷"],"a":2,"e":"挫折感、憂鬱感屬於負向情緒負荷。"},{"c":4,"n":49,"q":"藉著外出吃美食、逛街或購物來調適工作壓力是一種","o":["逃避作用","潛抑作用","合理化作用","清除作用"],"a":4,"e":"透過外出吃美食、逛街購物抒發壓力，屬於「清除作用」。"},{"c":4,"n":50,"q":"有關在宅瀕死的照顧，下列何者不適宜？","o":["聽從案家的意見不再照顧","繼續緩解疼痛與不適","協助案家接納死亡來臨的事實","鼓勵臨終者發表心中的疑慮並協助解決與支持"],"a":1,"e":"臨終照顧應持續提供，不可因此放棄照顧。"},{"c":4,"n":51,"q":"有關長期照顧機構的安全管理，何者為適切的？","o":["案主在機構內發生的意外不必向案家說","為保護案主的秘密，不應向主管報告發生了意外","任何意外事故都應依規定報告","意外事故的發生一定要懲罰當事者"],"a":3,"e":"任何意外事故都應依規定報告，以便改善與保障各方。"},{"c":4,"n":52,"q":"有關慢性病老人居家照顧的優點，下列何者不正確？","o":["留在家裡可享受家庭溫暖","被監視的感覺較低","可預防與延遲入住機構的時間","在成本效益分析上，居家式的照顧較機構式的照顧昂貴"],"a":4,"e":"居家照顧一般比機構照顧便宜。"},{"c":4,"n":53,"q":"下列有效的協商功能，何者不正確？","o":["尋求雙贏的結果","建立信賴、扶持的關係","集思廣益，加強參與感","以照顧服務員的意見為主"],"a":4,"e":"協商應尋求雙贏與參與，不是以照服員的意見為主。"},{"c":4,"n":54,"q":"對於處於憤怒且可能出現暴力行為的案主，照顧服務員應採取的合宜態度為A.予以反擊B.予以責難C.暫時離開情境D.尋求協助","o":["AB","CD","AC","BD"],"a":2,"e":"面對可能暴力的案主，應暫時離開情境並尋求協助。"},{"c":4,"n":55,"q":"照顧服務員至案家服務，一進門即聞到很濃的瓦斯味時，最優先的處理措施是","o":["打開電風扇吹散瓦斯味","通知瓦斯公司前來處理","打開電燈尋找瓦斯漏氣來源","打開窗戶讓空氣流通"],"a":4,"e":"聞到瓦斯味應立即開窗通風，不可開電器或點火，以免火花引爆。"},{"c":4,"n":56,"q":"照顧案主時，下列措施那一項不正確？","o":["傾聽案主談話","注意觀察案主非口語行為","不停的抱怨工作辛苦","多瞭解案主的想法和需要"],"a":3,"e":"不停抱怨工作辛苦會影響專業形象與照顧關係。"},{"c":4,"n":57,"q":"照顧者常要在各種角色間疲於奔命，是屬於以下哪一類的壓力源？","o":["心理情緒方面","經濟方面","生理方面","專業技能方面"],"a":1,"e":"在多重角色間疲於奔命，屬於心理情緒方面的壓力源。"},{"c":4,"n":58,"q":"當被照顧者的家屬之間出現不同的照顧意見時，照顧服務員應如何處理？","o":["主動介入調停","提供自己的意見","要求被照顧者表達意見","請督導員協助處理"],"a":4,"e":"家屬意見不一時，應請督導員協助處理，照服員不宜介入。"},{"c":4,"n":59,"q":"照顧服務員在案家提供家務處理時，最重要的工作任務為何？","o":["維持客廳清潔","維護案主的居家安全","浴室無臭味","清潔窗戶"],"a":2,"e":"居家服務最重要的是維護案主的居家安全。"},{"c":4,"n":60,"q":"照顧服務員是家庭照顧者的好幫手，可藉由下列何種服務來紓解家庭照顧者之心理壓力？","o":["理財服務","傾聽、情緒支援","環境清潔","採購服務"],"a":2,"e":"傾聽與情緒支持可以紓解家庭照顧者的心理壓力。"},{"c":4,"n":61,"q":"「喘息服務」主要是維持下列何者身心健康的措施？","o":["案主","家庭主要照顧者","照顧服務員","醫護人員"],"a":2,"e":"喘息服務是讓家庭主要照顧者暫時休息，維護其身心健康。"},{"c":4,"n":62,"q":"當家中出現一位慢性病患，其主要照顧者往往也會成為潛在的案主，需在平時多給予支援，下列哪一項敘述為錯誤？","o":["主要照顧者需要定期休假","傾聽主要照顧者的心聲","照顧慢性病患不會加重主要照顧者的壓力","居家服務可以降低照顧者的壓力"],"a":3,"e":"照顧慢性病患會增加主要照顧者的壓力。"},{"c":4,"n":63,"q":"當照顧服務員提供居家服務時，雖然協助的對象是案主，同時對家庭中何人最有紓解壓力的幫助？","o":["主要照顧者","案媳","案女","案子"],"a":1,"e":"居家服務最能直接減輕主要照顧者的負擔。"},{"c":4,"n":64,"q":"家庭照顧支援體系是屬於案主的何種支援體系？","o":["正式照顧支援體系","非正式照顧支援體系","自然支援體系","非自然的支援體系"],"a":2,"e":"家人親友屬於非正式支援體系。"},{"c":4,"n":65,"q":"一般家庭照顧體系提供案主的服務不包括下列哪一項？","o":["情感支援","護送和交通接送","財務管理","醫療服務"],"a":4,"e":"醫療服務由醫療專業人員提供，不屬於家庭照顧體系的服務。"},{"c":4,"n":66,"q":"下列哪一族群屬案主的正式照顧體系？","o":["照顧服務員","家人","親朋","鄰居"],"a":1,"e":"照顧服務員屬於正式照顧體系。"},{"c":4,"n":67,"q":"一般老年人在生活上，誰是最重要的支援者？","o":["配偶","子媳","孫子","女兒"],"a":1,"e":"配偶通常是老年人最重要的支援者。"},{"c":4,"n":68,"q":"兄弟姊妹最適合提供下列何種類型之支援？","o":["醫療支援","情緒支援","家務支援","技術支援"],"a":2,"e":"兄弟姊妹最適合提供情緒支援。"},{"c":4,"n":69,"q":"台灣地區老人之支援體系主要來源為何？","o":["家庭成員","朋友","鄰居","照顧服務員"],"a":1,"e":"台灣老人的支援主要來自家庭成員。"},{"c":4,"n":70,"q":"照顧工作經常會帶給家庭主要照顧者身體、心理、社會外尚有哪一方面的負荷？","o":["住宅","財務","交通","飲食"],"a":2,"e":"照顧工作也會帶來財務負荷。"},{"c":4,"n":71,"q":"下列哪一項措施是分擔家庭照顧者的勞務？","o":["居家服務","國民年金","老年津貼","留職停薪制度"],"a":1,"e":"居家服務能直接分擔家庭照顧者的照顧勞務。"},{"c":4,"n":72,"q":"照顧是一種「愛的勞務」且全年無休，故照顧服務員必須要有何種觀念照顧工作才能持久？","o":["自我學習","自我奮鬥","自我健康維護","自我憐憫"],"a":3,"e":"照顧工作要持久，照顧者要先維護自己的健康。"},{"c":4,"n":73,"q":"當照顧者出現下列何種狀況時，表示需要協助了？","o":["失眠","經常運動","經常與朋友訴苦","會參加聚會"],"a":1,"e":"照顧者出現失眠，是壓力過大的警訊，需要協助。"},{"c":4,"n":74,"q":"家庭照顧者被發現脾氣變壞了，正向的改善的方法不包含下列哪一項？","o":["找人聊天吃飯","外出散步或安排度假","參加支援團體","一人獨處哭泣"],"a":4,"e":"一個人獨處哭泣無法改善壓力，應尋求支持。"},{"c":4,"n":75,"q":"家庭照顧者要尋求外界資源協助時可以向當地哪個單位尋求協助？","o":["戶政事務所","內政部警政署","警察局","長期照顧管理中心"],"a":4,"e":"長期照顧管理中心是長照服務的單一窗口。"},{"c":4,"n":76,"q":"失智症的生活照顧可以向政府哪一個單位尋求協助？","o":["勞工局","社會局","民政局","新聞局"],"a":2,"e":"失智症的生活照顧可以向社會局（處）尋求協助。"},{"c":4,"n":77,"q":"一般人只會關心生病的人，常忽略身旁的照顧者，對於照顧者的協助，下列哪一項比較有效的？","o":["長期給予情感、財務及替代支援","給予口頭讚許","致送禮物","因照顧者繁忙故儘可能不去打擾"],"a":1,"e":"長期提供情感、財務與替代照顧的支援，才能真正幫到照顧者。"},{"c":4,"n":78,"q":"照顧服務員發現家屬疏忽對案主照顧時應如何處理？","o":["非常生氣，不願再去案家服務","向督導員報告，請督導員協助處理","私下向案親友報告","視而不見，只做分內的事"],"a":2,"e":"發現家屬疏忽照顧時，應向督導員報告處理。"},{"c":4,"n":79,"q":"照顧服務員有義務將案主健康及生活狀況主動告知何人？","o":["家屬","管區警員","里長","區長"],"a":1,"e":"案主的健康與生活狀況應主動告知家屬。"},{"c":4,"n":80,"q":"照顧服務員與案主及案家之間，應立基於哪項基本原則方能合作愉快？","o":["互利","互動","尊重與關懷","忍耐與關懷"],"a":3,"e":"雙方合作的基礎是尊重與關懷。"},{"c":4,"n":81,"q":"當家屬提出不合理的要求時，下列何者為照顧服務員適當的處理方式？","o":["與家屬抗辯","與親友訴苦","勉強答應","委婉拒絕並向督導員說明"],"a":4,"e":"面對不合理的要求，應委婉拒絕並向督導員說明。"},{"c":4,"n":82,"q":"與家屬溝通困難時，照顧服務員可採取下列何種方法？","o":["保持沉默","拒絕服務","求助於機構主管","逆來順受"],"a":3,"e":"與家屬溝通困難時，可以求助機構主管。"},{"c":4,"n":83,"q":"醫療人員視家庭照顧者為以下何種角色，有利於共同促進案主的照顧品質？","o":["既是共同案主，又是共事者","只是共同案主","只是消費者","是專業的共同夥伴"],"a":1,"e":"家庭照顧者既需要被協助（共同案主），也是照顧夥伴（共事者）。"},{"c":4,"n":84,"q":"接送家人就醫或代辦事項是屬於以下哪一類的照顧者壓力源？","o":["心理情緒方面","經濟方面","生理方面","專業技術方面"],"a":3,"e":"接送就醫、代辦事項需要體力與時間，屬於生理方面的壓力源。"},{"c":4,"n":85,"q":"照顧有褥瘡者，是哪一類的照顧壓力？","o":["心理情緒方面","經濟方面","生理方面","專業技術方面"],"a":4,"e":"照顧褥瘡需要專業技術，屬於專業技術方面的壓力。"},{"c":4,"n":86,"q":"原住民族委員會截至107年已認定的族群數為何？","o":["12 族","13 族","15 族","16 族"],"a":4,"e":"至107年，原住民族委員會認定的原住民族共16族。"},{"c":4,"n":87,"q":"原住民族長照2.0規劃建構原住民族整合型照顧，”以居家服務補部落長照之不足”，是屬於何種等級？","o":["A 級","B 級","C 級","D 級"],"a":3,"e":"在部落以居家服務補長照之不足，屬於C級（巷弄長照站）。"},{"c":4,"n":88,"q":"長照2.0擴大納入的原住民族服務對象，下列何者為非？","o":["50 歲以上失智症患者","55-64 歲失能平地原住民","49 歲以下失能身心障礙者","50 歲以上僅 IADL 失能之衰弱(frailty)老人"],"a":4,"e":"長照2.0擴大的對象包括50歲以上失智症、55～64歲失能平地原住民、49歲以下失能身障者，以及65歲以上僅IADL失能的衰弱老人；選項4年齡不符。"},{"c":4,"n":89,"q":"原住民族對健康與疾病常見的解釋模式，下列何者為非？","o":["自然病因論— 由一些不潔淨的東西所引起 (如女性經血)","超自然病因論—由神靈或鬼魂所引起","吃得下、可以工作就是健康","有感染流行感冒時要去聚會所聚會"],"a":4,"e":"流感期間到聚會所聚會會增加傳染，不是健康觀念。"},{"c":4,"n":90,"q":"有關原住民族文化安全的定義，下列何者為非？","o":["對於照顧行為是否安全必須由文化內部成員依其文化慣習來決定是否達到療癒的目的","打破被照顧者因為政策、經濟及制度上的歧視，所造成的健康不均等問題","文化就是表演及演唱而已","尊重不同族群文化價值與規範前題下，提供被照顧者有品質的照顧服務"],"a":3,"e":"文化不只是表演與唱歌，而是一套生活方式與價值觀。"},{"c":4,"n":91,"q":"對待身心障礙朋友的態度，下列何者為正確？","o":["憐憫與同情","憐憫與施捨","關懷與尊重","忍讓"],"a":3,"e":"對待身心障礙者應關懷與尊重，而不是憐憫。"},{"c":4,"n":92,"q":"與腦性麻痺症患者相處時，下列何者為非？","o":["要有耐心聽他講完話","鼓勵他參與談話發表自己意見","關懷與尊重","事事幫他完成"],"a":4,"e":"應鼓勵腦性麻痺者自己完成能力所及的事，而不是事事代勞。"},{"c":4,"n":93,"q":"與聽障者相處時，下列何者無法達到有效溝通？","o":["以筆談或手語或以圖片協助","和他面對面，請他看清楚你的唇形與表情","說話時，口中不要吃東西或嚼口香糖","提高聲調或音量"],"a":4,"e":"聽障者常有高頻音受損，提高音量反而失真，應面對面、用筆談或手語。"},{"c":4,"n":94,"q":"有關壓力調適的觀念，下列何者正確？","o":["壓力是可以完全消除","工作場所的壓力不會影響家庭生活，反之亦然","壓力不只是心事，與心理問題與身體狀態皆有關聯","壓力的來源是單一的不同壓力各自獨立存在，對個人不會產生交互作用的不良影響"],"a":3,"e":"壓力與心理、身體狀態都有關聯。"},{"c":4,"n":95,"q":"下列哪個選項中的兩個項目皆屬於工作壓力來源？A.工作環境太冷太熱；B.職業角色與職責明確；C.工作性質佳與工作方法正確；D.學以致用、能發揮所長；E.缺乏社會資源；F.團體凝聚力不夠","o":["AB","BC","CD","EF"],"a":4,"e":"缺乏社會資源與團體凝聚力不夠，都是工作壓力的來源。"},{"c":4,"n":96,"q":"下列哪一個項目不是自我檢測工作壓力的來源？","o":["覺得自己無法和周遭的人競爭","覺得自己稱職，可以處理自己的工作","不知道自己眼前有什麼升遷與前進的機會","覺得自己的工作負擔太重，以致在上班時間內無法完成"],"a":2,"e":"覺得自己稱職、能處理工作，是正向感受，不是壓力來源。"},{"c":4,"n":97,"q":"有關長期的抒壓養生方式，下列哪一個項目不正確？","o":["維他命 B 群的攝取","正向思考習慣培養","花費大批金錢購物","認識真正的自己，檢測工作壓力的來源"],"a":3,"e":"花大錢購物不是長期健康的紓壓方式。"},{"c":4,"n":98,"q":"有關壓力的觀念，下列哪一個項目是正確的？","o":["腹式呼吸及肌肉鬆弛法是簡易抒壓法","頭痛、頭暈、失眠乃與壓力無關的身心症狀","容易感冒、全身痠痛、肌肉緊繃乃與壓力無關的身心症狀","便秘、胃痛乃與壓力無關的身心症狀"],"a":1,"e":"腹式呼吸與肌肉放鬆法是簡單有效的紓壓方法。"},{"c":4,"n":99,"q":"有關失智者之心理特徵，下列敘述何者為非？","o":["經常處於不安狀態","判斷力衰退","容易有被害感","情緒不常起伏"],"a":4,"e":"失智者情緒容易起伏不定。"},{"c":4,"n":100,"q":"與失智長者溝通時應注意的技巧，下列何者為非？","o":["說話時視線交會","告訴對方我們的名字","說話時速度放慢","提供多元選擇"],"a":4,"e":"與失智者溝通應提供簡單的選擇，選項太多會造成混亂。"},{"c":4,"n":101,"q":"有關緊急疏解壓力的方法，下列哪一個項目是不需要開立醫囑，可以立即進行的？","o":["服用肌肉鬆弛劑","服用抗焦慮劑","服用助眠劑","鼓勵親人或摯友的關心與支持"],"a":4,"e":"親友的關心與支持不需醫囑，可以立即進行。"},{"c":4,"n":102,"q":"有關長期的紓壓養生方式，下列哪一個項目不正確?","o":["維他命 B 群的攝取","正向思考習慣培養","花費大批金錢購物","認識真正的自己，檢測工作壓力的來源"],"a":3,"e":"（本題已刪題）花費大批金錢購物不是長期健康的紓壓方式。","d":1},{"c":5,"n":1,"q":"下列何者不是職業傷害之原因？","o":["工作姿勢與方式不正確","遵循工作標準做事","照明度不足","工作量過多"],"a":2,"e":"遵循工作標準做事能預防職業傷害，不是傷害的原因。"},{"c":5,"n":2,"q":"照顧服務員在從事照顧工作時，不小心致使案主受傷，下列何種做法不恰當？","o":["儘速與服務單位聯絡，由服務單位協助處理","協助緊急就醫","不要讓服務單位知道，私下與案主協議解決","通知案主之緊急聯絡人"],"a":3,"e":"不可隱瞞或私下和解，應通知服務單位、協助就醫並聯絡家屬。"},{"c":5,"n":3,"q":"對扶養義務有數人的老年案主而言，下列何者為第一順位？","o":["兄弟姐妹","直系血親尊親屬","直系血親卑親屬","家長"],"a":3,"e":"依民法，負扶養義務的第一順位是直系血親卑親屬（子女、孫子女）。"},{"c":5,"n":4,"q":"下列何者不是身心障礙者權益保障法中對於身心障礙者的定義？","o":["因生理或心理因素使參與社會及從事生產工作活動功能受到限制","經鑑定符合主管機關所訂等級之障礙","領有身心障礙手冊","經訓練後具有工作能力"],"a":4,"e":"身權法的定義著重功能受限並經鑑定，與「經訓練後具有工作能力」無關。"},{"c":5,"n":5,"q":"開始提供服務後，才發現案主有其他需求及問題，照顧服務員應該如何做？","o":["幫忙聯絡其他相關機構協助解決","回報自己的服務單位，由專業人員協助、轉介","找其他照顧服務員商量對策","不在原訂的服務範圍，少管閒事"],"a":2,"e":"發現新需求應回報服務單位，由專業人員評估與轉介。"},{"c":5,"n":6,"q":"當訪客詢問被照顧者的私人事情時，下列何者錯誤？","o":["避免當著被照顧者的面和第三者討論被照顧者的事情","因為被照顧者回答很慢，乾脆由照顧服務員代替被照顧者回答問題","應以適合被照顧者年齡的態度對待他","若被照顧者可以自行回答，應引導被照顧者回答"],"a":2,"e":"被照顧者能回答時應讓他自己回答，尊重他的自主權。"},{"c":5,"n":7,"q":"當您開始接案，照顧長期臥床案主時，合宜的態度應該是","o":["重病、不易照顧者不要接","久病不癒者不要接","植物人不要接","視個人的能力學習接納照顧不同種類的案主"],"a":4,"e":"（本題已刪題）應依個人能力，以接納、學習的態度照顧不同狀況的案主。","d":1},{"c":5,"n":8,"q":"依老人福利法規定，所稱「老人」是指年滿幾歲以上的人？","o":["50 歲","65 歲","55 歲","70 歲"],"a":2,"e":"老人福利法所稱老人，是指年滿65歲以上的人。"},{"c":5,"n":9,"q":"照顧服務員與案主間連結的法律關係是屬於下列那一種？","o":["買賣關係","委任關係","租賃關係","借貸關係"],"a":2,"e":"照顧服務屬於受託處理事務，是委任關係。"},{"c":5,"n":10,"q":"下列何者符合身心障礙者權益保障法之規定？","o":["非視覺障礙者而從事按摩業","身心障礙者就業薪資應比照一般待遇","已建築完成之公共設施毋庸改善無障礙空間設備","身心障礙福利機構無庸申請主管機關許可即得自由設立"],"a":2,"e":"身心障礙者就業薪資應與一般人同工同酬。"},{"c":5,"n":11,"q":"當照顧服務員在工作過程中，與案主或案家對服務項目發生爭議時，當下應如何處置？","o":["馬上拒絕案主的要求","委婉地拒絕案主的要求，並說明服務契約的規定內容","答應為案主執行該項服務項目","要求案主應多負擔費用"],"a":2,"e":"發生爭議時，應委婉拒絕並說明服務契約的規定內容。"},{"c":5,"n":12,"q":"服務倫理而言，照顧服務員對於被照顧者的金錢，下列哪一項處理態度為宜？","o":["可以先行挪用","不可以挪用","可以先行商借，事後歸回就好","可以竊取"],"a":2,"e":"案主的金錢絕對不可以挪用。"},{"c":5,"n":13,"q":"失能老人如有因智力減退而發生不合宜的行為時，照顧服務員應","o":["給予更大的包容","好好糾正他","給予適當的處罰","不需理會他，當作沒看見"],"a":1,"e":"失智引起的不合宜行為不是故意的，應給予包容。"},{"c":5,"n":14,"q":"照顧服務員幫案主作關節運動，不慎造成案主骨折時，照顧服務員應負何種責任？","o":["過失傷害的刑責","蓄意傷害的刑責","只需負擔醫療費用","不需負任何責任"],"a":1,"e":"因疏忽造成傷害，可能涉及過失傷害刑責。"},{"c":5,"n":15,"q":"照顧服務員因臨時身體不舒服，無法前往案家服務案主時，應如何處理？","o":["私下委請其他同事代為照顧","通知所服務的單位，由該單位派請其他服務員代理","不要張揚，不要說","向案家請假告知無法去照顧即可"],"a":2,"e":"無法上班時應通知服務單位，由單位安排代班人員。"},{"c":5,"n":16,"q":"照顧失智的案主，因為案主記憶力大幅減退，常忘記日常瑣事，所以照顧服務員合宜的態度為","o":["反正也記不得，因此不需要和他多說什麼話","隨時都再一次告知或提醒","與他約法三章，如果案主忘了就不幫他做","提醒案主三次，再不記得就處罰他"],"a":2,"e":"失智者記憶減退，需要隨時耐心提醒。"},{"c":5,"n":17,"q":"關於被照顧者及其家屬所餽贈的禮物，照顧服務員應如何處理？","o":["收下即可","買一份等值禮品回贈給被照顧者或其家屬","告知被照顧者及其家屬，照顧服務員依工作守則不可以收","請被照顧者直接送給照顧服務員所屬之服務單位"],"a":3,"e":"依工作守則不可收受禮物，應婉拒並說明原因。"},{"c":5,"n":18,"q":"辦理申請敬老福利生活津貼的單位是哪一單位？","o":["勞保局","縣市政府社會局","內政部","戶籍所在地的鄉、鎮、市、區公所"],"a":4,"e":"敬老福利生活津貼向戶籍所在地的鄉鎮市區公所申請。"},{"c":5,"n":19,"q":"照顧服務員資格訓練計畫規定，核心課程的時數為多少小時？","o":["50 小時","40 小時","30 小時","55 小時"],"a":1,"e":"照顧服務員訓練的核心課程為50小時。"},{"c":5,"n":20,"q":"照顧服務員資格訓練計畫規定，臨床實習課程的時數為多少小時？","o":["50 小時","40 小時","30 小時","12 小時"],"a":3,"e":"照顧服務員訓練的臨床實習為30小時。"},{"c":5,"n":21,"q":"老人福利機構設立標準規定，所稱私立小型老人安養、養護機構，是指收容人數未滿多少人？","o":["30 人","45 人","50 人","20 人"],"a":3,"e":"小型老人福利機構是指收容人數未滿50人。"},{"c":5,"n":22,"q":"照顧服務員應具備的條件，何者最不重要？","o":["口才","愛心與耐心","身心健康","熱心"],"a":1,"e":"照顧服務員最重要的是愛心、耐心、身心健康與熱心；口才相對最不重要。"},{"c":5,"n":23,"q":"以下何者不是身心障礙者權益保障法所認定的身心障礙對象？","o":["愛滋病患者","視覺、聽覺機能障礙者","顏面損傷者","慢性精神病患者"],"a":1,"e":"愛滋病患者不屬於身心障礙鑑定類別。"},{"c":5,"n":24,"q":"與被照顧者溝通時，以下何者不適當？","o":["在訪客面前討論被照顧者病情","利用錄音、照片使反覆視聽","一次只給簡單明瞭訊息","有足夠時間給被照顧者理解與反應"],"a":1,"e":"不可在訪客面前討論被照顧者的病情，要保護隱私。"},{"c":5,"n":25,"q":"溝通的內容哪一項不適當？","o":["以案主所關心的事情為主","帶有專業術語的衛教知識","重覆敘述重要的訊息","多提案主正面的、成功的事"],"a":2,"e":"專業術語不易理解，應改用淺顯易懂的說法。"},{"c":5,"n":26,"q":"以下何者不是正向調適工作壓力的方式？","o":["運動、聽音樂或外出旅遊","找督導討論抒發情緒","對不瞭解的部分，進修學習新知","向案主或家屬抱怨"],"a":4,"e":"向案主或家屬抱怨不是正向的壓力調適方式。"},{"c":5,"n":27,"q":"有關長期照護機構的安全管理，何者為適切的？","o":["被照顧者在機構內發生的意外事件不必告知其家人","避免被機構懲罰，被照顧者發生意外事件後，盡量不要讓機構知道","任何意外事故都應依規定報告","意外事故的發生一定要懲罰當事者"],"a":3,"e":"任何意外事故都應依規定報告。"},{"c":5,"n":28,"q":"有關疥瘡的敘述，何者是正確？","o":["疥瘡不會傳染","白天癢得較厲害","室內灑殺蟲劑以防傳染","是一種傳染性強的皮膚病"],"a":4,"e":"疥瘡是傳染性很強的皮膚病，夜間特別癢。"},{"c":5,"n":29,"q":"長期照顧機構門禁安全的目的，何者有誤？","o":["為保護住民的生活安全","可以監視每一位住民交友隱私","避免失智者走失","了解機構出入者"],"a":2,"e":"門禁是為了安全，不能用來監視住民的交友隱私。"},{"c":5,"n":30,"q":"食物中毒的預防原則，何者有誤？","o":["生鮮魚貝類買回來不必洗，立即放入冰箱","應將生食和熟食的刀具和砧板分用","煮熟的食物需及早食用","調味料應有清楚的標籤以免誤用"],"a":1,"e":"生鮮魚貝類買回來應先清洗、分裝，再放入冰箱。"},{"c":5,"n":31,"q":"以下何者不是設置「照顧服務員」職類技術士檢定的目的？","o":["取代護理人員的工作","提升照顧服務員的工作品質","提升照顧服務員的社會信譽","保障案主的權益"],"a":1,"e":"照服員檢定是為了提升照服員的品質與信譽，不能取代護理人員。"},{"c":5,"n":32,"q":"以下哪一項行為不代表案主可能有自殺的傾向？","o":["案主忽然交待重要物品所在地與處理方式","拒絕進食或治療","忘記關門窗","常自責拖累家人"],"a":3,"e":"忘記關門窗是一般健忘，不是自殺警訊。"},{"c":5,"n":33,"q":"達到良好溝通目的的訊息內容應該要","o":["內容不完整","重點很多","簡單明確","說的很快"],"a":3,"e":"好的溝通訊息應簡單明確。"},{"c":5,"n":34,"q":"以下哪一項行為不是照顧服務員有工作壓力的警訊？","o":["注意力不集中、常出錯","有耐心聽被照顧者說話","愛發脾氣、常焦慮不安","無食慾、失眠"],"a":2,"e":"有耐心聽被照顧者說話是正常表現，不是壓力警訊。"},{"c":5,"n":35,"q":"以下哪一項不是照顧服務員在案家處理其家務的目的？","o":["維護被照顧者生活品質","取代被照顧者自己有能力可以完成的家務工作","減輕家屬的照顧負荷","維持被照顧者生活的自主與獨立"],"a":2,"e":"處理家務不應取代案主自己能做的事，要維持他的自主與獨立。"},{"c":5,"n":36,"q":"長期照護機構住民的餐具洗淨後，下列何者處理不當？","o":["以煮沸或蒸氣消毒","曬太陽","以抹布將水擦乾","自然晾乾"],"a":3,"e":"抹布可能帶有細菌，餐具應自然晾乾或消毒烘乾。"},{"c":5,"n":37,"q":"當案主與家屬發生爭吵時，照顧服務員應如何處理？","o":["介入爭執，扮演仲裁者","站在案主這邊，為案主說話","袖手旁觀","抒解雙方情緒，避免衝突惡化，但不介入爭執"],"a":4,"e":"案主與家屬爭吵時，應抒解雙方情緒但不介入。"},{"c":5,"n":38,"q":"當陪同被照顧者就醫延誤到下個被照顧者服務時間的時候，以下處理方式何者為宜？","o":["回報機構督導可能誤班的狀況，請示處理方式","時間到就離開，請被照顧者自行回家","自行與下一個被照顧者協調調班，不必向機構報告","打電話請朋友幫忙代班"],"a":1,"e":"可能延誤下一個班時，應回報機構督導請示處理方式。"},{"c":5,"n":39,"q":"照顧服務員將家裡電話留給案主可能的不良影響是什麼？","o":["案主會勒索服務員","造成案主時常打電話給服務員，影響服務員的家庭生活","造成服務員依賴案主","造成案主被電話詐騙"],"a":2,"e":"留家裡電話給案主，可能常被打擾，影響私人生活。"},{"c":5,"n":40,"q":"服務關係結束後，照顧服務員與案主應保持怎樣的關係？","o":["仍保持密切聯繫","打電話給案主，關切新服務員的服務狀況","避免與案主過於密切聯繫，以免案主拿服務員作比較，造成現有服務員的困擾","改以志工方式，繼續提供服務"],"a":3,"e":"服務結束後應避免與案主過度聯繫，以免影響新服務員。"},{"c":5,"n":41,"q":"服務過程中，如果照顧服務員發現被照顧者需求改變，既有的服務契約無法滿足被照顧者需求時，服務員應該如何因應？","o":["主動幫被照顧者聯繫相關資源","少管閒事，有錢拿就好","要被照顧者自行向機構督導反映","主動反映給機構督導，請督導重新評估需求與服務計畫"],"a":4,"e":"發現需求改變應反映給督導，重新評估並調整服務計畫。"},{"c":5,"n":42,"q":"對於案主有性騷擾的行為時，照顧服務員應該以何種態度面對？","o":["當面斥責教訓案主，給他難堪","立即且堅定地拒絕案主，警告其不可再犯，並告知機構督導","忍氣吞聲，避免衝突","立即要求機構督導更換個案"],"a":2,"e":"遇到性騷擾應立即且堅定拒絕，並告知機構督導。"},{"c":5,"n":43,"q":"當案主因財物遺失懷疑照顧服務員偷竊時，服務員應如何處理？","o":["大聲駁斥案主，表達抗議","在案主面前向天發誓，表示自身清白","禮貌但堅定向案主表達清白，並尋找失物可能放置地點","立即向機構督導請辭，表達抗議"],"a":3,"e":"被懷疑偷竊時，應禮貌而堅定地表達清白，並協助找尋失物。"},{"c":5,"n":44,"q":"案主如有心神喪失或精神耗弱致不能處理自己事務時，以下何者不具向法院聲請監護宣告之資格？","o":["本人","配偶","檢察官","鄰居"],"a":4,"e":"監護宣告可由本人、配偶、四親等內親屬、檢察官等聲請；鄰居沒有聲請資格。"},{"c":5,"n":45,"q":"叫救護車時，以下哪一項資料不需要提供？","o":["呼叫人的姓名","事故地點","傷者狀況","天氣狀況"],"a":4,"e":"叫救護車需說明地點、傷者狀況、聯絡人姓名與電話；天氣不需要。"},{"c":5,"n":46,"q":"照顧服務員在為案主執行任何一項生活照顧工作時，皆須顧及案主的隱私，下列哪項是錯誤的？","o":["案主外出時，確定已做好必要的覆蓋","做治療時，要關門或拉上圍簾","治療或照護時只暴露所需的部位","案主已睡著，可與臨床服務員談論彼此案主的事情"],"a":4,"e":"即使案主睡著，也不可與他人談論案主的事情。"},{"c":5,"n":47,"q":"照顧居家案主時，照顧服務員的工作範圍不包括下列那一項？","o":["案主本人","案主所住個人範圍","案主的主要照顧者","鄰居或親戚"],"a":4,"e":"工作範圍不包括鄰居或親戚。"},{"c":5,"n":48,"q":"遺棄父母之子女，以下的敘述哪一項是錯誤的？","o":["應負刑事責任","主管機關得對其科處罰鍰","主管機關公告其姓名","子女堅持不照顧案主，任何人都沒辦法"],"a":4,"e":"遺棄父母的子女要負法律責任，主管機關也可以介入處理。"},{"c":5,"n":49,"q":"照顧服務員在服務過程中，對自己應有的認知，下列那一項是錯誤？","o":["認識自己的角色與權限","服務年資深，所有事情均可自行做主","虛心接受專業人員的督導","不斷學習進修，以提供良好的照顧品質"],"a":2,"e":"年資再深也要依角色與權限工作，不能所有事情都自行決定。"},{"c":5,"n":50,"q":"照顧居家被照顧者期間，下列那一項是正確的？","o":["按約定時間到案家服務，不可遲到或早退","被照顧者午休可約朋友外出喝咖啡","任意請假，事情由其家人處理","約朋友到被照顧者家中打牌"],"a":1,"e":"應按約定時間服務，不可遲到早退。"},{"c":5,"n":51,"q":"就工作倫理觀點，下列哪一項是照顧服務員不正確的做法？","o":["為維繫與案主之間的關係，可將個人電話、地址留給案主或案家","不可未經案主同意，自行到銀行領錢","不可向案主或案家借錢","不可將個人的家事帶到案主家中"],"a":1,"e":"不宜留個人電話、地址給案主或案家，要維持專業界線。"},{"c":5,"n":52,"q":"為滿足案主個人基本需要，以下措施那一項錯誤？","o":["維護案主的安全與環境整潔","協助案主獲得營養的需求","協助案主獲得身、心、靈的舒適、隱私及緩解焦慮","完全順從案主家人的決定"],"a":4,"e":"應以案主需求為中心，不能完全順從家人的決定。"},{"c":5,"n":53,"q":"照顧服務員的主要業務，下列哪一項錯誤？","o":["協助維護案主個人衛生","協助滿足案主個人的基本需要","協助執行專業人員對案主的照護評估與照護計畫","執行注射工作"],"a":4,"e":"注射屬於醫療行為，照服員不可以執行。"},{"c":5,"n":54,"q":"就工作倫理的觀點，照顧服務員利用與案主的關係，那一項活動是不合規定的？","o":["介紹朋友或自己向案主或家人做直銷或推銷商品","不可以接受案主或案家所饋贈的禮金","不可以向案主或家人拉保險","案主意識不清，但其所有物品絕不可據為己有"],"a":1,"e":"照服員不可向案主或家屬推銷商品、做直銷。"},{"c":5,"n":55,"q":"有關照顧服務員提供被照顧者良好的服務品質，下列那一項是正確的？","o":["凡要使用的物品都請他買外國貨","適合被照顧者個人特性與需求的物品，才請被照顧者家屬購買","只要外觀美麗，不需考慮安全性及價錢","只要被照顧者喜歡，不用管實用否"],"a":2,"e":"物品應選擇適合被照顧者特性與需求的，再請家屬購買。"},{"c":5,"n":56,"q":"照顧服務員因照顧不當造成案主意外傷害，服務員的處置何者是正確的？","o":["密切觀察受傷害者的生命徵象，並報告機構督導事後應仔細檢討，預防再度發生","馬上處置妥當，不必報告任何人","迅速將現場整理，以免被人發現","指責別人害的"],"a":1,"e":"發生意外傷害應觀察生命徵象、報告督導，並檢討改進。"},{"c":5,"n":57,"q":"照顧服務員與案主的溝通中，下列那一項是正確的？","o":["溝通與服務品質沒有關係","和案主溝通不良，一定是案主個人問題，與照顧服務員無關","溝通不只是靠語言溝通，非語言的溝通有時更有影響","案主或家屬有抱怨時，為息事寧人，不必理會"],"a":3,"e":"非語言溝通（表情、肢體、語調）有時影響更大。"},{"c":5,"n":58,"q":"照顧服務員的工作會遇到困難、挫折、沮喪是常有的事，下列那一項的處理不適當？","o":["找負責指導的人員或可信任的人討論","不斷尋求學習照顧知識與技術","對自家人發脾氣，以發洩情緒","以各種活動如聽音樂、打球等轉移情緒"],"a":3,"e":"對家人發脾氣會影響家庭，不是適當的情緒處理。"},{"c":5,"n":59,"q":"當案主主訴或表情不舒服時，照顧服務員的首要工作為何？","o":["把案主帶去睡覺","不予理會，明天就會好了","服務員自行處理","先行關懷並收集相關資料"],"a":4,"e":"案主不舒服時，應先關懷並收集相關資料。"},{"c":5,"n":60,"q":"照顧服務員對選擇服務對象，最合宜的態度為何？","o":["拒絕不易照顧者","避免照顧久病不癒者","不接耗費照顧體力的植物人","視個人能力，以接納和學習的態度，照顧不同身體狀況之案主"],"a":4,"e":"應依個人能力，以接納、學習的態度照顧不同的案主。"},{"c":5,"n":61,"q":"為了讓案主賞心悅目，照顧服務員穿著何者是不適當的？","o":["配戴鑽戒及項鍊、飾物","衣著樸素、整潔，不過度暴露","頭髮梳理整齊，不披頭散髮","宜穿軟底鞋，不穿高跟鞋"],"a":1,"e":"工作時不宜配戴飾品，容易刮傷案主，也藏汙納垢。"},{"c":5,"n":62,"q":"為案主調配膳食時，應遵守的法則，下列哪一項是錯誤的？","o":["手指、皮膚有傷口、膿瘡者需戴手套","調配膳食前後均應確實洗手","配膳前應將飾物、戒指、手錶等脫除","好不容易才留長的指甲，剪掉可惜，不必修剪"],"a":4,"e":"指甲應剪短，避免藏汙與刮傷。"},{"c":5,"n":63,"q":"照顧服務員挪用案主之金錢，可能涉嫌觸犯哪一項罪名？","o":["業務侵佔罪","竊盜罪","詐欺罪","贓物罪"],"a":1,"e":"業務上持有他人財物而據為己有，可能構成業務侵占罪。"},{"c":5,"n":64,"q":"照顧老弱是何人的責任？","o":["家人的責任","國家應負完全的責任","慈善機構的責任","國家、社會、家庭共同要負擔的責任"],"a":4,"e":"照顧老弱是國家、社會、家庭共同的責任。"},{"c":5,"n":65,"q":"照顧服務員協助單身案主申請身心障礙證明，應向哪一個單位提出？","o":["戶籍所在地之鄉、鎮、市、區公所","衛福部","縣市政府社會局","地區以上之醫院"],"a":1,"e":"題庫答案為向戶籍所在地的鄉鎮市區公所申請身心障礙證明。"},{"c":5,"n":66,"q":"長期照顧機構內的牆壁或地面，需有何設施，以方便身障者行動？","o":["簡明和標準的標示或符號","美麗的垂飾","名畫、花地磚","一般的鏡子"],"a":1,"e":"簡明標準的標示或符號，方便身障者辨識與行動。"},{"c":5,"n":67,"q":"對於長照服務機構下列哪一項敘述是合宜的？","o":["安養機構可以收容重症或植物人","夜間應裝置夜燈及緊急照明設備","不必有逃生設備，但需有足夠的人力將住民移到安全地方","建築物整年都用中央空調，無通風不良之虞"],"a":2,"e":"長照機構夜間應有夜燈與緊急照明，預防跌倒並利於逃生。"},{"c":5,"n":68,"q":"照顧服務員留存照顧記錄的意義，下列敘述何者不正確？","o":["提供醫生、護理人員及其他醫療團隊的人員處置時參考的訊息","提供給被照顧者及其家人參考","若發生醫療糾紛、保險理賠、犯罪嫌疑、甚或遺囑查證，記錄也是一種法律上的證明文件","毫無意義或用途"],"a":4,"e":"照顧記錄可提供醫療團隊參考，也是法律證明文件，不是毫無意義。"},{"c":5,"n":69,"q":"照顧服務員因臨時身體不舒服，無法前往案家服務案主時，應如何處理？","o":["私下委請其他同事代為照顧","通知所服務的單位，由該單位派請其他服務員代理","不要張揚，不要說","向案家請假，告知無法去照顧即可"],"a":2,"e":"（本題已刪題）無法上班時應通知服務單位，由單位派員代理。","d":1},{"c":6,"n":1,"q":"對於核計勞工所得有無低於基本（最低）工資，下列何者錯誤？","o":["僅計入在正常工時內之報酬","應計入加班費","不計入休假日出勤加給之工資","不計入競賽獎金"],"a":2,"e":"核算基本工資只計正常工時內的報酬，不計入加班費。"},{"c":6,"n":2,"q":"下列何者之工資日數得列入計算平均工資？","o":["請事假期間","職災醫療期間","發生計算事由之當日前 6 個月","放無薪假期間"],"a":3,"e":"平均工資以發生事由當日前6個月的工資計算；事假、職災醫療、無薪假期間應扣除。"},{"c":6,"n":3,"q":"有關「例假」之敘述，下列何者錯誤？","o":["每 7 日應有例假 1 日","工資照給","天災出勤時，工資加倍及補休","須給假，不必給工資"],"a":4,"e":"例假日工資照給。"},{"c":6,"n":4,"q":"勞動基準法第84條之1規定之工作者，因工作性質特殊，就其工作時間之敘述，下列何者正確？","o":["完全不受限制","無例假與休假","不另給予延時工資","得由勞雇雙方另行約定"],"a":4,"e":"勞基法第84條之1的工作者，工作時間得由勞雇雙方另行約定，並報主管機關核備。"},{"c":6,"n":5,"q":"依勞動基準法規定，雇主應置備勞工工資清冊並應保存幾年？","o":["1 年","2 年","5 年","10 年"],"a":3,"e":"工資清冊應保存5年。"},{"c":6,"n":6,"q":"事業單位僱用勞工多少人以上者，應依勞動基準法規定訂立工作規則？","o":["30 人","50 人","100 人","200 人"],"a":1,"e":"僱用勞工30人以上應訂立工作規則。"},{"c":6,"n":7,"q":"依勞動基準法規定，雇主延長勞工之工作時間連同正常工作時間，每日不得超過多少小時？","o":["10 小時","11 小時","12 小時","15 小時"],"a":3,"e":"延長工時連同正常工時，每日不得超過12小時。"},{"c":6,"n":8,"q":"依勞動基準法規定，下列何者屬不定期契約？","o":["臨時性或短期性的工作","季節性的工作","特定性的工作","有繼續性的工作"],"a":4,"e":"有繼續性的工作應為不定期契約。"},{"c":6,"n":9,"q":"依職業安全衛生法規定，事業單位勞動場所發生死亡職業災害時，雇主應於多少小時內通報勞動檢查機構？","o":["8 小時","12 小時","24 小時","48 小時"],"a":1,"e":"發生死亡職業災害，雇主應於8小時內通報勞動檢查機構。"},{"c":6,"n":10,"q":"有關事業單位之勞資會議主席，下列何者正確？","o":["由企業工會推派之","由產業工會推派之","由勞資雙方協議推派之","由勞資雙方輪流擔任之"],"a":4,"e":"勞資會議主席由勞資雙方代表各推派1人輪流擔任。"},{"c":6,"n":11,"q":"職業安全衛生法所稱有母性健康危害之虞之工作，不包括下列何種工作型態？","o":["長時間站立姿勢作業","人力提舉、搬運及推拉重物","輪班及工作負荷","駕駛運輸車輛"],"a":4,"e":"駕駛運輸車輛不屬於法定的母性健康危害工作型態。"},{"c":6,"n":12,"q":"依職業安全衛生法施行細則規定，下列何者非屬特別危害健康之作業？","o":["噪音作業","游離輻射作業","會計作業","粉塵作業"],"a":3,"e":"會計作業不屬於特別危害健康作業。"},{"c":6,"n":13,"q":"從事於易踏穿材料構築之屋頂修繕作業時，應有何種作業主管在場執行主管業務？","o":["施工架組配","擋土支撐組配","屋頂","模板支撐"],"a":3,"e":"易踏穿屋頂的修繕作業，應有屋頂作業主管在場。"},{"c":6,"n":14,"q":"有關「工讀生」之敘述，下列何者正確？","o":["工資不得低於基本工資之 80 ％","屬短期工作者，加班只能補休","每日正常工作時間得超過 8 小時","國定假日出勤，工資加倍發給"],"a":4,"e":"工讀生也受勞基法保障，國定假日出勤工資加倍發給。"},{"c":6,"n":15,"q":"勞工工作時手部嚴重受傷，住院醫療期間公司應按下列何者給予職業災害補償？","o":["前 6 個月平均工資","前 1 年平均工資","原領工資","基本工資"],"a":3,"e":"職災醫療期間，雇主應按原領工資給予補償。"},{"c":6,"n":16,"q":"勞工在何種情況下，雇主得不經預告終止勞動契約？","o":["確定被法院判刑 6 個月以內並諭知緩刑超過 1 年以上者","不服指揮對雇主暴力相向者","經常遲到早退者","非連續曠工但 1 個月內累計 3 日者"],"a":2,"e":"對雇主實施暴行，雇主可以不經預告終止勞動契約。"},{"c":6,"n":17,"q":"對於吹哨者保護規定，下列何者錯誤？","o":["事業單位不得對勞工申訴人終止勞動契約","勞動檢查機構受理勞工申訴必須保密","為實施勞動檢查，必要時得告知事業單位有關勞工申訴人身分","事業單位不得有不利勞工申訴人之處分"],"a":3,"e":"勞動檢查機構必須對申訴人身分保密，不得告知事業單位。"},{"c":6,"n":18,"q":"職業安全衛生法所稱有母性健康危害之虞之工作，係指對於具生育能力之女性勞工從事工作，可能會導致的一些影響。下列何者除外？","o":["胚胎發育","妊娠期間之母體健康","哺乳期間之嬰兒健康","經期紊亂"],"a":4,"e":"母性健康危害是指影響胚胎發育、妊娠期母體健康與哺乳期嬰兒健康；經期紊亂不在此範圍。"},{"c":6,"n":19,"q":"下列何者非屬職業安全衛生法規定之勞工法定義務？","o":["定期接受健康檢查","參加安全衛生教育訓練","實施自動檢查","遵守安全衛生工作守則"],"a":3,"e":"實施自動檢查是雇主的義務，不是勞工的法定義務。"},{"c":6,"n":20,"q":"下列何者非屬應對在職勞工施行之健康檢查？","o":["一般健康檢查","體格檢查","特殊健康檢查","特定對象及特定項目之檢查"],"a":2,"e":"體格檢查是新僱用勞工時實施的，不是在職勞工的健康檢查。"},{"c":6,"n":21,"q":"下列何者非為防範有害物食入之方法？","o":["有害物與食物隔離","不在工作場所進食或飲水","常洗手、漱口","穿工作服"],"a":4,"e":"穿工作服是防止皮膚接觸，不是防止食入有害物。"},{"c":6,"n":22,"q":"原事業單位如有違反職業安全衛生法或有關安全衛生規定，致承攬人所僱勞工發生職業災害時，有關承攬管理責任，下列敘述何者正確？","o":["原事業單位應與承攬人負連帶賠償責任","原事業單位不需負連帶補償責任","承攬廠商應自負職業災害之賠償責任","勞工投保單位即為職業災害之賠償單位"],"a":1,"e":"原事業單位違反規定時，應與承攬人負連帶賠償責任。"},{"c":6,"n":23,"q":"依勞動基準法規定，主管機關或檢查機構於接獲勞工申訴事業單位違反本法及其他勞工法令規定後，應為必要之調查，並於幾日內將處理情形，以書面通知勞工？","o":["14 日","20 日","30 日","60 日"],"a":4,"e":"主管機關接獲申訴後，應於60日內以書面通知勞工處理情形。"},{"c":6,"n":24,"q":"我國中央勞動業務主管機關為下列何者？","o":["內政部","勞工保險局","勞動部","經濟部"],"a":3,"e":"中央勞動主管機關是勞動部。"},{"c":6,"n":25,"q":"對於勞動部公告列入應實施型式驗證之機械、設備或器具，下列何種情形不得免驗證？","o":["依其他法律規定實施驗證者","供國防軍事用途使用者","輸入僅供科技研發之專用機型","輸入僅供收藏使用之限量品"],"a":4,"e":"僅供收藏的限量品不在免驗證範圍內。"},{"c":6,"n":26,"q":"對於墜落危險之預防設施，下列敘述何者較為妥適？","o":["在外牆施工架等高處作業應盡量使用繫腰式安全帶","安全帶應確實配掛在低於足下之堅固點","高度 2m 以上之邊緣開口部分處應圍起警示帶","高度 2m 以上之開口處應設護欄或安全網"],"a":4,"e":"高度2公尺以上的開口處應設置護欄或安全網。"},{"c":6,"n":27,"q":"對於感電電流流過人體可能呈現的症狀，下列何者錯誤？","o":["痛覺","強烈痙攣","血壓降低、呼吸急促、精神亢奮","造成組織灼傷"],"a":3,"e":"感電可能造成血壓變化、呼吸困難甚至停止，不會「精神亢奮」。"},{"c":6,"n":28,"q":"下列何者非屬於容易發生墜落災害的作業場所或設施？","o":["施工架","廚房","屋頂","梯子"],"a":2,"e":"廚房不屬於容易發生墜落災害的場所。"},{"c":6,"n":29,"q":"下列何者非屬危險物儲存場所應採取之火災爆炸預防措施？","o":["使用工業用電風扇","裝設可燃性氣體偵測裝置","使用防爆電氣設備","標示「嚴禁煙火」"],"a":1,"e":"工業用電風扇可能產生火花，不是防爆措施。"},{"c":6,"n":30,"q":"雇主於臨時用電設備加裝漏電斷路器，可減少下列何種災害發生？","o":["墜落","物體倒塌、崩塌","感電","被撞"],"a":3,"e":"漏電斷路器可以防止感電。"},{"c":6,"n":31,"q":"雇主要求確實管制人員不得進入吊舉物下方，可避免下列何種災害發生？","o":["感電","墜落","物體飛落","缺氧"],"a":3,"e":"管制人員不進入吊舉物下方，可避免物體飛落災害。"},{"c":6,"n":32,"q":"職業上危害因子所引起的勞工疾病，稱為何種疾病？","o":["職業疾病","法定傳染病","流行性疾病","遺傳性疾病"],"a":1,"e":"職業上危害因子所引起的疾病，稱為職業疾病。"},{"c":6,"n":33,"q":"事業招人承攬時，其承攬人就承攬部分負雇主之責任，原事業單位就職業災害補償部分之責任為何？","o":["視職業災害原因判定是否補償","依工程性質決定責任","依承攬契約決定責任","仍應與承攬人負連帶責任"],"a":4,"e":"原事業單位仍應與承攬人負連帶補償責任。"},{"c":6,"n":34,"q":"預防職業病最根本的措施為何？","o":["實施特殊健康檢查","實施作業環境改善","實施定期健康檢查","實施僱用前體格檢查"],"a":2,"e":"預防職業病最根本的是改善作業環境，從源頭消除危害。"},{"c":6,"n":35,"q":"在地下室作業，當通風換氣充分時，則不易發生一氧化碳中毒、缺氧危害或火災爆炸危險。「通風換氣充分」係指下列何種描述？","o":["風險控制方法","發生機率","危害源","風險"],"a":1,"e":"通風換氣是降低危害的風險控制方法。"},{"c":6,"n":36,"q":"勞工為節省時間，在未斷電情況下清理機臺，易發生危害為何？","o":["捲夾","缺氧","墜落","崩塌"],"a":1,"e":"未斷電清理機器，容易被捲夾。"},{"c":6,"n":37,"q":"工作場所具有揮發性化學有害物質進入人體，最常見途徑為下列何者？","o":["口腔","呼吸道","皮膚","眼睛"],"a":2,"e":"揮發性化學物質最常經由呼吸道進入人體。"},{"c":6,"n":38,"q":"活線作業勞工應佩戴何種防護手套？","o":["棉紗手套","耐熱手套","絕緣手套","防振手套"],"a":3,"e":"活線作業應戴絕緣手套。"},{"c":6,"n":39,"q":"下列何者非屬電氣災害之種類？","o":["電弧灼傷","電氣火災","靜電危害","雷電閃爍"],"a":4,"e":"雷電閃爍是自然現象，不屬於電氣災害種類。"},{"c":6,"n":40,"q":"下列何者非屬於工作場所作業會發生墜落災害的潛在危害因子？","o":["開口未設置護欄","未設置安全之上下設備","未確實配戴耳罩","屋頂開口下方未張掛安全網"],"a":3,"e":"未戴耳罩和噪音有關，與墜落無關。"},{"c":6,"n":41,"q":"在噪音防治之對策中，從下列何者著手最為有效？","o":["偵測儀器","噪音源","傳播途徑","個人防護具"],"a":2,"e":"噪音防治從噪音源著手最有效。"},{"c":6,"n":42,"q":"勞工於室外高氣溫作業環境工作，可能對身體產生之熱危害，下列何者非屬熱危害之症狀？","o":["熱衰竭","中暑","熱痙攣","痛風"],"a":4,"e":"痛風是代謝性疾病，不屬於熱危害。"},{"c":6,"n":43,"q":"下列何者是消除職業病發生率之源頭管理對策？","o":["使用個人防護具","健康檢查","改善作業環境","多運動"],"a":3,"e":"改善作業環境是源頭管理。"},{"c":6,"n":44,"q":"下列何者非職業病預防之危害因子？","o":["遺傳性疾病","物理性危害","人因工程危害","化學性危害"],"a":1,"e":"遺傳性疾病不是職業危害因子。"},{"c":6,"n":45,"q":"依職業安全衛生設施規則規定，下列何者非屬使用合梯，應符合之規定？","o":["合梯應具有堅固之構造","合梯材質不得有顯著之損傷、腐蝕等","梯腳與地面之角度應在 80 度以上","有安全之防滑梯面"],"a":3,"e":"合梯梯腳與地面的角度應在75度以內。"},{"c":6,"n":46,"q":"下列何者非屬勞工從事電氣工作安全之規定？","o":["使其使用電工安全帽","穿戴絕緣防護具","停電作業應斷開、檢電、接地及掛牌","穿戴棉質手套絕緣"],"a":4,"e":"棉質手套不能絕緣，應穿戴絕緣防護具。"},{"c":6,"n":47,"q":"為防止勞工感電，下列何者錯誤？","o":["使用防水插頭","避免不當延長接線","設備有金屬外殼保護即可免接地","電線架高或加以防護"],"a":3,"e":"有金屬外殼的設備仍需接地，以免漏電時感電。"},{"c":6,"n":48,"q":"不當抬舉導致肌肉骨骼傷害或肌肉疲勞之現象，可歸類為下列何者？","o":["感電事件","不當動作","不安全環境","被撞事件"],"a":2,"e":"不當抬舉造成的傷害，屬於不當動作。"},{"c":6,"n":49,"q":"使用鑽孔機時，不應使用下列何護具？","o":["耳塞","防塵口罩","手套","護目鏡"],"a":3,"e":"使用鑽孔機不應戴手套，以免被捲入。"},{"c":6,"n":50,"q":"腕道症候群常發生於下列何種作業？","o":["電腦鍵盤作業","潛水作業","堆高機作業","第一種壓力容器作業"],"a":1,"e":"腕道症候群常見於長時間使用電腦鍵盤。"},{"c":6,"n":51,"q":"對於化學燒傷傷患的一般處理原則，下列何者正確？","o":["立即用大量清水沖洗","傷患必須臥下，而且頭、胸部須高於身體其他部位","於燒傷處塗抹油膏、油脂或發酵粉","使用酸鹼中和"],"a":1,"e":"化學燒傷應立即用大量清水沖洗。"},{"c":6,"n":52,"q":"下列何者非屬防止搬運事故之一般原則？","o":["以機械代替人力","以機動車輛搬運","採取適當之搬運方法","儘量增加搬運距離"],"a":4,"e":"應盡量縮短搬運距離，增加距離不是防止事故的原則。"},{"c":6,"n":53,"q":"對於脊柱或頸部受傷患者，下列何者不是適當的處理原則？","o":["不輕易移動傷患","速請醫師","如無合用的器材，需 2 人作徒手搬運","向急救中心聯絡"],"a":3,"e":"脊椎受傷者不宜徒手搬運，應以硬板固定，等待專業處理。"},{"c":6,"n":54,"q":"於使用道路作業之工作場所，為防止工作人員遭車輛撞擊危害，所採取防護措施，下列何者錯誤？","o":["設置警告標示","置交通引導人員","管制非工作人員不得進入","各包商之車輛一律停放於工地現場"],"a":4,"e":"包商車輛不應一律停在工地現場，以免撞擊工作人員。"},{"c":6,"n":55,"q":"安全帽承受巨大外力衝擊後，雖外觀良好，應採下列何種處理方式？","o":["廢棄","繼續使用","送修","油漆保護"],"a":1,"e":"安全帽受過重大衝擊後內部可能已受損，應廢棄。"},{"c":6,"n":56,"q":"因舉重而扭腰係由於身體動作不自然姿勢，動作之反彈，引起扭筋、扭腰及形成類似狀態造成職業災害，其災害類型為下列何者？","o":["不當狀態","不當動作","不當方針","不當設備"],"a":2,"e":"舉重時扭腰屬於不當動作造成的災害。"},{"c":6,"n":57,"q":"有關工作場所安全衛生之敘述，下列何者錯誤？","o":["對於勞工從事其身體或衣著有被污染之虞之特殊作業時，應備置該勞工洗眼、洗澡、漱口、更 衣、洗濯等設備","事業單位應備置足夠急救藥品及器材","事業單位應備置足夠的零食自動販賣機","勞工應定期接受健康檢查"],"a":3,"e":"零食自動販賣機與工作場所安全衛生無關。"},{"c":6,"n":58,"q":"在地下室從事油漆粉刷作業，可能呼吸到揮發性有機化合物時，下列措施何者恰當？","o":["用手帕遮擋鼻子","配戴防塵口罩","配戴濾毒罐面具","配戴醫用口罩"],"a":3,"e":"揮發性有機物應配戴濾毒罐面具，防塵口罩無法過濾。"},{"c":6,"n":59,"q":"安全門或緊急出口平時應維持何狀態？","o":["門可上鎖但不可封死","保持開門狀態以保持逃生路徑暢通","門應關上但不可上鎖","與一般進出門相同，視各樓層規定可開可關"],"a":3,"e":"安全門平時應關閉但不可上鎖，以防火煙蔓延並確保可逃生。"},{"c":6,"n":60,"q":"下列何種防護具較能消減噪音對聽力的危害？","o":["棉花球","耳塞","耳罩","碎布球"],"a":3,"e":"耳罩的隔音效果較好。"},{"c":6,"n":61,"q":"勞工若面臨長期工作負荷壓力及工作疲勞累積，沒有獲得適當休息及充足睡眠，便可能影響體能及精神狀態，甚而較易促發下列何種疾病？","o":["皮膚癌","腦心血管疾病","多發性神經病變","肺水腫"],"a":2,"e":"長期過勞容易促發腦心血管疾病。"},{"c":6,"n":62,"q":"「勞工腦心血管疾病發病的風險與年齡、吸菸、總膽固醇數值、家族病史、生活型態、心臟方面疾病」之相關性為何？","o":["無","正","負","可正可負"],"a":2,"e":"年齡、吸菸、膽固醇、家族病史等因素與腦心血管疾病風險呈正相關。"},{"c":6,"n":63,"q":"下列何者非屬職場不法侵害類型？","o":["肢體暴力","語言暴力","家庭暴力","性騷擾"],"a":3,"e":"家庭暴力不屬於職場不法侵害。"},{"c":6,"n":64,"q":"職場內部常見之身體或精神不法侵害，不包含下列何者？","o":["脅迫、名譽損毀、侮辱、嚴重辱罵勞工","強求勞工執行業務上明顯不必要或不可能之工作","過度介入勞工私人事宜","使勞工執行與能力、經驗相符的工作"],"a":4,"e":"安排與能力、經驗相符的工作是正常管理，不是不法侵害。"},{"c":6,"n":65,"q":"下列何種措施較可避免工作單調重複或負荷過重？","o":["連續夜班","工時過長","排班保有規律性","經常性加班"],"a":3,"e":"排班保有規律性，可以避免負荷過重。"},{"c":6,"n":66,"q":"減輕皮膚燒傷程度之最重要步驟為何？","o":["儘速用清水沖洗","立即刺破水泡","立即在燒傷處塗抹油脂","在燒傷處塗抹麵粉"],"a":1,"e":"燒傷後儘速用清水沖洗降溫，最能減輕傷害。"},{"c":6,"n":67,"q":"眼內噴入化學物或其他異物，應立即使用下列何者沖洗眼睛？","o":["牛奶","蘇打水","清水","稀釋的醋"],"a":3,"e":"眼睛噴入化學物，應立即用大量清水沖洗。"},{"c":6,"n":68,"q":"石綿最可能引起下列何種疾病？","o":["白指症","心臟病","間皮細胞瘤","巴金森氏症"],"a":3,"e":"石綿容易引起間皮細胞瘤（間皮瘤）。"},{"c":6,"n":69,"q":"作業場所高頻率噪音較易導致下列何種症狀？","o":["失眠","聽力損失","肺部疾病","腕道症候群"],"a":2,"e":"高頻噪音容易造成聽力損失。"},{"c":6,"n":70,"q":"廚房設置之排油煙機，為下列何者？","o":["整體換氣裝置","局部排氣裝置","吹吸型換氣裝置","排氣煙囪"],"a":2,"e":"排油煙機是在污染源附近抽氣，屬於局部排氣裝置。"},{"c":6,"n":71,"q":"下列何者為選用防塵口罩時，最不重要之考量因素？","o":["捕集效率愈高愈好","吸氣阻抗愈低愈好","重量愈輕愈好","視野愈小愈好"],"a":4,"e":"防塵口罩應有良好視野，「視野愈小愈好」是錯的。"},{"c":6,"n":72,"q":"若勞工工作性質需與陌生人接觸、工作中需處理不可預期的突發事件或工作場所治安狀況較差，較容易遭遇下列何種危害？","o":["組織內部不法侵害","組織外部不法侵害","多發性神經病變","潛涵症"],"a":2,"e":"接觸陌生人或治安較差的場所，較易遭受組織外部的不法侵害。"},{"c":6,"n":73,"q":"下列何者不是發生電氣火災的主要原因？","o":["電器接點短路","電氣火花","電纜線置於地上","漏電"],"a":3,"e":"電纜線放在地上不是電氣火災的主因（但應注意被踩壓破損）。"},{"c":6,"n":74,"q":"依勞工職業災害保險及保護法規定，職業災害保險之保險效力，自何時開始起算，至離職當日停止？","o":["通知當日","到職當日","雇主訂定當日","勞雇雙方合意之日"],"a":2,"e":"職災保險效力自到職當日起算。"},{"c":6,"n":75,"q":"依勞工職業災害保險及保護法規定，勞工職業災害保險以下列何者為保險人，辦理保險業務？","o":["財團法人職業災害預防及重建中心","勞動部職業安全衛生署","勞動部勞動基金運用局","勞動部勞工保險局"],"a":4,"e":"勞工職災保險的保險人是勞動部勞工保險局。"},{"c":6,"n":76,"q":"有關「童工」之敘述，下列何者正確？","o":["每日工作時間不得超過 8 小時","不得於午後 8 時至翌晨 8 時之時間內工作","例假日得在監視下工作","工資不得低於基本工資之 70％"],"a":1,"e":"童工每日工作時間不得超過8小時，也不得在夜間工作。"},{"c":6,"n":77,"q":"依勞動檢查法施行細則規定，事業單位如不服勞動檢查結果，應於勞動檢查結果通知書送達之次日起10日內，以書面敘明理由向勞動檢查機構提出？","o":["申訴","陳情","抗議","異議"],"a":4,"e":"不服勞動檢查結果，應於10日內以書面提出異議。"},{"c":6,"n":78,"q":"工作者若因雇主違反職業安全衛生法規定而發生職業災害、疑似罹患職業病或身體、精神遭受不法侵害所提起之訴訟，得向勞動部委託之民間團體提出下列何者？","o":["災害理賠","申請扶助","精神補償","國家賠償"],"a":2,"e":"可以向勞動部委託的民間團體申請扶助。"},{"c":6,"n":79,"q":"計算平日加班費須按平日每小時工資額加給計算，下列何者錯誤？","o":["前 2 小時至少加給 1/3 倍","超過 2 小時部分至少加給 2/3 倍","經勞資協商同意後，一律加給 0.5 倍","未經雇主同意給加班費者，一律補休"],"a":4,"e":"加班需經雇主同意，但勞工選擇補休或加班費應依法約定，不是「一律補休」。"},{"c":6,"n":80,"q":"下列工作場所何者非屬勞動檢查法所定之危險性工作場所？","o":["農藥製造","金屬表面處理","火藥類製造","從事石油裂解之石化工業之工作場所"],"a":2,"e":"金屬表面處理不屬於危險性工作場所。"},{"c":6,"n":81,"q":"依職業安全衛生設施規則規定，有關電氣安全，下列何者錯誤？","o":["110 伏特之電壓不致造成人員死亡","電氣室應禁止非工作人員進入","不可以濕手操作電氣開關，且切斷開關應迅速","220 伏特為低壓電"],"a":1,"e":"110伏特電壓同樣可能造成感電死亡。"},{"c":6,"n":82,"q":"依職業安全衛生設施規則規定，下列何者非屬於車輛系營建機械？","o":["平土機","堆高機","推土機","鏟土機"],"a":2,"e":"堆高機不屬於車輛系營建機械。"},{"c":6,"n":83,"q":"下列何者非為事業單位勞動場所發生職業災害者，雇主應於8小時內通報勞動檢查機構？","o":["發生死亡災害","勞工受傷無須住院治療","發生災害之罹災人數在 3 人以上","發生災害之罹災人數在 1 人以上，且需住院治療"],"a":2,"e":"勞工受傷但無需住院，不在8小時內通報的範圍。"},{"c":6,"n":84,"q":"依職業安全衛生管理辦法規定，下列何者非屬「自動檢查」之內容？","o":["機械之定期檢查","機械、設備之重點檢查","機械、設備之作業檢點","勞工健康檢查"],"a":4,"e":"勞工健康檢查不屬於自動檢查。"},{"c":6,"n":85,"q":"下列何者係針對於機械操作點的捲夾危害特性可以採用之防護裝置？","o":["設置護圍、護罩","穿戴棉紗手套","穿戴防護衣","強化教育訓練"],"a":1,"e":"設置護圍、護罩可防止捲夾危害。"},{"c":6,"n":86,"q":"下列何者非屬從事起重吊掛作業導致物體飛落災害之可能原因？","o":["吊鉤未設防滑舌片致吊掛鋼索鬆脫","鋼索斷裂","超過額定荷重作業","過捲揚警報裝置過度靈敏"],"a":4,"e":"過捲揚警報靈敏是安全裝置正常運作，不是事故原因。"},{"c":6,"n":87,"q":"勞工不遵守安全衛生工作守則規定，屬於下列何者？","o":["不安全設備","不安全行為","不安全環境","管理缺陷"],"a":2,"e":"勞工不遵守工作守則，屬於不安全行為。"},{"c":6,"n":88,"q":"下列何者不屬於局限空間內作業場所應採取之缺氧、中毒等危害預防措施？","o":["實施通風換氣","進入作業許可程序","使用柴油內燃機發電提供照明","測定氧氣、危險物、有害物濃度"],"a":3,"e":"在局限空間使用柴油內燃機會產生一氧化碳，造成中毒。"},{"c":6,"n":89,"q":"下列何者非通風換氣之目的？","o":["防止游離輻射","防止火災爆炸","稀釋空氣中有害物","補充新鮮空氣"],"a":1,"e":"通風換氣無法防止游離輻射。"},{"c":6,"n":90,"q":"已在職之勞工，首次從事特別危害健康作業，應實施下列何種檢查？","o":["一般體格檢查","特殊體格檢查","一般體格檢查及特殊健康檢查","特殊健康檢查"],"a":4,"e":"在職勞工首次從事特別危害健康作業，應實施特殊健康檢查。"},{"c":6,"n":91,"q":"依職業安全衛生設施規則規定，噪音超過多少分貝之工作場所，應標示並公告噪音危害之預防事項，使勞工周知？","o":["75 分貝","80 分貝","85 分貝","90 分貝"],"a":4,"e":"噪音超過90分貝的工作場所應標示並公告預防事項。"},{"c":6,"n":92,"q":"下列何者非屬工作安全分析的目的？","o":["發現並杜絕工作危害","確立工作安全所需工具與設備","懲罰犯錯的員工","作為員工在職訓練的參考"],"a":3,"e":"工作安全分析的目的是預防危害，不是懲罰員工。"},{"c":6,"n":93,"q":"可能對勞工之心理或精神狀況造成負面影響的狀態，如異常工作壓力、超時工作、語言脅迫或恐嚇等，可歸屬於下列何者管理不當？","o":["職業安全","職業衛生","勞工健康","環保"],"a":3,"e":"異常壓力、超時工作、語言脅迫等屬於勞工健康管理問題。"},{"c":6,"n":94,"q":"有關女性工作者妊娠期間宜避免作業之敘述，下列何者錯誤？","o":["避免砷或鉛之暴露","避免每班站立 7 小時以上之作業","避免提舉 1 公斤重物之職務","避免重體力勞動之職務"],"a":3,"e":"妊娠期間應避免提舉重物，但1公斤太輕，不在限制範圍。"},{"c":6,"n":95,"q":"熱中暑時，易發生下列何現象？","o":["體溫下降","體溫正常","體溫上升","體溫忽高忽低"],"a":3,"e":"中暑時體溫會上升，甚至超過40℃。"},{"c":6,"n":96,"q":"下列何者不會使電路發生過電流？","o":["電氣設備過載","電路短路","電路漏電","電路斷路"],"a":4,"e":"電路斷路時沒有電流流通，不會產生過電流。"},{"c":6,"n":97,"q":"下列何者較屬安全、尊嚴的職場組織文化？","o":["不斷責備勞工","公開在眾人面前長時間責罵勞工","強求勞工執行業務上明顯不必要或不可能之工作","不介入勞工私人事宜"],"a":4,"e":"不介入勞工私人事宜，是尊重勞工的職場文化。"},{"c":6,"n":98,"q":"下列何者與職場母性健康保護較不相關？","o":["職業安全衛生法","妊娠與分娩後女性及未滿十八歲勞工禁止從事危險性或有害性工作認定標準","性別平等工作法","動力堆高機型式驗證"],"a":4,"e":"動力堆高機型式驗證與母性健康保護無關。"},{"c":6,"n":99,"q":"油漆塗裝工程應注意防火防爆事項，下列何者錯誤？","o":["確實通風","注意電氣火花","緊密門窗以減少溶劑擴散揮發","嚴禁煙火"],"a":3,"e":"油漆塗裝應保持通風，緊閉門窗會使溶劑蒸氣累積，增加火災爆炸風險。"},{"c":6,"n":100,"q":"依職業安全衛生設施規則規定，雇主對於物料儲存，為防止氣候變化或自然發火發生危險者，下列何者為最佳之採取措施？","o":["保持自然通風","密閉","與外界隔離及溫濕控制","靜置於倉儲區，避免陽光直射"],"a":3,"e":"易自燃的物料應與外界隔離，並控制溫度與濕度。"},{"c":7,"n":1,"q":"下列何者「違反」個人資料保護法？","o":["公司基於人事管理之特定目的，張貼榮譽榜揭示績優員工姓名","縣市政府提供村里長轄區內符合資格之老人名冊供發放敬老金","網路購物公司為辦理退貨，將客戶之住家地址提供予宅配公司","學校將應屆畢業生之住家地址提供補習班招生使用"],"a":4,"e":"將學生住址提供給補習班招生，超出原本的蒐集目的，違反個資法。"},{"c":7,"n":2,"q":"非公務機關利用個人資料進行行銷時，下列敘述何者錯誤？","o":["若已取得當事人書面同意，當事人即不得拒絕利用其個人資料行銷","於首次行銷時，應提供當事人表示拒絕行銷之方式","當事人表示拒絕接受行銷時，應停止利用其個人資料","倘非公務機關違反「應即停止利用其個人資料行銷」之義務，未於限期內改正者，按次處新臺幣 2 萬元以上 20 萬元以下罰鍰"],"a":1,"e":"即使已取得書面同意，當事人仍可隨時表示拒絕行銷。"},{"c":7,"n":3,"q":"個人資料保護法規定為保護當事人權益，幾人以上的當事人提出告訴，就可以進行團體訴訟？","o":["5 人","10 人","15 人","20 人"],"a":4,"e":"個資法規定，20人以上的當事人可以授與團體提起團體訴訟。"},{"c":7,"n":4,"q":"關於個人資料保護法的敘述，下列何者錯誤？","o":["公務機關執行法定職務必要範圍內，可以蒐集、處理或利用一般性個人資料","間接蒐集之個人資料，於處理或利用前，不必告知當事人個人資料來源","非公務機關亦應維護個人資料之正確，並主動或依當事人之請求更正或補充","外國學生在臺灣短期進修或留學，也受到我國個人資料保護法的保障"],"a":2,"e":"間接蒐集的個資，在處理或利用前應告知當事人資料來源。"},{"c":7,"n":5,"q":"關於個人資料保護法的敘述，下列何者錯誤？","o":["不管是否使用電腦處理的個人資料，都受個人資料保護法保護","公務機關依法執行公權力，不受個人資料保護法規範","身分證字號、婚姻、指紋都是個人資料","我的病歷資料雖然是由醫生所撰寫，但也屬於是我的個人資料範圍"],"a":2,"e":"公務機關依法執行職務時，也要遵守個資法的規範。"},{"c":7,"n":6,"q":"對於依照個人資料保護法應告知之事項，下列何者不在法定應告知的事項內？","o":["個人資料利用之期間、地區、對象及方式","蒐集之目的","蒐集機關的負責人姓名","如拒絕提供或提供不正確個人資料將造成之影響"],"a":3,"e":"個資法應告知的事項不包括蒐集機關負責人的姓名。"},{"c":7,"n":7,"q":"請問下列何者非為個人資料保護法第3條所規範之當事人權利？","o":["查詢或請求閱覽","請求刪除他人之資料","請求補充或更正","請求停止蒐集、處理或利用"],"a":2,"e":"當事人只能請求刪除自己的資料，不能請求刪除他人的資料。"},{"c":7,"n":8,"q":"下列何者非安全使用電腦內的個人資料檔案的做法？","o":["利用帳號與密碼登入機制來管理可以存取個資者的人","規範不同人員可讀取的個人資料檔案範圍","個人資料檔案使用完畢後立即退出應用程式，不得留置於電腦中","為確保重要的個人資料可即時取得，將登入密碼標示在螢幕下方"],"a":4,"e":"把密碼貼在螢幕旁，任何人都看得到，非常不安全。"},{"c":7,"n":9,"q":"下列何者行為非屬個人資料保護法所稱之國際傳輸？","o":["將個人資料傳送給地方政府","將個人資料傳送給美國的分公司","將個人資料傳送給法國的人事部門","將個人資料傳送給日本的委託公司"],"a":1,"e":"傳送給國內地方政府不屬於國際傳輸。"},{"c":7,"n":10,"q":"有關智慧財產權行為之敘述，下列何者有誤？","o":["製造、販售仿冒註冊商標的商品雖已侵害商標權，但不屬於公訴罪之範疇","以 101 大樓、美麗華百貨公司做為拍攝電影的背景，屬於合理使用的範圍","原作者自行創作某音樂作品後，即可宣稱擁有該作品之著作權","著作權是為促進文化發展為目的，所保護的財產權之一"],"a":1,"e":"販售仿冒註冊商標的商品屬於公訴罪。"},{"c":7,"n":11,"q":"專利權又可區分為發明、新型與設計三種專利權，其中發明專利權是否有保護期限？期限為何？","o":["有，5 年","有，20 年","有，50 年","無期限，只要申請後就永久歸申請人所有"],"a":2,"e":"發明專利權的期限為自申請日起20年。"},{"c":7,"n":12,"q":"受僱人於職務上所完成之著作，如果沒有特別以契約約定，其著作人為下列何者？","o":["雇用人","受僱人","雇用公司或機關法人代表","由雇用人指定之自然人或法人"],"a":2,"e":"職務上完成的著作，若沒有約定，以受僱人為著作人（著作財產權歸雇用人）。"},{"c":7,"n":13,"q":"任職於某公司的程式設計工程師，因職務所編寫之電腦程式，如果沒有特別以契約約定，則該電腦程式之著作財產權歸屬下列何者？","o":["公司","編寫程式之工程師","公司全體股東共有","公司與編寫程式之工程師共有"],"a":1,"e":"職務上完成的電腦程式，若沒有約定，著作財產權歸公司（雇用人）。"},{"c":7,"n":14,"q":"某公司員工因執行業務，擅自以重製之方法侵害他人之著作財產權，若被害人提起告訴，下列對於處罰對象的敘述，何者正確？","o":["僅處罰侵犯他人著作財產權之員工","僅處罰雇用該名員工的公司","該名員工及其雇主皆須受罰","員工只要在從事侵犯他人著作財產權之行為前請示雇主並獲同意，便可以不受處罰"],"a":3,"e":"員工執行業務時侵權，員工與雇主都要受罰（兩罰規定）。"},{"c":7,"n":15,"q":"受僱人於職務上所完成之發明、新型或設計，其專利申請權及專利權如未特別約定屬於下列何者？","o":["雇用人","受僱人","雇用人所指定之自然人或法人","雇用人與受僱人共有"],"a":1,"e":"職務上的發明，若沒有約定，專利申請權與專利權屬於雇用人。"},{"c":7,"n":16,"q":"任職大發公司的郝聰明，專門從事技術研發，有關研發技術的專利申請權及專利權歸屬，下列敘述何者錯誤？","o":["職務上所完成的發明，除契約另有約定外，專利申請權及專利權屬於大發公司","職務上所完成的發明，雖然專利申請權及專利權屬於大發公司，但是郝聰明享有姓名表示權","郝聰明完成非職務上的發明，應即以書面通知大發公司","大發公司與郝聰明之雇傭契約約定，郝聰明非職務上的發明，全部屬於公司，約定有效"],"a":4,"e":"約定非職務上的發明全部歸公司，剝奪受僱人的權益，這種約定無效。"},{"c":7,"n":17,"q":"有關著作權的敘述，下列何者錯誤？","o":["我們到表演場所觀看表演時，不可隨便錄音或錄影","到攝影展上，拿相機拍攝展示的作品，分贈給朋友，是侵害著作權的行為","網路上供人下載的免費軟體，都不受著作權法保護，所以我可以燒成大補帖光碟，再去賣給別人","高普考試題，不受著作權法保護"],"a":3,"e":"免費下載的軟體仍受著作權保護，燒錄販售屬於侵權。"},{"c":7,"n":18,"q":"有關著作權的敘述，下列何者錯誤？","o":["撰寫碩博士論文時，在合理範圍內引用他人的著作，只要註明出處，不會構成侵害著作權","在網路散布盜版光碟，不管有沒有營利，會構成侵害著作權","在網路的部落格看到一篇文章很棒，只要註明出處，就可以把文章複製在自己的部落格","將補習班老師的上課內容錄音檔，放到網路上拍賣，會構成侵害著作權"],"a":3,"e":"即使註明出處，整篇複製他人文章仍可能侵權，應取得授權或合理引用。"},{"c":7,"n":19,"q":"有關商標權的敘述，下列何者錯誤？","o":["要取得商標權一定要申請商標註冊","商標註冊後可取得 10 年商標權","商標註冊後，3 年不使用，會被廢止商標權","在夜市買的仿冒品，品質不好，上網拍賣，不會構成侵權"],"a":4,"e":"販賣仿冒品屬於侵害商標權的行為，不論品質好壞。"},{"c":7,"n":20,"q":"有關營業秘密的敘述，下列何者錯誤？","o":["受雇人於非職務上研究或開發之營業秘密，仍歸雇用人所有","營業秘密不得為質權及強制執行之標的","營業秘密所有人得授權他人使用其營業秘密","營業秘密得全部或部分讓與他人或與他人共有"],"a":1,"e":"受雇人在非職務上研發的營業秘密，原則上歸受雇人所有。"},{"c":7,"n":21,"q":"甲公司將其新開發受營業秘密法保護之技術，授權乙公司使用，下列何者錯誤？","o":["乙公司已獲授權，所以可以未經甲公司同意，再授權丙公司使用","約定授權使用限於一定之地域、時間","約定授權使用限於特定之內容、一定之使用方法","要求被授權人乙公司在一定期間負有保密義務"],"a":1,"e":"被授權人未經授權人同意，不得再授權第三人使用。"},{"c":7,"n":22,"q":"甲公司嚴格保密之最新配方產品大賣，下列何者侵害甲公司之營業秘密？","o":["鑑定人 A 因司法審理而知悉配方","甲公司授權乙公司使用其配方","甲公司之 B 員工擅自將配方盜賣給乙公司","甲公司與乙公司協議共有配方"],"a":3,"e":"員工擅自將配方盜賣，是侵害營業秘密的行為。"},{"c":7,"n":23,"q":"故意侵害他人之營業秘密，法院因被害人之請求，最高得酌定損害額幾倍之賠償？","o":["1 倍","2 倍","3 倍","4 倍"],"a":3,"e":"故意侵害營業秘密，法院最高得酌定損害額3倍的賠償。"},{"c":7,"n":24,"q":"受雇者因承辦業務而知悉營業秘密，在離職後對於該營業秘密的處理方式，下列敘述何者正確？","o":["聘雇關係解除後便不再負有保障營業秘密之責","僅能自用而不得販售獲取利益","自離職日起 3 年後便不再負有保障營業秘密之責","離職後仍不得洩漏該營業秘密"],"a":4,"e":"離職後仍不得洩漏原公司的營業秘密。"},{"c":7,"n":25,"q":"按照現行法律規定，侵害他人營業秘密，其法律責任為","o":["僅需負刑事責任","僅需負民事損害賠償責任","刑事責任與民事損害賠償責任皆須負擔","刑事責任與民事損害賠償責任皆不須負擔"],"a":3,"e":"侵害營業秘密，刑事責任與民事賠償責任都要負擔。"},{"c":7,"n":26,"q":"企業內部之營業秘密，可以概分為「商業性營業秘密」及「技術性營業秘密」二大類型，請問下列何者屬於「技術性營業秘密」？","o":["人事管理","經銷據點","產品配方","客戶名單"],"a":3,"e":"產品配方屬於技術性營業秘密；人事、經銷、客戶名單屬於商業性營業秘密。"},{"c":7,"n":27,"q":"某離職同事請求在職員工將離職前所製作之某份文件傳送給他，請問下列回應方式何者正確？","o":["由於該項文件係由該離職員工製作，因此可以傳送文件","若其目的僅為保留檔案備份，便可以傳送文件","可能構成對於營業秘密之侵害，應予拒絕並請他直接向公司提出請求","視彼此交情決定是否傳送文件"],"a":3,"e":"公司文件可能涉及營業秘密，應拒絕傳送，並請對方直接向公司申請。"},{"c":7,"n":28,"q":"行為人以竊取等不正當方法取得營業秘密，下列敘述何者正確？","o":["已構成犯罪","只要後續沒有洩漏便不構成犯罪","只要後續沒有出現使用之行為便不構成犯罪","只要後續沒有造成所有人之損害便不構成犯罪"],"a":1,"e":"以竊取等不正當方法取得營業秘密，即已構成犯罪。"},{"c":7,"n":29,"q":"針對在我國境內竊取營業秘密後，意圖在外國、中國大陸或港澳地區使用者，營業秘密法是否可以適用？","o":["無法適用","可以適用，但若屬未遂犯則不罰","可以適用並加重其刑","能否適用需視該國家或地區與我國是否簽訂相互保護營業秘密之條約或協定"],"a":3,"e":"意圖在境外使用而竊取營業秘密，可以適用營業秘密法並加重其刑。"},{"c":7,"n":30,"q":"所謂營業秘密，係指方法、技術、製程、配方、程式、設計或其他可用於生產、銷售或經營之資訊，但其保障所需符合的要件不包括下列何者？","o":["因其秘密性而具有實際之經濟價值者","所有人已採取合理之保密措施者","因其秘密性而具有潛在之經濟價值者","一般涉及該類資訊之人所知者"],"a":4,"e":"營業秘密必須是一般人所不知道的資訊；眾所皆知的資訊不受保護。"},{"c":7,"n":31,"q":"因故意或過失而不法侵害他人之營業秘密者，負損害賠償責任該損害賠償之請求權，自請求權人知有行為及賠償義務人時起，幾年間不行使就會消滅？","o":["2 年","5 年","7 年","10 年"],"a":1,"e":"營業秘密的損害賠償請求權，自知道之日起2年內不行使就消滅。"},{"c":7,"n":32,"q":"公司負責人為了要節省開銷，將員工薪資以高報低來投保全民健保及勞保，是觸犯了刑法上之何種罪刑？","o":["詐欺罪","侵占罪","背信罪","工商秘密罪"],"a":1,"e":"以高報低投保健保與勞保，屬於詐欺行為。"},{"c":7,"n":33,"q":"A受僱於公司擔任會計，因自己的財務陷入危機，多次將公司帳款轉入妻兒戶頭，是觸犯了刑法上之何種罪刑？","o":["洩漏工商秘密罪","侵占罪","詐欺罪","偽造文書罪"],"a":2,"e":"業務上持有公司款項而據為己有，屬於侵占罪。"},{"c":7,"n":34,"q":"某甲於公司擔任業務經理時，未依規定經董事會同意，私自與自己親友之公司訂定生意合約，會觸犯下列何種罪刑？","o":["侵占罪","貪污罪","背信罪","詐欺罪"],"a":3,"e":"違背職務、圖利親友而損害公司利益，屬於背信罪。"},{"c":7,"n":35,"q":"如果你擔任公司採購的職務，親朋好友們會向你推銷自家的產品，希望你要採購時，你應該","o":["適時地婉拒，說明利益需要迴避的考量，請他們見諒","既然是親朋好友，就應該互相幫忙","建議親朋好友將產品折扣，折扣部分歸於自己，就會採購","可以暗中地幫忙親朋好友，進行採購，不要被發現有親友關係便可"],"a":1,"e":"面對親友推銷，應婉拒並說明需要利益迴避。"},{"c":7,"n":36,"q":"小美是公司的業務經理，有一天巧遇國中同班的死黨小林，發現他是公司的下游廠商老闆。最近小美處理一件公司的招標案件，小林的公司也在其中，私下約小美見面，請求她提供這次招標案的底標，並馬上要給予幾十萬元的前謝金，請問小美該怎麼辦？","o":["退回錢，並告訴小林都是老朋友，一定會全力幫忙","收下錢，將錢拿出來給單位同事們分紅","應該堅決拒絕，並避免每次見面都與小林談論相關業務問題","朋友一場，給他一個比較接近底標的金額，反正又不是正確的，所以沒關係"],"a":3,"e":"應堅決拒絕賄賂，並避免與對方私下談論業務。"},{"c":7,"n":37,"q":"公司發給每人一台平板電腦提供業務上使用，但是發現根本很少在使用，為了讓它有效的利用，所以將它拿回家給親人使用，這樣的行為是","o":["可以的，這樣就不用花錢買","可以的，反正放在那裡不用它，也是浪費資源","不可以的，因為這是公司的財產，不能私用","不可以的，因為使用年限未到，如果年限到報廢了，便可以拿回家"],"a":3,"e":"公司財產不可以私用。"},{"c":7,"n":38,"q":"公司的車子，假日又沒人使用，你是鑰匙保管者，請問假日可以開出去嗎？","o":["可以，只要付費加油即可","可以，反正假日不影響公務","不可以，因為是公司的，並非私人擁有","不可以，應該是讓公司想要使用的員工，輪流使用才可"],"a":3,"e":"公司車輛屬於公司財產，不可私用。"},{"c":7,"n":39,"q":"阿哲是財經線的新聞記者，某次採訪中得知A公司在一個月內將有一個大的併購案，這個併購案顯示公司的財力，且能讓A公司股價往上飆升。請問阿哲得知此消息後，可以立刻購買該公司的股票嗎？","o":["可以，有錢大家賺","可以，這是我努力獲得的消息","可以，不賺白不賺","不可以，屬於內線消息，必須保持記者之操守，不得洩漏"],"a":4,"e":"利用職務得知的未公開重大消息買賣股票，屬於內線交易。"},{"c":7,"n":40,"q":"與公務機關接洽業務時，下列敘述何者正確？","o":["沒有要求公務員違背職務，花錢疏通而已，並不違法","唆使公務機關承辦採購人員配合浮報價額，僅屬偽造文書行為","口頭允諾行賄金額但還沒送錢，尚不構成犯罪","與公務員同謀之共犯，即便不具公務員身分，仍可依據貪污治罪條例處刑"],"a":4,"e":"不具公務員身分的人與公務員共同犯罪，也可以依貪污治罪條例處罰。"},{"c":7,"n":41,"q":"與公務機關有業務往來構成職務利害關係者，下列敘述何者正確？","o":["將餽贈之財物請公務員父母代轉，該公務員亦已違反規定","與公務機關承辦人飲宴應酬為增進基本關係的必要方法","高級茶葉低價售予有利害關係之承辦公務員，有價購行為就不算違反法規","機關公務員藉子女婚宴廣邀業務往來廠商之行為，並無不妥"],"a":1,"e":"透過公務員父母轉交餽贈財物，公務員同樣違反規定。"},{"c":7,"n":42,"q":"廠商某甲承攬公共工程，工程進行期間，甲與其工程人員經常招待該公共工程委辦機關之監工及驗收之公務員喝花酒或招待出國旅遊，下列敘述何者正確？","o":["公務員若沒有收現金，就沒有罪","只要工程沒有問題，某甲與監工及驗收等相關公務員就沒有犯罪","因為不是送錢，所以都沒有犯罪","某甲與相關公務員均已涉嫌觸犯貪污治罪條例"],"a":4,"e":"招待喝花酒、出國旅遊屬於不正利益，雙方都涉嫌貪污。"},{"c":7,"n":43,"q":"行（受）賄罪成立要素之一為具有對價關係，而作為公務員職務之對價有「賄賂」或「不正利益」，下列何者不屬於「賄賂」或「不正利益」？","o":["開工邀請公務員觀禮","送百貨公司大額禮券","免除債務","招待吃米其林等級之高檔大餐"],"a":1,"e":"單純邀請觀禮不屬於賄賂或不正利益。"},{"c":7,"n":44,"q":"下列有關貪腐的敘述何者錯誤？","o":["貪腐會危害永續發展和法治","貪腐會破壞民主體制及價值觀","貪腐會破壞倫理道德與正義","貪腐有助降低企業的經營成本"],"a":4,"e":"貪腐會增加企業經營成本，不會降低。"},{"c":7,"n":45,"q":"下列何者不是設置反貪腐專責機構須具備的必要條件？","o":["賦予該機構必要的獨立性","使該機構的工作人員行使職權不會受到不當干預","提供該機構必要的資源、專職工作人員及必要培訓","賦予該機構的工作人員有權力可隨時逮捕貪污嫌疑人"],"a":4,"e":"反貪機構需有獨立性與資源，但不能隨時任意逮捕人。"},{"c":7,"n":46,"q":"檢舉人向有偵查權機關或政風機構檢舉貪污瀆職，必須於何時為之始可能給與獎金？","o":["犯罪未起訴前","犯罪未發覺前","犯罪未遂前","預備犯罪前"],"a":2,"e":"必須在犯罪未發覺前檢舉，才可能給予獎金。"},{"c":7,"n":47,"q":"檢舉人應以何種方式檢舉貪污瀆職始能核給獎金？","o":["匿名","委託他人檢舉","以真實姓名檢舉","以他人名義檢舉"],"a":3,"e":"必須以真實姓名檢舉，才能核給獎金。"},{"c":7,"n":48,"q":"我國制定何種法律以保護刑事案件之證人，使其勇於出面作證，俾利犯罪之偵查、審判？","o":["貪污治罪條例","刑事訴訟法","行政程序法","證人保護法"],"a":4,"e":"保護證人勇於作證的法律是證人保護法。"},{"c":7,"n":49,"q":"下列何者非屬公司對於企業社會責任實踐之原則？","o":["加強個人資料揭露","維護社會公益","發展永續環境","落實公司治理"],"a":1,"e":"企業社會責任應保護個人資料，不是加強揭露。"},{"c":7,"n":50,"q":"下列何者並不屬於「職業素養」規範中的範疇？","o":["增進自我獲利的能力","擁有正確的職業價值觀","積極進取職業的知識技能","具備良好的職業行為習慣"],"a":1,"e":"職業素養強調職業價值觀、知識技能與行為習慣，不是增進自我獲利。"},{"c":7,"n":51,"q":"下列何者符合專業人員的職業道德？","o":["未經雇主同意，於上班時間從事私人事務","利用雇主的機具設備私自接單生產","未經顧客同意，任意散佈或利用顧客資料","盡力維護雇主及客戶的權益"],"a":4,"e":"盡力維護雇主及客戶的權益，符合職業道德。"},{"c":7,"n":52,"q":"身為公司員工必須維護公司利益，下列何者是正確的工作態度或行為？","o":["將公司逾期的產品更改標籤","施工時以省時、省料為獲利首要考量，不顧品質","服務時優先考量公司的利益，顧客權益次之","工作時謹守本分，以積極態度解決問題"],"a":4,"e":"謹守本分、以積極態度解決問題，是正確的工作態度。"},{"c":7,"n":53,"q":"身為專業技術工作人士，應以何種認知及態度服務客戶？","o":["若客戶不瞭解，就儘量減少成本支出，抬高報價","遇到維修問題，儘量拖過保固期","主動告知可能碰到問題及預防方法","隨著個人心情來提供服務的內容及品質"],"a":3,"e":"專業人員應主動告知客戶可能遇到的問題與預防方法。"},{"c":7,"n":54,"q":"因為工作本身需要高度專業技術及知識，所以在對客戶服務時應如何？","o":["不用理會顧客的意見","保持親切、真誠、客戶至上的態度","若價錢較低，就敷衍了事","以專業機密為由，不用對客戶說明及解釋"],"a":2,"e":"服務客戶應保持親切、真誠、客戶至上的態度。"},{"c":7,"n":55,"q":"從事專業性工作，在與客戶約定時間應","o":["保持彈性，任意調整","儘可能準時，依約定時間完成工作","能拖就拖，能改就改","自己方便就好，不必理會客戶的要求"],"a":2,"e":"與客戶約定時間應準時，並依約完成工作。"},{"c":7,"n":56,"q":"從事專業性工作，在服務顧客時應有的態度為何？","o":["選擇最安全、經濟及有效的方法完成工作","選擇工時較長、獲利較多的方法服務客戶","為了降低成本，可以降低安全標準","不必顧及雇主和顧客的立場"],"a":1,"e":"應選擇最安全、經濟又有效的方法完成工作。"},{"c":7,"n":57,"q":"以下哪一項員工的作為符合敬業精神？","o":["利用正常工作時間從事私人事務","運用雇主的資源，從事個人工作","未經雇主同意擅離工作崗位","謹守職場紀律及禮節，尊重客戶隱私"],"a":4,"e":"謹守職場紀律與禮節、尊重客戶隱私，符合敬業精神。"},{"c":7,"n":58,"q":"小張獲選為小孩學校的家長會長，這個月要召開會議，沒時間準備資料，所以，利用上班期間有空檔非休息時間來完成，請問是否可以？","o":["可以，因為不耽誤他的工作","可以，因為他能力好，能夠同時完成很多事","不可以，因為這是私事，不可以利用上班時間完成","可以，只要不要被發現"],"a":3,"e":"上班時間處理私事不符合職業倫理。"},{"c":7,"n":59,"q":"小吳是公司的專用司機，為了能夠隨時用車，經過公司同意，每晚都將公司的車開回家，然而，他發現反正每天上班路線，都要經過女兒學校，就順便載女兒上學，請問可以嗎？","o":["可以，反正順路","不可以，這是公司的車不能私用","可以，只要不被公司發現即可","可以，要資源須有效使用"],"a":2,"e":"公司車不可私用，即使順路也不可以。"},{"c":7,"n":60,"q":"小江是職場上的新鮮人，剛進公司不久，他應該具備怎樣的態度？","o":["上班、下班，管好自己便可","仔細觀察公司生態，加入某些小團體，以做為後盾","只要做好人脈關係，這樣以後就好辦事","努力做好自己職掌的業務，樂於工作，與同事之間有良好的互動，相互協助"],"a":4,"e":"新人應努力做好分內工作，並與同事保持良好互動。"},{"c":7,"n":61,"q":"在公司內部行使商務禮儀的過程，主要以參與者在公司中的何種條件來訂定順序？","o":["年齡","性別","社會地位","職位"],"a":4,"e":"公司內的商務禮儀以職位高低定順序。"},{"c":7,"n":62,"q":"一位職場新鮮人剛進公司時，良好的工作態度是","o":["多觀察、多學習，了解企業文化和價值觀","多打聽哪一個部門比較輕鬆，升遷機會較多","多探聽哪一個公司在找人，隨時準備跳槽走人","多遊走各部門認識同事，建立自己的小圈圈"],"a":1,"e":"新人應多觀察、多學習，了解企業文化。"},{"c":7,"n":63,"q":"根據消除對婦女一切形式歧視公約(CEDAW)，下列何者正確？","o":["對婦女的歧視指基於性別而作的任何區別、排斥或限制","只關心女性在政治方面的人權和基本自由","未要求政府需消除個人或企業對女性的歧視","傳統習俗應予保護及傳承，即使含有歧視女性的部分，也不可以改變"],"a":1,"e":"CEDAW定義的歧視，是基於性別而作的任何區別、排斥或限制。"},{"c":7,"n":64,"q":"某規範明定地政機關進用女性測量助理名額，不得超過該機關測量助理名額總數二分之一，根據消除對婦女一切形式歧視公約(CEDAW)，下列何者正確？","o":["限制女性測量助理人數比例，屬於直接歧視","土地測量經常在戶外工作，基於保護女性所作的限制，不屬性別歧視","此項二分之一規定是為促進男女比例平衡","此限制是為確保機關業務順暢推動，並未歧視女性"],"a":1,"e":"限制女性錄取名額，屬於直接歧視。"},{"c":7,"n":65,"q":"根據消除對婦女一切形式歧視公約(CEDAW)之間接歧視意涵，下列何者錯誤？","o":["一項法律、政策、方案或措施表面上對男性和女性無任何歧視，但實際上卻產生歧視女性的效果","察覺間接歧視的一個方法，是善加利用性別統計與性別分析","如果未正視歧視之結構和歷史模式，及忽略男女權力關係之不平等，可能使現有不平等狀況更為惡化","不論在任何情況下，只要以相同方式對待男性和女性，就能避免間接歧視之產生"],"a":4,"e":"形式上相同對待，仍可能產生間接歧視，必須考量實際結果。"},{"c":7,"n":66,"q":"下列何者不是菸害防制法之立法目的？","o":["防制菸害","保護未成年免於菸害","保護孕婦免於菸害","促進菸品的使用"],"a":4,"e":"菸害防制法的目的是防制菸害，不會促進菸品使用。"},{"c":7,"n":67,"q":"按菸害防制法規定，在禁菸場所吸菸會被罰多少錢？","o":["新臺幣 2 千元至 1 萬元罰鍰","新臺幣 1 千元至 5 千元罰鍰","新臺幣 1 萬元至 5 萬元罰鍰","新臺幣 2 萬元至 10 萬元罰鍰"],"a":1,"e":"在禁菸場所吸菸，處新臺幣2千元至1萬元罰鍰。"},{"c":7,"n":68,"q":"請問下列何者不是個人資料保護法所定義的個人資料？","o":["身分證號碼","最高學歷","職稱","護照號碼"],"a":3,"e":"單純的職稱無法識別特定個人，題庫判定不屬於個人資料。"},{"c":7,"n":69,"q":"有關專利權的敘述，下列何者正確？","o":["專利有規定保護年限，當某商品、技術的專利保護年限屆滿，任何人皆可免費運用該項專利","我發明了某項商品，卻被他人率先申請專利權，我仍可主張擁有這項商品的專利權","製造方法可以申請新型專利權","在本國申請專利之商品進軍國外，不需向他國申請專利權"],"a":1,"e":"專利保護期限屆滿後，任何人都可以免費使用該技術。"},{"c":7,"n":70,"q":"下列何者行為會有侵害著作權的問題？","o":["將報導事件事實的新聞文字轉貼於自己的社群網站","直接轉貼高普考考古題在 FACEBOOK","以分享網址的方式轉貼資訊分享於社群網站","將講師的授課內容錄音，複製多份分贈友人"],"a":4,"e":"錄下講師的授課內容並複製分送，屬於侵害著作權。"},{"c":7,"n":71,"q":"有關著作權之概念，下列何者正確？","o":["國外學者之著作，可受我國著作權法的保護","公務機關所函頒之公文，受我國著作權法的保護","著作權要待向智慧財產權申請通過後才可主張","以傳達事實之新聞報導的語文著作，依然受著作權之保障"],"a":1,"e":"依互惠原則，外國人的著作也受我國著作權法保護。"},{"c":7,"n":72,"q":"某廠商之商標在我國已經獲准註冊，請問若希望將商品行銷販賣到國外，請問是否需在當地申請註冊才能主張商標權？","o":["是，因為商標權註冊採取屬地保護原則","否，因為我國申請註冊之商標權在國外也會受到承認","不一定，需視我國是否與商品希望行銷販賣的國家訂有相互商標承認之協定","不一定，需視商品希望行銷販賣的國家是否為 WTO 會員國"],"a":1,"e":"商標權採屬地主義，到國外銷售需在當地另外申請註冊。"},{"c":7,"n":73,"q":"下列何者不屬於營業秘密？","o":["具廣告性質的不動產交易底價","須授權取得之產品設計或開發流程圖示","公司內部管制的各種計畫方案","不是公開可查知的客戶名單分析資料"],"a":1,"e":"帶有廣告性質、已對外公開的底價，不屬於營業秘密。"},{"c":7,"n":74,"q":"營業秘密可分為「技術機密」與「商業機密」，下列何者屬於「商業機密」？","o":["程式","設計圖","商業策略","生產製程"],"a":3,"e":"商業策略屬於商業機密；程式、設計圖、製程屬於技術機密。"},{"c":7,"n":75,"q":"某甲在公務機關擔任首長，其弟弟乙是某協會的理事長，乙為舉辦協會活動，決定向甲服務的機關申請經費補助，下列有關利益衝突迴避之敘述，何者正確？","o":["協會是舉辦慈善活動，甲認為是好事，所以指示機關承辦人補助活動經費","機關未經公開公平方式，私下直接對協會補助活動經費新臺幣 10 萬元","甲應自行迴避該案審查，避免瓜田李下，防止利益衝突","乙為順利取得補助，應該隱瞞是機關首長甲之弟弟的身分"],"a":3,"e":"公職人員遇到有利害關係的案件，應自行迴避。"},{"c":7,"n":76,"q":"依公職人員利益衝突迴避法規定，公職人員甲與其小舅子乙（二親等以內的關係人）間，下列何種行為不違反該法？","o":["甲要求受其監督之機關聘用小舅子乙","小舅子乙以請託關說之方式，請求甲之服務機關通過其名下農地變更使用申請案","關係人乙經政府採購法公開招標程序，並主動在投標文件表明與甲的身分關係，取得甲服務機關之年度採購標案","甲、乙兩人均自認為人公正，處事坦蕩，任何往來都是清者自清，不需擔心任何問題"],"a":3,"e":"經公開招標程序並主動揭露身分關係，不違反利益衝突迴避法。"},{"c":7,"n":77,"q":"大雄擔任公司部門主管，代表公司向公務機關投標，為使公司順利取得標案，可以向公務機關的採購人員為以下何種行為？","o":["為社交禮俗需要，贈送價值昂貴的名牌手錶作為見面禮","為與公務機關間有良好互動，招待至有女陪侍場所飲宴","為了解招標文件內容，提出招標文件疑義並請說明","為避免報價錯誤，要求提供底價作為參考"],"a":3,"e":"對招標文件有疑義，可以依程序提出並請機關說明。"},{"c":7,"n":78,"q":"下列關於政府採購人員之敘述，何者未違反相關規定？","o":["非主動向廠商求取，是偶發地收到廠商致贈價值在新臺幣 500 元以下之廣告物、促銷品、紀念品","要求廠商提供與採購無關之額外服務","利用職務關係向廠商借貸","利用職務關係媒介親友至廠商處所任職"],"a":1,"e":"偶發、非主動求取、價值500元以下的廣告物或紀念品，可以收受。"},{"c":7,"n":79,"q":"下列敘述何者錯誤？","o":["憲法保障言論自由，但散布假新聞、假消息仍須面對法律責任","在網路或 Line 社群網站收到假訊息，可以敘明案情並附加截圖檔，向法務部調查局檢舉","對新聞媒體報導有意見，向國家通訊傳播委員會申訴","自己或他人捏造、扭曲、竄改或虛構的訊息，只要一小部分能證明是真的，就不會構成假訊息"],"a":4,"e":"即使部分內容屬實，捏造或扭曲的訊息仍可能構成假訊息。"},{"c":7,"n":80,"q":"下列敘述何者正確？","o":["公務機關委託的代檢（代驗）業者，不是公務員，不會觸犯到刑法的罪責","賄賂或不正利益，只限於法定貨幣，給予網路遊戲幣沒有違法的問題","在靠北公務員社群網站，覺得可受公評且匿名發文，就可以謾罵公務機關對特定案件的檢查情形","受公務機關委託辦理案件，除履行採購契約應辦事項外，對於蒐集到的個人資料，也要遵守相關保護及保密規定"],"a":4,"e":"受託辦理公務時，對蒐集到的個資也要遵守保護與保密規定。"},{"c":7,"n":81,"q":"有關促進參與及預防貪腐的敘述，下列何者錯誤？","o":["我國非聯合國會員國，無須落實聯合國反貪腐公約規定","推動政府部門以外之個人及團體積極參與預防和打擊貪腐","提高決策過程之透明度，並促進公眾在決策過程中發揮作用","對公職人員訂定執行公務之行為守則或標準"],"a":1,"e":"我國雖非聯合國會員國，仍透過施行法落實反貪腐公約。"},{"c":7,"n":82,"q":"為建立良好之公司治理制度，公司內部宜納入何種檢舉人制度？","o":["告訴乃論制度","吹哨者（whistleblower）保護程序及保護制度","不告不理制度","非告訴乃論制度"],"a":2,"e":"公司治理應建立吹哨者保護制度。"},{"c":7,"n":83,"q":"有關公司訂定誠信經營守則時，下列何者錯誤？","o":["避免與涉有不誠信行為者進行交易","防範侵害營業秘密、商標權、專利權、著作權及其他智慧財產權","建立有效之會計制度及內部控制制度","防範檢舉"],"a":4,"e":"誠信經營應鼓勵並保護檢舉，不是防範檢舉。"},{"c":7,"n":84,"q":"乘坐轎車時，如有司機駕駛，按照國際乘車禮儀，以司機的方位來看，首位應為","o":["後排右側","前座右側","後排左側","後排中間"],"a":1,"e":"有司機駕駛時，後排右側為首位。"},{"c":7,"n":85,"q":"今天好友突然來電，想來個「說走就走的旅行」，因此，無法去上班，下列何者作法不適當？","o":["發送 E-MAIL 給主管與人事部門，並收到回覆","什麼都無需做，等公司打電話來確認後，再告知即可","用 LINE 傳訊息給主管，並確認讀取且有回覆","打電話給主管與人事部門請假"],"a":2,"e":"無法上班必須事先請假並取得主管回覆，不能等公司打電話來詢問。"},{"c":7,"n":86,"q":"每天下班回家後，就懶得再出門去買菜，利用上班時間瀏覽線上購物網站，發現有很多限時搶購的便宜商品，還能在下班前就可以送到公司，下班順便帶回家，省掉好多時間，下列何者最適當？","o":["可以，又沒離開工作崗位，且能節省時間","可以，還能介紹同事一同團購，省更多的錢，增進同事情誼","不可以，應該把商品寄回家，不是公司","不可以，上班不能從事個人私務，應該等下班後再網路購物"],"a":4,"e":"上班時間不應處理個人私事，例如網購。"},{"c":7,"n":87,"q":"宜樺家中養了一隻貓，由於最近生病，獸醫師建議要有人一直陪牠，這樣會恢復快一點，辦公室雖然禁止攜帶寵物，但因為上班家裡無人陪伴，所以準備帶牠到辦公室一起上班，下列何者最適當？","o":["可以，只要我放在寵物箱，不要影響工作即可","可以，同事們都答應也不反對","可以，雖然貓會發出聲音，大小便有異味，只要處理好不影響工作即可","不可以，可以送至專門機構照護或請專人照顧，以免影響工作"],"a":4,"e":"辦公室禁止攜帶寵物就應遵守，可以改送專門機構照護。"},{"c":7,"n":88,"q":"根據性別平等工作法，下列何者非屬職場性騷擾？","o":["公司員工執行職務時，客戶對其講黃色笑話，該員工感覺被冒犯","雇主對求職者要求交往，作為僱用與否之交換條件","公司員工執行職務時，遭到同事以「女人就是沒大腦」性別歧視用語加以辱罵，該員工感覺其人格尊嚴受損","公司員工下班後搭乘捷運，在捷運上遭到其他乘客偷拍"],"a":4,"e":"下班後在捷運上被陌生人偷拍，不是執行職務期間，不屬於職場性騷擾（適用性騷擾防治法）。"},{"c":7,"n":89,"q":"根據性別平等工作法，下列何者非屬職場性別歧視？","o":["雇主考量男性賺錢養家之社會期待，提供男性高於女性之薪資","雇主考量女性以家庭為重之社會期待，裁員時優先資遣女性","雇主事先與員工約定倘其有懷孕之情事，必須離職","有未滿 2 歲子女之男性員工，也可申請每日六十分鐘的哺乳時間"],"a":4,"e":"男性員工也可以申請哺乳時間，是性別平等的措施，不是歧視。"},{"c":7,"n":90,"q":"根據性別平等工作法，有關雇主防治性騷擾之責任與罰則，下列何者錯誤？","o":["僱用受僱者 30 人以上者，應訂定性騷擾防治措施、申訴及懲戒規範","雇主知悉性騷擾發生時，應採取立即有效之糾正及補救措施","雇主違反應訂定性騷擾防治措施之規定時，處以罰鍰即可，不用公布其姓名","雇主違反應訂定性騷擾申訴管道者，應限期令其改善，屆期未改善者，應按次處罰"],"a":3,"e":"雇主違反防治規定，除了罰鍰，也會公布其姓名。"},{"c":7,"n":91,"q":"根據性騷擾防治法，有關性騷擾之責任與罰則，下列何者錯誤？","o":["對他人為性騷擾者，如果沒有造成他人財產上之損失，就無需負擔金錢賠償之責任","對於因教育、訓練、醫療、公務、業務、求職，受自己監督、照護之人，利用權勢或機會為性騷擾者，得加重科處罰鍰至二分之一","意圖性騷擾，乘人不及抗拒而為親吻、擁抱或觸摸其臀部、胸部或其他身體隱私處之行為者，處 2 年以下有期徒刑、拘役或併科 10 萬元以下罰金","對他人為權勢性騷擾以外之性騷擾者，由直轄市、縣（市）主管機關處 1 萬元以上 10 萬元以下罰鍰"],"a":1,"e":"性騷擾即使沒有財產損失，被害人仍可請求非財產上的損害賠償。"},{"c":7,"n":92,"q":"根據性別平等工作法規範職場性騷擾範疇，下列何者錯誤？","o":["上班執行職務時，任何人以性要求、具有性意味或性別歧視之言詞或行為，造成敵意性、脅迫性或冒犯性之工作環境","對僱用、求職或執行職務關係受自己指揮、監督之人，利用權勢或機會為性騷擾","與朋友聚餐後回家時，被陌生人以盯梢、守候、尾隨跟蹤","雇主對受僱者或求職者為明示或暗示之性要求、具有性意味或性別歧視之言詞或行為"],"a":3,"e":"下班後被陌生人跟蹤，不屬於職場性騷擾範疇（適用跟蹤騷擾防制法）。"},{"c":7,"n":93,"q":"根據消除對婦女一切形式歧視公約（CEDAW）之直接歧視及間接歧視意涵，下列何者錯誤？","o":["老闆得知小黃懷孕後，故意將小黃調任薪資待遇較差的工作，意圖使其自行離開職場，小黃老闆的行為是直接歧視","某餐廳於網路上招募外場服務生，條件以未婚年輕女性優先錄取，明顯以性或性別差異為由所實施的差別待遇，為直接歧視","某公司員工值班注意事項排除女性員工參與夜間輪值，是考量女性有人身安全及家庭照顧等需求，為維護女性權益之措施，非直接歧視","某科技公司規定男女員工之加班時數上限及加班費或津貼不同，認為女性能力有限，且無法長時間工作，限制女性獲取薪資及升遷機會，這規定是直接歧視"],"a":3,"e":"以保護為名排除女性參與夜間輪值，仍是基於性別的差別待遇，屬於直接歧視。"},{"c":7,"n":94,"q":"目前菸害防制法規範，「不可販賣菸品」給未滿幾歲的人？","o":["20","19","18","17"],"a":1,"e":"菸害防制法規定，不得販賣菸品給未滿20歲的人。"},{"c":7,"n":95,"q":"按菸害防制法規定，下列敘述何者錯誤？","o":["只有老闆、店員才可以出面勸阻在禁菸場所抽菸的人","任何人都可以出面勸阻在禁菸場所抽菸的人","餐廳、旅館設置室內吸菸室，需經專業技師簽證核可","加油站屬易燃易爆場所，任何人都可以勸阻在禁菸場所抽菸的人"],"a":1,"e":"任何人都可以勸阻在禁菸場所吸菸的人。"},{"c":7,"n":96,"q":"關於菸品對人體危害的敘述，下列何者正確？","o":["只要開電風扇、或是抽風機就可以去除菸霧中的有害物質","指定菸品（如：加熱菸）只要通過健康風險評估，就不會危害健康，因此工作時如果想吸菸，就可以在職場拿出來使用","雖然自己不吸菸，同事在旁邊吸菸，就會增加自己得肺癌的機率","只要不將菸吸入肺部，就不會對身體造成傷害"],"a":3,"e":"二手菸會增加不吸菸者罹患肺癌的風險。"},{"c":7,"n":97,"q":"職場禁菸的好處不包括","o":["降低吸菸者的菸品使用量，有助於減少吸菸導致的疾病而請假","避免同事因為被動吸菸而生病","讓吸菸者菸癮降低，戒菸較容易成功","吸菸者不能抽菸會影響工作效率"],"a":4,"e":"職場禁菸的好處不包括「影響工作效率」，這反而是反對禁菸的說法。"},{"c":7,"n":98,"q":"大多數的吸菸者都嘗試過戒菸，但是很少自己戒菸成功。吸菸的同事要戒菸，怎樣建議他是無效的？","o":["鼓勵他撥打戒菸專線 0800-63-63-63，取得相關建議與協助","建議他到醫療院所、社區藥局找藥物戒菸","建議他參加醫院或衛生所辦理的戒菸班","戒菸是自己的事，別人幫不了忙"],"a":4,"e":"戒菸可以靠專線、藥物、戒菸班等外部協助，不是只能靠自己。"},{"c":7,"n":99,"q":"禁菸場所負責人未於場所入口處設置明顯禁菸標示，要罰該場所負責人多少元？","o":["2 千至 1 萬","1 萬至 5 萬","1 萬至 25 萬","20 萬至 100 萬"],"a":2,"e":"未設置禁菸標示，處場所負責人1萬至5萬元罰鍰。"},{"c":7,"n":100,"q":"目前電子煙是非法的，下列對電子煙的敘述，何者錯誤？","o":["跟吸菸一樣會成癮","會有爆炸危險","沒有燃燒的菸草，也沒有二手煙的問題","可能造成嚴重肺損傷"],"a":3,"e":"電子煙仍會產生有害氣膠，同樣有二手煙的問題。"},{"c":8,"n":1,"q":"世界環境日是在每一年的哪一日？","o":["3 月 8 日","6 月 5 日","11 月 12 日","4 月 10 日"],"a":2,"e":"世界環境日是每年6月5日。"},{"c":8,"n":2,"q":"2015年巴黎協議之目的為何？","o":["避免臭氧層破壞","減少持久性污染物排放","遏阻全球暖化趨勢","生物多樣性保育"],"a":3,"e":"巴黎協定的目的是遏阻全球暖化。"},{"c":8,"n":3,"q":"下列何者為環境保護的正確作為？","o":["多吃肉少蔬食","自己開車不共乘","鐵馬步行","不隨手關燈"],"a":3,"e":"騎腳踏車、步行可以減少碳排放。"},{"c":8,"n":4,"q":"下列何種行為對生態環境會造成較大的衝擊？","o":["種植原生樹木","引進外來物種","設立國家公園","設立自然保護區"],"a":2,"e":"外來物種可能破壞原有生態平衡，衝擊最大。"},{"c":8,"n":5,"q":"下列哪一種飲食習慣能減碳抗暖化？","o":["多吃速食","多吃天然蔬果","多吃牛肉","多選擇吃到飽的餐館"],"a":2,"e":"多吃天然蔬果可以減少加工與運輸的碳排放。"},{"c":8,"n":6,"q":"飼主遛狗時，其狗在道路或其他公共場所便溺時，下列何者應優先負清除責任？","o":["主人","清潔隊","警察","土地所有權人"],"a":1,"e":"狗在公共場所便溺，飼主應負清除責任。"},{"c":8,"n":7,"q":"外食自備餐具是落實綠色消費的哪一項表現？","o":["重複使用","回收再生","環保選購","降低成本"],"a":1,"e":"自備餐具屬於重複使用。"},{"c":8,"n":8,"q":"再生能源一般是指可永續利用之能源，主要包括哪些：A.化石燃料、B.風力、C.太陽能、D.水力？","o":["ABCD","ABD","BCD","ACD"],"a":3,"e":"再生能源包括風力、太陽能、水力；化石燃料不屬於再生能源。"},{"c":8,"n":9,"q":"依環境基本法第3條規定，基於國家長期利益，經濟、科技及社會發展均應兼顧環境保護。但如果經濟、科技及社會發展對環境有嚴重不良影響或有危害時，應以何者優先？","o":["經濟","科技","社會","環境"],"a":4,"e":"發展對環境有嚴重不良影響時，應以環境保護優先。"},{"c":8,"n":10,"q":"森林面積的減少甚至消失可能導致哪些影響：A.水資源減少B.減緩全球暖化C.加劇全球暖化D.降低生物多樣性？","o":["ACD","BCD","ABD","ABCD"],"a":1,"e":"森林減少會使水資源減少、加劇暖化、降低生物多樣性。"},{"c":8,"n":11,"q":"塑膠為海洋生態的殺手，所以政府推動「無塑海洋」政策，下列何項不是減少塑膠危害海洋生態的重要措施？","o":["擴大禁止免費供應塑膠袋","禁止製造、進口及販售含塑膠柔珠的清潔用品","定期進行海水水質監測","淨灘、淨海"],"a":3,"e":"監測水質是了解現況，不能直接減少塑膠危害。"},{"c":8,"n":12,"q":"違反環境保護法律或自治條例之行政法上義務，經處分機關處停工、停業處分或處新臺幣五千元以上罰鍰者，應接受下列何種講習？","o":["道路交通安全講習","環境講習","衛生講習","消防講習"],"a":2,"e":"違反環保法規而受停工、停業處分或5千元以上罰鍰，需接受環境講習。"},{"c":8,"n":13,"q":"下列何者為環保標章？","o":["","","",""],"a":1,"e":"綠色地球與葉片圖樣是我國環保標章。","oi":["img/q837_1.jpg","img/q837_2.jpg","img/q837_3.jpg","img/q837_4.jpg"]},{"c":8,"n":14,"q":"「聖嬰現象」是指哪一區域的溫度異常升高？","o":["西太平洋表層海水","東太平洋表層海水","西印度洋表層海水","東印度洋表層海水"],"a":2,"e":"聖嬰現象是東太平洋表層海水溫度異常升高。"},{"c":8,"n":15,"q":"「酸雨」定義為雨水酸鹼值達多少以下時稱之？","o":["5.0","6.0","7.0","8.0"],"a":1,"e":"雨水pH值低於5.0稱為酸雨。"},{"c":8,"n":16,"q":"一般而言，水中溶氧量隨水溫之上升而呈下列哪一種趨勢？","o":["增加","減少","不變","不一定"],"a":2,"e":"水溫越高，水中溶氧量越少。"},{"c":8,"n":17,"q":"二手菸中包含多種危害人體的化學物質，甚至多種物質有致癌性，會危害到下列何者的健康？","o":["只對 12 歲以下孩童有影響","只對孕婦比較有影響","只對 65 歲以上之民眾有影響","對二手菸接觸民眾皆有影響"],"a":4,"e":"二手菸對所有接觸的民眾都有影響。"},{"c":8,"n":18,"q":"二氧化碳和其他溫室氣體含量增加是造成全球暖化的主因之一，下列何種飲食方式也能降低碳排放量，對環境保護做出貢獻：A.少吃肉，多吃蔬菜；B.玉米產量減少時，購買玉米罐頭食用；C.選擇當地食材；D.使用免洗餐具，減少清洗用水與清潔劑？","o":["AB","AC","AD","ACD"],"a":2,"e":"少吃肉、選擇當地食材可以減少碳排放；罐頭與免洗餐具反而增加資源消耗。"},{"c":8,"n":19,"q":"上下班的交通方式有很多種，其中包括：A.騎腳踏車；B.搭乘大眾交通工具；C.自行開車，請將前述幾種交通方式之單位排碳量由少至多之排列方式為何？","o":["ABC","ACB","BAC","CBA"],"a":1,"e":"排碳量由少到多：騎腳踏車 < 大眾運輸 < 自行開車。"},{"c":8,"n":20,"q":"下列何者「不是」室內空氣污染源？","o":["建材","辦公室事務機","廢紙回收箱","油漆及塗料"],"a":3,"e":"廢紙回收箱一般不會釋放空氣污染物。"},{"c":8,"n":21,"q":"下列何者不是自來水消毒採用的方式？","o":["加入臭氧","加入氯氣","紫外線消毒","加入二氧化碳"],"a":4,"e":"自來水常用氯、臭氧、紫外線消毒，不會加入二氧化碳。"},{"c":8,"n":22,"q":"下列何者不是造成全球暖化的元凶？","o":["汽機車排放的廢氣","工廠所排放的廢氣","火力發電廠所排放的廢氣","種植樹木"],"a":4,"e":"種樹可以吸收二氧化碳，減緩暖化。"},{"c":8,"n":23,"q":"下列何者不是造成臺灣水資源減少的主要因素？","o":["超抽地下水","雨水酸化","水庫淤積","濫用水資源"],"a":2,"e":"雨水酸化與水量減少無直接關係；超抽、淤積、濫用才是主因。"},{"c":8,"n":24,"q":"下列何者是海洋受污染的現象？","o":["形成紅潮","形成黑潮","溫室效應","臭氧層破洞"],"a":1,"e":"紅潮是藻類大量繁殖，常因水體優養化污染造成。"},{"c":8,"n":25,"q":"水中生化需氧量（BOD）愈高，其所代表的意義為下列何者？","o":["水為硬水","有機污染物多","水質偏酸","分解污染物時不需消耗太多氧"],"a":2,"e":"BOD愈高，表示水中有機污染物愈多。"},{"c":8,"n":26,"q":"下列何者是酸雨對環境的影響？","o":["湖泊水質酸化","增加森林生長速度","土壤肥沃","增加水生動物種類"],"a":1,"e":"酸雨會使湖泊水質酸化。"},{"c":8,"n":27,"q":"下列哪一項水質濃度降低會導致河川魚類大量死亡？","o":["氨氮","溶氧","二氧化碳","生化需氧量"],"a":2,"e":"溶氧量降低，魚類會缺氧死亡。"},{"c":8,"n":28,"q":"下列何種生活小習慣的改變可減少細懸浮微粒（PM 2 . 5）排放，共同為改善空氣品質盡一份心力？","o":["少吃燒烤食物","使用吸塵器","養成運動習慣","每天喝 500cc 的水"],"a":1,"e":"燒烤會產生大量細懸浮微粒，少吃可以減少排放。"},{"c":8,"n":29,"q":"下列哪種措施不能用來降低空氣污染？","o":["汽機車強制定期排氣檢測","汰換老舊柴油車","禁止露天燃燒稻草","汽機車加裝消音器"],"a":4,"e":"消音器是降低噪音，不能減少空氣污染。"},{"c":8,"n":30,"q":"大氣層中臭氧層有何作用？","o":["保持溫度","對流最旺盛的區域","吸收紫外線","造成光害"],"a":3,"e":"（本題已刪題）臭氧層可以吸收太陽的紫外線。","d":1},{"c":8,"n":31,"q":"小李具有乙級廢水專責人員證照，某工廠希望以高價租用證照的方式合作，請問下列何者正確？","o":["這是違法行為","互蒙其利","價錢合理即可","經環保局同意即可"],"a":1,"e":"出租證照（借牌）是違法行為。"},{"c":8,"n":32,"q":"可藉由下列何者改善河川水質且兼具提供動植物良好棲地環境？","o":["運動公園","人工溼地","滯洪池","水庫"],"a":2,"e":"人工溼地可以淨化水質，也提供動植物棲地。"},{"c":8,"n":33,"q":"台灣自來水之水源主要取自","o":["海洋的水","河川或水庫的水","綠洲的水","灌溉渠道的水"],"a":2,"e":"台灣自來水主要取自河川與水庫。"},{"c":8,"n":34,"q":"目前市面清潔劑均會強調「無磷」，是因為含磷的清潔劑使用後，若廢水排至河川或湖泊等水域會造成什麼影響？","o":["綠牡蠣","優養化","秘雕魚","烏腳病"],"a":2,"e":"含磷廢水會造成水體優養化，藻類大量繁殖。"},{"c":8,"n":35,"q":"冰箱在廢棄回收時應特別注意哪一項物質，以避免逸散至大氣中造成臭氧層的破壞？","o":["冷媒","甲醛","汞","苯"],"a":1,"e":"冰箱的冷媒（氟氯碳化物等）逸散會破壞臭氧層。"},{"c":8,"n":36,"q":"下列何者不是噪音的危害所造成的現象？","o":["精神很集中","煩躁、失眠","緊張、焦慮","工作效率低落"],"a":1,"e":"噪音會使人煩躁、焦慮、效率低落，不會讓精神更集中。"},{"c":8,"n":37,"q":"我國移動污染源空氣污染防制費的徵收機制為何？","o":["依車輛里程數計費","隨油品銷售徵收","依牌照徵收","依照排氣量徵收"],"a":2,"e":"移動污染源空污費是隨油品銷售徵收。"},{"c":8,"n":38,"q":"室內裝潢時，若不謹慎選擇建材，將會逸散出氣狀污染物。其中會刺激皮膚、眼、鼻和呼吸道，也是致癌物質，可能為下列哪一種污染物？","o":["臭氧","甲醛","氟氯碳化合物","二氧化碳"],"a":2,"e":"甲醛會刺激皮膚與呼吸道，也是致癌物質。"},{"c":8,"n":39,"q":"高速公路旁常見農田違法焚燒稻草，其產生下列何種汙染物除了對人體健康造成不良影響外，亦會造成濃煙影響行車安全？","o":["懸浮微粒","二氧化碳(CO 2 )","臭氧(O 3 )","沼氣"],"a":1,"e":"焚燒稻草會產生大量懸浮微粒，影響健康與行車視線。"},{"c":8,"n":40,"q":"都市中常產生的「熱島效應」會造成何種影響？","o":["增加降雨","空氣污染物不易擴散","空氣污染物易擴散","溫度降低"],"a":2,"e":"熱島效應使都市空氣污染物不易擴散。"},{"c":8,"n":41,"q":"下列何者不是藉由蚊蟲傳染的疾病？","o":["日本腦炎","瘧疾","登革熱","痢疾"],"a":4,"e":"痢疾經由糞口途徑傳染，不是蚊蟲傳染。"},{"c":8,"n":42,"q":"下列何者非屬資源回收分類項目中「廢紙類」的回收物？","o":["報紙","雜誌","紙袋","用過的衛生紙"],"a":4,"e":"用過的衛生紙不能回收，應丟一般垃圾。"},{"c":8,"n":43,"q":"下列何者對飲用瓶裝水之形容是正確的？A.飲用後之寶特瓶容器為地球增加了一個廢棄物；B.運送瓶裝水時卡車會排放空氣污染物；C.瓶裝水一定比經煮沸之自來水安全衛生？","o":["AB","BC","AC","ABC"],"a":1,"e":"寶特瓶增加廢棄物、運送產生污染；瓶裝水不一定比煮沸的自來水安全。"},{"c":8,"n":44,"q":"下列哪一項是我們在家中常見的環境衛生用藥？","o":["體香劑","殺蟲劑","洗滌劑","乾燥劑"],"a":2,"e":"殺蟲劑屬於環境衛生用藥。"},{"c":8,"n":45,"q":"下列何者為公告應回收的廢棄物？A.廢鋁箔包、B.廢紙容器、C.寶特瓶","o":["ABC","AC","BC","C"],"a":1,"e":"廢鋁箔包、廢紙容器、寶特瓶都是公告應回收的項目。"},{"c":8,"n":46,"q":"小明拿到「垃圾強制分類」的宣導海報，標語寫著「分3類，好OK」，標語中的分3類是指家戶日常生活中產生的垃圾可以區分哪三類？","o":["資源垃圾、廚餘、事業廢棄物","資源垃圾、一般廢棄物、事業廢棄物","一般廢棄物、事業廢棄物、放射性廢棄物","資源垃圾、廚餘、一般垃圾"],"a":4,"e":"垃圾強制分三類：資源垃圾、廚餘、一般垃圾。"},{"c":8,"n":47,"q":"家裡有過期的藥品，請問這些藥品要如何處理？","o":["倒入馬桶沖掉","交由藥局回收","繼續服用","送給相同疾病的朋友"],"a":2,"e":"（本題已刪題）過期藥品應交由藥局回收。","d":1},{"c":8,"n":48,"q":"台灣西部海岸曾發生的綠牡蠣事件是與下列何種物質污染水體有關？","o":["汞","銅","磷","鎘"],"a":2,"e":"綠牡蠣事件是銅污染造成的。"},{"c":8,"n":49,"q":"在生物鏈越上端的物種其體內累積持久性有機污染物(POPs)濃度將越高，危害性也將越大，這是說明POPs具有下列何種特性？","o":["持久性","半揮發性","高毒性","生物累積性"],"a":4,"e":"污染物沿食物鏈逐漸累積，稱為生物累積性。"},{"c":8,"n":50,"q":"有關小黑蚊的敘述，下列何者為非？","o":["活動時間以中午十二點到下午三點為活動高峰期","小黑蚊的幼蟲以腐植質、青苔和藻類為食","無論雄性或雌性皆會吸食哺乳類動物血液","多存在竹林、灌木叢、雜草叢、果園等邊緣地帶等處"],"a":3,"e":"小黑蚊只有雌蚊會吸血。"},{"c":8,"n":51,"q":"利用垃圾焚化廠處理垃圾的最主要優點為何？","o":["減少處理後的垃圾體積","去除垃圾中所有毒物","減少空氣污染","減少處理垃圾的程序"],"a":1,"e":"焚化可以大幅減少垃圾體積。"},{"c":8,"n":52,"q":"利用豬隻的排泄物當燃料發電，是屬於下列哪一種能源？","o":["地熱能","太陽能","生質能","核能"],"a":3,"e":"動物排泄物、農業廢棄物等生物質轉換的能源，屬於生質能。"},{"c":8,"n":53,"q":"每個人日常生活皆會產生垃圾，有關處理垃圾的觀念與方式，下列何者不正確？","o":["垃圾分類，使資源回收再利用","所有垃圾皆掩埋處理，垃圾將會自然分解","廚餘回收堆肥後製成肥料","可燃性垃圾經焚化燃燒可有效減少垃圾體積"],"a":2,"e":"很多垃圾（如塑膠）無法自然分解，全部掩埋不是正確做法。"},{"c":8,"n":54,"q":"防治蚊蟲最好的方法是","o":["使用殺蟲劑","清除孳生源","網子捕捉","拍打"],"a":2,"e":"清除積水容器等孳生源，是防治蚊蟲最根本的方法。"},{"c":8,"n":55,"q":"室內裝修業者承攬裝修工程，工程中所產生的廢棄物應該如何處理？","o":["委託合法清除機構清運","倒在偏遠山坡地","河岸邊掩埋","交給清潔隊垃圾車"],"a":1,"e":"裝修廢棄物屬事業廢棄物，應委託合法清除機構清運。"},{"c":8,"n":56,"q":"若使用後的廢電池未經回收，直接廢棄所含重金屬物質曝露於環境中可能產生哪些影響？A.地下水污染、B.對人體產生中毒等不良作用、C.對生物產生重金屬累積及濃縮作用、D.造成優養化","o":["ABC","ABCD","ACD","BCD"],"a":1,"e":"廢電池的重金屬會污染地下水、使人中毒、在生物體內累積；優養化是氮磷造成的。"},{"c":8,"n":57,"q":"哪一種家庭廢棄物可用來作為製造肥皂的主要原料？","o":["食醋","果皮","回鍋油","熟廚餘"],"a":3,"e":"回鍋油含油脂，可以和鹼製成肥皂。"},{"c":8,"n":58,"q":"世紀之毒「戴奧辛」主要透過何者方式進入人體？","o":["透過觸摸","透過呼吸","透過飲食","透過雨水"],"a":3,"e":"（本題已刪題）戴奧辛主要經由飲食（含脂肪的食物）進入人體。","d":1},{"c":8,"n":59,"q":"臺灣地狹人稠，垃圾處理一直是不易解決的問題，下列何種是較佳的因應對策？","o":["垃圾分類資源回收","蓋焚化廠","運至國外處理","向海爭地掩埋"],"a":1,"e":"垃圾分類、資源回收是從源頭減量的最佳對策。"},{"c":8,"n":60,"q":"購買下列哪一種商品對環境比較友善？","o":["用過即丟的商品","一次性的產品","材質可以回收的商品","過度包裝的商品"],"a":3,"e":"選購材質可回收的商品，對環境比較友善。"},{"c":8,"n":61,"q":"下列何項法規的立法目的為預防及減輕開發行為對環境造成不良影響，藉以達成環境保護之目的？","o":["公害糾紛處理法","環境影響評估法","環境基本法","環境教育法"],"a":2,"e":"環境影響評估法的目的，是預防及減輕開發行為對環境的不良影響。"},{"c":8,"n":62,"q":"下列何種開發行為若對環境有不良影響之虞者，應實施環境影響評估？A.開發科學園區；B.新建捷運工程；C.採礦","o":["AB","BC","AC","ABC"],"a":4,"e":"開發科學園區、新建捷運、採礦都屬於應實施環評的開發行為。"},{"c":8,"n":63,"q":"主管機關審查環境影響說明書或評估書，如認為已足以判斷未對環境有重大影響之虞，作成之審查結論可能為下列何者？","o":["通過環境影響評估審查","應繼續進行第二階段環境影響評估","認定不應開發","補充修正資料再審"],"a":1,"e":"足以判斷不會對環境有重大影響時，審查結論為通過環評。"},{"c":8,"n":64,"q":"依環境影響評估法規定，對環境有重大影響之虞的開發行為應繼續進行第二階段環境影響評估，下列何者不是上述對環境有重大影響之虞或應進行第二階段環境影響評估的決定方式？","o":["明訂開發行為及規模","環評委員會審查認定","自願進行","有民眾或團體抗爭"],"a":4,"e":"民眾抗爭不是法定決定第二階段環評的方式。"},{"c":8,"n":65,"q":"依環境教育法，環境教育之戶外學習應選擇何地點辦理？","o":["遊樂園","環境教育設施或場所","森林遊樂區","海洋世界"],"a":2,"e":"環境教育的戶外學習，應選擇環境教育設施或場所。"},{"c":8,"n":66,"q":"依環境影響評估法規定，環境影響評估審查委員會審查環境影響說明書，認定下列對環境有重大影響之虞者，應繼續進行第二階段環境影響評估，下列何者非屬對環境有重大影響之虞者？","o":["對保育類動植物之棲息生存有顯著不利之影響","對國家經濟有顯著不利之影響","對國民健康有顯著不利之影響","對其他國家之環境有顯著不利之影響"],"a":2,"e":"對國家經濟的影響不屬於環評法所列「對環境有重大影響之虞」的項目。"},{"c":8,"n":67,"q":"依環境影響評估法規定，第二階段環境影響評估，目的事業主管機關應舉行下列何種會議？","o":["研討會","聽證會","辯論會","公聽會"],"a":4,"e":"第二階段環評，目的事業主管機關應舉行公聽會。"},{"c":8,"n":68,"q":"開發單位申請變更環境影響說明書、評估書內容或審查結論，符合下列哪一情形，得檢附變更內容對照表辦理？","o":["既有設備提昇產能而污染總量增加在百分之十以下","降低環境保護設施處理等級或效率","環境監測計畫變更","開發行為規模增加未超過百分之五"],"a":3,"e":"環境監測計畫變更，可以檢附變更內容對照表辦理。"},{"c":8,"n":69,"q":"開發單位變更原申請內容有下列哪一情形，無須就申請變更部分，重新辦理環境影響評估？","o":["不降低環保設施之處理等級或效率","規模擴增百分之十以上","對環境品質之維護有不利影響","土地使用之變更涉及原規劃之保護區"],"a":1,"e":"不降低環保設施的處理等級或效率，不需要重新辦理環評。"},{"c":8,"n":70,"q":"工廠或交通工具排放空氣污染物之檢查，下列何者錯誤？","o":["依中央主管機關規定之方法使用儀器進行檢查","檢查人員以嗅覺進行氨氣濃度之判定","檢查人員以嗅覺進行異味濃度之判定","檢查人員以肉眼進行粒狀污染物不透光率之判定"],"a":2,"e":"氨氣濃度必須用儀器檢測，不能用嗅覺判定（異味可以用嗅覺判定）。"},{"c":8,"n":71,"q":"下列對於空氣污染物排放標準之敘述，何者正確：A.排放標準由中央主管機關訂定；B.所有行業之排放標準皆相同？","o":["僅 A","僅 B","AB 皆正確","AB 皆錯誤"],"a":1,"e":"排放標準由中央主管機關訂定，不同行業的標準不同。"},{"c":8,"n":72,"q":"下列對於細懸浮微粒（PM 2 . 5）之敘述何者正確？A.空氣品質測站中自動監測儀所測得之數值若高於空氣品質標準，即判定為不符合空氣品質標準；B.濃度監測之標準方法為中央主管機關公告之手動檢測方法；C.空氣品質標準之年平均值為15μg/m 3？","o":["僅 AB","僅 BC","僅 AC","ABC 皆正確"],"a":2,"e":"（本題已刪題）PM2.5監測以中央公告的手動檢測方法為準，年平均標準值為15μg/m³（依當時標準）。","d":1},{"c":8,"n":73,"q":"機車為空氣污染物之主要排放來源之一，下列何者可降低空氣污染物之排放量：A.將四行程機車全面汰換成二行程機車；B.推廣電動機車；C.降低汽油中之硫含量？","o":["僅 AB","僅 BC","僅 AC","ABC 皆正確"],"a":2,"e":"推廣電動機車、降低油品硫含量可以減少污染；二行程機車污染反而較大。"},{"c":8,"n":74,"q":"公眾聚集量大且滯留時間長之場所，經公告應設置自動監測設施，其應量測之室內空氣污染物項目為何？","o":["二氧化碳","一氧化碳","臭氧","甲醛"],"a":1,"e":"公共場所的室內空品自動監測，主要量測二氧化碳。"},{"c":8,"n":75,"q":"空氣污染源依排放特性分為固定污染源及移動污染源，下列何者屬於移動污染源？","o":["焚化廠","石化廠","機車","煉鋼廠"],"a":3,"e":"機車屬於移動污染源。"},{"c":8,"n":76,"q":"我國汽機車移動污染源空氣污染防制費的徵收機制為何？","o":["依牌照徵收","隨水費徵收","隨油品銷售徵收","購車時徵收"],"a":3,"e":"移動污染源空污費是隨油品銷售徵收。"},{"c":8,"n":77,"q":"細懸浮微粒（PM 2 . 5）除了來自於污染源直接排放外，亦可能經由下列哪一種反應產生？","o":["光合作用","酸鹼中和","厭氧作用","光化學反應"],"a":4,"e":"PM2.5也可能由空氣中的污染物經光化學反應生成。"},{"c":8,"n":78,"q":"我國固定污染源空氣污染防制費以何種方式徵收？","o":["依營業額徵收","隨使用原料徵收","按工廠面積徵收","依排放污染物之種類及數量徵收"],"a":4,"e":"固定污染源空污費依排放污染物的種類與數量徵收。"},{"c":8,"n":79,"q":"在不妨害水體正常用途情況下，水體所能涵容污染物之量稱為","o":["涵容能力","放流能力","運轉能力","消化能力"],"a":1,"e":"水體能涵容污染物而不妨害正常用途的量，稱為涵容能力。"},{"c":8,"n":80,"q":"水污染防治法中所稱地面水體不包括下列何者？","o":["河川","海洋","灌溉渠道","地下水"],"a":4,"e":"地面水體不包括地下水。"},{"c":8,"n":81,"q":"下列何者不是主管機關設置水質監測站採樣的項目？","o":["水溫","氫離子濃度指數","溶氧量","顏色"],"a":4,"e":"水質監測項目包括水溫、pH、溶氧等；顏色不是法定採樣項目。"},{"c":8,"n":82,"q":"事業、污水下水道系統及建築物污水處理設施之廢（污）水處理，其產生之污泥，依規定應作何處理？","o":["應妥善處理，不得任意放置或棄置","可作為農業肥料","可作為建築土方","得交由清潔隊處理"],"a":1,"e":"污泥應妥善處理，不得任意放置或棄置。"},{"c":8,"n":83,"q":"依水污染防治法，事業排放廢（污）水於地面水體者，應符合下列哪一標準之規定？","o":["下水水質標準","放流水標準","水體分類水質標準","土壤處理標準"],"a":2,"e":"排放廢水到地面水體，應符合放流水標準。"},{"c":8,"n":84,"q":"放流水標準，依水污染防治法應由何機關定之：A.中央主管機關；B.中央主管機關會同相關目的事業主管機關；C.中央主管機關會商相關目的事業主管機關？","o":["僅 A","僅 B","僅 C","ABC"],"a":3,"e":"放流水標準由中央主管機關會商相關目的事業主管機關訂定。"},{"c":8,"n":85,"q":"對於噪音之量測，下列何者錯誤？","o":["可於下雨時測量","風速大於每秒 5 公尺時不可量測","聲音感應器應置於離地面或樓板延伸線 1.2 至 1.5 公尺之間","測量低頻噪音時，僅限於室內地點測量，非於戶外量測"],"a":1,"e":"下雨時不可以測量噪音，雨聲會干擾量測結果。"},{"c":8,"n":86,"q":"對於噪音管制法之規定，下列敘述何者錯誤？","o":["噪音指超過管制標準之聲音","環保局得視噪音狀況劃定公告噪音管制區","人民得向主管機關檢舉使用中機動車輛噪音妨害安寧情形","使用經校正合格之噪音計皆可執行噪音管制法規定之檢驗測定"],"a":4,"e":"執行噪音管制的檢驗測定，必須依法定方法並由合格人員進行，不是有校正合格的噪音計就可以。"},{"c":8,"n":87,"q":"製造非持續性但卻妨害安寧之聲音者，由下列何單位依法進行處理？","o":["警察局","環保局","社會局","消防局"],"a":1,"e":"非持續性、妨害安寧的聲音（如深夜喧嘩）由警察依社會秩序維護法處理。"},{"c":8,"n":88,"q":"廢棄物、剩餘土石方清除機具應隨車持有證明文件且應載明廢棄物、剩餘土石方之：A產生源；B處理地點；C清除公司","o":["僅 AB","僅 BC","僅 AC","ABC 皆是"],"a":1,"e":"清除機具隨車文件要載明廢棄物的產生源與處理地點。"},{"c":8,"n":89,"q":"從事廢棄物清除、處理業務者，應向直轄市、縣（市）主管機關或中央主管機關委託之機關取得何種文件後，始得受託清除、處理廢棄物業務？","o":["公民營廢棄物清除處理機構許可文件","運輸車輛駕駛證明","運輸車輛購買證明","公司財務證明"],"a":1,"e":"從事廢棄物清除處理業務，應先取得公民營廢棄物清除處理機構許可文件。"},{"c":8,"n":90,"q":"在何種情形下，禁止輸入事業廢棄物：A.對國內廢棄物處理有妨礙；B.可直接固化處理、掩埋、焚化或海拋；C.於國內無法妥善清理？","o":["僅 A","僅 B","僅 C","ABC"],"a":4,"e":"妨礙國內處理、可直接固化掩埋焚化海拋、國內無法妥善清理的事業廢棄物，都禁止輸入。"},{"c":8,"n":91,"q":"毒性化學物質因洩漏、化學反應或其他突發事故而污染運作場所周界外之環境，運作人應立即採取緊急防治措施，並至遲於多久時間內，報知直轄市、縣（市）主管機關？","o":["1 小時","2 小時","4 小時","30 分鐘"],"a":4,"e":"毒化物污染場外環境，運作人應在30分鐘內報知主管機關。"},{"c":8,"n":92,"q":"下列何種物質或物品，受毒性及關注化學物質管理法之管制？","o":["製造醫藥之靈丹","製造農藥之蓋普丹","含汞之日光燈","使用青石綿製造石綿瓦"],"a":4,"e":"（本題已刪題）青石綿屬於毒性化學物質，受毒管法管制。","d":1},{"c":8,"n":93,"q":"下列何行為不是土壤及地下水污染整治法所指污染行為人之作為？","o":["洩漏或棄置污染物","非法排放或灌注污染物","仲介或容許洩漏、棄置、非法排放或灌注污染物","依法令規定清理污染物"],"a":4,"e":"依法令規定清理污染物是正當行為，不是污染行為。"},{"c":8,"n":94,"q":"依土壤及地下水污染整治法規定，進行土壤、底泥及地下水污染調查、整治及提供、檢具土壤及地下水污染檢測資料時，其土壤、底泥及地下水污染物檢驗測定，應委託何單位辦理？","o":["經中央主管機關許可之檢測機構","大專院校","政府機關","自行檢驗"],"a":1,"e":"污染檢測應委託經中央主管機關許可的檢測機構辦理。"},{"c":8,"n":95,"q":"為解決環境保護與經濟發展的衝突與矛盾，1992年聯合國環境發展大會（UN Conference on Environment and Development, UNCED）制定通過","o":["日內瓦公約","蒙特婁公約","21 世紀議程","京都議定書"],"a":3,"e":"1992年聯合國環境與發展大會通過「21世紀議程」。"},{"c":8,"n":96,"q":"一般而言，下列哪一個防治策略是屬經濟誘因策略？","o":["可轉換排放許可交易","許可證制度","放流水標準","環境品質標準"],"a":1,"e":"排放許可交易是以市場機制減少排放，屬於經濟誘因策略。"},{"c":8,"n":97,"q":"對溫室氣體管制之「無悔政策」係指","o":["減輕溫室氣體效應之同時，仍可獲致社會效益","全世界各國同時進行溫室氣體減量","各類溫室氣體均有相同之減量邊際成本","持續研究溫室氣體對全球氣候變遷之科學證據"],"a":1,"e":"無悔政策是指減少溫室氣體的同時，也能獲得其他社會效益。"},{"c":8,"n":98,"q":"一般家庭垃圾在進行衛生掩埋後，會經由細菌的分解而產生甲烷氣體，有關甲烷氣體對大氣危機中哪一種效應具有影響力？","o":["臭氧層破壞","酸雨","溫室效應","煙霧（smog）效應"],"a":3,"e":"甲烷是溫室氣體，會加劇溫室效應。"},{"c":8,"n":99,"q":"下列國際環保公約，何者限制各國進行野生動植物交易，以保護瀕臨絕種的野生動植物？","o":["華盛頓公約","巴塞爾公約","蒙特婁議定書","氣候變化綱要公約"],"a":1,"e":"華盛頓公約（CITES）限制瀕危野生動植物的國際交易。"},{"c":8,"n":100,"q":"因人類活動導致哪些營養物過量排入海洋，造成沿海赤潮頻繁發生，破壞了紅樹林、珊瑚礁、海草，亦使魚蝦銳減，漁業損失慘重？","o":["碳及磷","氮及磷","氮及氯","氯及鎂"],"a":2,"e":"氮、磷過量排入海洋會造成優養化與赤潮。"},{"c":9,"n":1,"q":"依經濟部能源署「指定能源用戶應遵行之節約能源規定」，在正常使用條件下，公眾出入之營業場所其室內冷氣溫度平均值不得低於攝氏幾度？","o":["26","25","24","22"],"a":1,"e":"公眾出入營業場所的室內冷氣溫度平均值不得低於26℃。"},{"c":9,"n":2,"q":"下列何者為節能標章？","o":["","","",""],"a":2,"e":"愛心形狀加上電源插頭的圖案是我國節能標章。","oi":["img/q926_1.jpg","img/q926_2.jpg","img/q926_3.jpg","img/q926_4.jpg"]},{"c":9,"n":3,"q":"下列何者為國內能源消費最大部門？","o":["服務業","住宅","運輸","工業"],"a":4,"e":"工業部門是國內最大的能源消費部門。"},{"c":9,"n":4,"q":"下列何者「不是」節省能源的做法？","o":["電冰箱溫度長時間設定在強冷或急冷","影印機當 15 分鐘無人使用時，自動進入省電模式","電視機勿背著窗戶，並避免太陽直射","短程不開汽車，以儘量搭乘公車、騎單車或步行為宜"],"a":1,"e":"冰箱長時間設定強冷，會增加耗電。"},{"c":9,"n":5,"q":"經濟部能源署的能源效率標示中，電冰箱分為幾個等級？","o":["1","3","5","7"],"a":3,"e":"能源效率分級標示分為1～5級。"},{"c":9,"n":6,"q":"溫室氣體排放量：指自排放源排出之各種溫室氣體量乘以各該物質溫暖化潛勢所得之合計量，以","o":["氧化亞氮（N 2 O）","二氧化碳（CO 2 ）","甲烷（CH 4 ）","六氟化硫（SF 6 ）當量表示"],"a":2,"e":"溫室氣體排放量以二氧化碳當量表示。"},{"c":9,"n":7,"q":"根據氣候變遷因應法，國家溫室氣體長期減量目標於中華民國幾年達成溫室氣體淨零排放？","o":["119","129","139","149"],"a":3,"e":"氣候變遷因應法訂定2050年（民國139年）達成淨零排放。"},{"c":9,"n":8,"q":"氣候變遷因應法所稱主管機關，在中央為下列何單位？","o":["經濟部能源署","環境部","國家發展委員會","衛生福利部"],"a":2,"e":"氣候變遷因應法的中央主管機關為環境部。"},{"c":9,"n":9,"q":"氣候變遷因應法中所稱：一單位之排放額度相當於允許排放多少的二氧化碳當量？","o":["1 公斤","1 立方米","1 公噸","1 公升"],"a":3,"e":"一單位排放額度相當於1公噸二氧化碳當量。"},{"c":9,"n":10,"q":"下列何者「不是」全球暖化帶來的影響？","o":["洪水","熱浪","地震","旱災"],"a":3,"e":"地震是地殼運動造成的，與全球暖化無關。"},{"c":9,"n":11,"q":"下列何種方法無法減少二氧化碳？","o":["想吃多少儘量點，剩下可當廚餘回收","選購當地、當季食材，減少運輸碳足跡","多吃蔬菜，少吃肉","自備杯筷，減少免洗用具垃圾量"],"a":1,"e":"點太多菜造成浪費，處理廚餘也會耗能、排碳。"},{"c":9,"n":12,"q":"下列何者不會減少溫室氣體的排放？","o":["減少使用煤、石油等化石燃料","大量植樹造林，禁止亂砍亂伐","增高燃煤氣體排放的煙囪","開發太陽能、水能等新能源"],"a":3,"e":"增高煙囪只是把污染排得更遠，排放總量不變。"},{"c":9,"n":13,"q":"關於綠色採購之敘述，下列何者錯誤？","o":["採購由回收材料所製造之物品","採購的產品對環境及人類健康有最小的傷害性","選購對環境傷害較少、污染程度較低的產品","以精美包裝為主要首選"],"a":4,"e":"綠色採購應避免過度包裝。"},{"c":9,"n":14,"q":"一旦大氣中的二氧化碳含量增加，會引起哪一種後果？","o":["溫室效應惡化","臭氧層破洞","冰期來臨","海平面下降"],"a":1,"e":"二氧化碳增加會使溫室效應惡化。"},{"c":9,"n":15,"q":"關於建築中常用的金屬玻璃帷幕牆，下列敘述何者正確？","o":["玻璃帷幕牆的使用能節省室內空調使用","玻璃帷幕牆適用於臺灣，讓夏天的室內產生溫暖的感覺","在溫度高的國家，建築物使用金屬玻璃帷幕會造成日照輻射熱，產生室內「溫室效應」","臺灣的氣候濕熱，特別適合在大樓以金屬玻璃帷幕作為建材"],"a":3,"e":"在炎熱地區使用玻璃帷幕，日照輻射熱會使室內升溫，增加空調負擔。"},{"c":9,"n":16,"q":"下列何者不是能源之類型？","o":["電力","壓縮空氣","蒸汽","熱傳"],"a":4,"e":"熱傳是熱的傳遞方式，不是能源類型。"},{"c":9,"n":17,"q":"我國已制定能源管理系統標準為","o":["CNS 50001","CNS 12681","CNS 14001","CNS 22000"],"a":1,"e":"我國能源管理系統標準為CNS 50001。"},{"c":9,"n":18,"q":"台灣電力股份有限公司所謂的三段式時間電價於夏月平日（非週六日）之尖峰用電時段為何？","o":["9：00〜24：00","6：00〜11：00","16：00〜22： 00","9：00〜16：00"],"a":3,"e":"夏月平日尖峰時段為16:00～22:00（依題庫版本）。"},{"c":9,"n":19,"q":"基於節能減碳的目標，下列何種光源發光效率最低，不鼓勵使用？","o":["白熾燈泡","LED 燈泡","省電燈泡","螢光燈管"],"a":1,"e":"白熾燈泡發光效率最低，大部分電能變成熱。"},{"c":9,"n":20,"q":"下列的能源效率分級標示，哪一項較省電？","o":["1","2","3","4"],"a":1,"e":"能源效率標示「1級」最省電。"},{"c":9,"n":21,"q":"下列何者「不是」目前台灣主要的發電方式？","o":["燃煤","燃氣","水力","地熱"],"a":4,"e":"地熱目前不是台灣主要的發電方式。"},{"c":9,"n":22,"q":"有關延長線及電線的使用，下列敘述何者錯誤？","o":["拔下延長線插頭時，應手握插頭取下","使用中之延長線如有異味產生，屬正常現象不須理會","應避開火源，以免外覆塑膠熔解，致使用時造成短路","使用老舊之延長線，容易造成短路、漏電或觸電等危險情形，應立即更換"],"a":2,"e":"延長線產生異味可能是過熱，有火災風險，應立即停用。"},{"c":9,"n":23,"q":"有關觸電的處理方式，下列敘述何者錯誤？","o":["立即將觸電者拉離現場","把電源開關關閉","通知救護人員","使用絕緣的裝備來移除電源"],"a":1,"e":"直接拉觸電者，施救者也會觸電，應先切斷電源或用絕緣物移開。"},{"c":9,"n":24,"q":"目前電費單中，係以「度」為收費依據，下列何者為其單位？","o":["kW","kWh","kJ","kJh"],"a":2,"e":"1度電 = 1 kWh（千瓦小時）。"},{"c":9,"n":25,"q":"依據台灣電力公司三段式時間電價（尖峰、半尖峰及離峰時段）的規定，哪個時段電價最便宜？","o":["尖峰時段","夏月半尖峰時段","非夏月半尖峰時段","離峰時段"],"a":4,"e":"離峰時段的電價最便宜。"},{"c":9,"n":26,"q":"當用電設備遭遇電源不足或輸配電設備受限制時，導致用戶暫停或減少用電的情形，常以下列何者名稱出現？","o":["停電","限電","斷電","配電"],"a":2,"e":"因供電不足而要求暫停或減少用電，稱為限電。"},{"c":9,"n":27,"q":"照明控制可以達到節能與省電費的好處，下列何種方法最適合一般住宅社區兼顧節能、經濟性與實際照明需求？","o":["加裝 DALI 全自動控制系統","走廊與地下停車場選用紅外線感應控制電燈","全面調低照明需求","晚上關閉所有公共區域的照明"],"a":2,"e":"走廊與停車場使用紅外線感應燈，兼顧節能與照明需求。"},{"c":9,"n":28,"q":"上班性質的商辦大樓為了降低尖峰時段用電，下列何者錯誤？","o":["使用儲冰式空調系統減少白天空調用電需求","白天有陽光照明，所以白天可以將照明設備全關掉","汰換老舊電梯馬達並使用變頻控制","電梯設定隔層停止控制，減少頻繁啟動"],"a":2,"e":"白天也有照明不足的區域，全部關燈會影響工作與安全。"},{"c":9,"n":29,"q":"為了節能與降低電費的需求，應該如何正確選用家電產品？","o":["選用高功率的產品效率較高","優先選用取得節能標章的產品","設備沒有壞，還是堪用，繼續用，不會增加支出","選用能效分級數字較高的產品，效率較高， 5 級的比 1 級的電器產品更省電"],"a":2,"e":"優先選用取得節能標章的產品；能效分級1級最省電。"},{"c":9,"n":30,"q":"有效而正確的節能從選購產品開始，就一般而言，下列的因素中，何者是選購電氣設備的最優先考量項目？","o":["用電量消耗電功率是多少瓦攸關電費支出，用電量小的優先","採購價格比較，便宜優先","安全第一，一定要通過安規檢驗合格","名人或演藝明星推薦，應該口碑較好"],"a":3,"e":"選購電器以安全第一，必須通過安規檢驗。"},{"c":9,"n":31,"q":"高效率燈具如果要降低眩光的不舒服，下列何者與降低刺眼眩光影響無關？","o":["光源下方加裝擴散板或擴散膜","燈具的遮光板","光源的色溫","採用間接照明"],"a":3,"e":"色溫影響光色感受，與眩光無關。"},{"c":9,"n":32,"q":"用電熱爐煮火鍋，採用中溫50%加熱，比用高溫100%加熱，將同一鍋水煮開，下列何者是對的？","o":["中溫 50%加熱比較省電","高溫 100%加熱比較省電","中溫 50%加熱，電流反而比較大","兩種方式用電量是一樣的"],"a":4,"e":"煮開同一鍋水所需熱量相同；理論上用電量一樣，只是時間長短不同。"},{"c":9,"n":33,"q":"台灣電力公司為降低尖峰負載時段超載的停電風險，將尖峰時段電價費率（每度電單價）提高，離峰時段的費率降低，引導用戶轉移部分負載至離峰時段，這種電能管理策略稱為何？","o":["需量競價","時間電價","可停電力","表燈用戶彈性電價"],"a":2,"e":"依時段訂定不同電價，稱為時間電價。"},{"c":9,"n":34,"q":"集合式住宅的地下停車場需要維持通風良好的空氣品質，又要兼顧節能效益，下列排風扇控制方式何者不恰當？","o":["淘汰老舊排風扇，改裝取得節能標章、適當容量的高效率風扇","兩天一次運轉通風扇就好了","結合一氧化碳偵測器，自動啟動/停止控制","設定每天早晚二次定期啟動排風扇"],"a":2,"e":"兩天才運轉一次無法維持停車場的空氣品質。"},{"c":9,"n":35,"q":"大樓電梯為了節能及生活便利需求，可設定部分控制功能，下列何者是錯誤或不正確的做法？","o":["加感應開關，無人時自動關閉電燈與通風扇","縮短每次開門/關門的時間","電梯設定隔樓層停靠，減少頻繁啟動","電梯馬達加裝變頻控制"],"a":2,"e":"縮短開關門時間可能夾傷乘客，也不是有效的節能措施。"},{"c":9,"n":36,"q":"為了節能及兼顧冰箱的保溫效果，下列何者是錯誤或不正確的做法？","o":["冰箱內上下層間不要塞滿，以利冷藏對流","食物存放位置紀錄清楚，一次拿齊食物，減少開門次數","冰箱門的密封壓條如果鬆弛，無法緊密關門，應儘速更新修復","冰箱內食物擺滿塞滿，效益最高"],"a":4,"e":"冰箱塞滿會妨礙冷氣對流，反而更耗電。"},{"c":9,"n":37,"q":"電鍋剩飯持續保溫至隔天再食用，或剩飯先放冰箱冷藏，隔天用微波爐加熱，就加熱及節能觀點來評比，下列何者正確？","o":["持續保溫較省電","微波爐再加熱比較省電又方便","兩者一樣","優先選電鍋保溫方式，因為馬上就可以吃"],"a":2,"e":"剩飯冷藏後隔天用微波爐加熱，比整晚保溫省電。"},{"c":9,"n":38,"q":"不斷電系統UPS與緊急發電機的裝置都是應付臨時性供電狀況，停電時，下列敘述何者正確？","o":["緊急發電機 UPS 立即啟動，不斷電系統延遲啟動","不斷電系統 UPS 立即啟動，緊急發電機延遲啟動","兩者同時啟動","不斷電系統 UPS 可以撐比較久"],"a":2,"e":"停電時UPS立即供電，緊急發電機需要啟動時間。"},{"c":9,"n":39,"q":"下列何者為非再生能源？","o":["地熱能","焦煤","太陽能","水力能"],"a":2,"e":"焦煤是化石燃料，屬於非再生能源。"},{"c":9,"n":40,"q":"有關冷凍冷藏櫃之除霜方式，下列何者最節能？","o":["電熱除霜","熱氣除霜","用吹風機除霜","打開冰箱門除霜"],"a":2,"e":"熱氣除霜利用系統本身的熱，最節能。"},{"c":9,"n":41,"q":"一般桶裝瓦斯（液化石油氣）主要成分為丁烷與下列何種成分所組成？","o":["甲烷","乙烷","丙烷","辛烷"],"a":3,"e":"桶裝瓦斯主要成分是丙烷與丁烷。"},{"c":9,"n":42,"q":"在正常操作，且提供相同暖氣之情形下，下列何種暖氣設備之能源效率最高？","o":["冷暖氣機","電熱風扇","電熱輻射機","電暖爐"],"a":1,"e":"冷暖氣機（熱泵）的能源效率最高。"},{"c":9,"n":43,"q":"下列何種熱水器所需能源費用最少？","o":["電熱水器","天然瓦斯熱水器","柴油鍋爐熱水器","熱泵熱水器"],"a":4,"e":"熱泵熱水器效率最高，能源費用最少。"},{"c":9,"n":44,"q":"某公司希望能進行節能減碳，為地球盡點心力，以下何種作為並不恰當？","o":["將採購規定列入以下文字：「汰換設備時首先考慮能源效率 1 級或具有節能標章之產品」","盤查所有能源使用設備","實行能源管理","為考慮經營成本，汰換設備時採買最便宜的機種"],"a":4,"e":"只買最便宜的機種，往往效率差、長期更耗能。"},{"c":9,"n":45,"q":"冷氣外洩會造成能源之浪費，下列的入門設施與管理何者最耗能？","o":["全開式有氣簾","全開式無氣簾","自動門有氣簾","自動門無氣簾"],"a":2,"e":"全開式入口沒有氣簾，冷氣外洩最多。"},{"c":9,"n":46,"q":"下列何者「不是」潔淨能源？","o":["風能","地熱","太陽能","頁岩氣"],"a":4,"e":"頁岩氣是化石燃料，不是潔淨能源。"},{"c":9,"n":47,"q":"有關再生能源中的風力、太陽能的使用特性中，下列敘述何者錯誤？","o":["間歇性能源，供應不穩定","不易受天氣影響","需較大的土地面積","設置成本較高"],"a":2,"e":"風力與太陽能容易受天氣影響。"},{"c":9,"n":48,"q":"有關台灣能源發展所面臨的挑戰，下列何者錯誤？","o":["進口能源依存度高，能源安全易受國際影響","化石能源所占比例高，溫室氣體減量壓力大","自產能源充足，不需仰賴進口","能源密集度較先進國家仍有改善空間"],"a":3,"e":"台灣自產能源不足，絕大部分仰賴進口。"},{"c":9,"n":49,"q":"若發生瓦斯外洩之情形，下列處理方法何者錯誤？","o":["應先關閉瓦斯爐或熱水器等開關","緩慢地打開門窗，讓瓦斯自然飄散","開啟電風扇，加強空氣流動","在漏氣止住前，應保持警戒，嚴禁煙火"],"a":3,"e":"瓦斯外洩時開啟電器可能產生火花引爆，不可開電風扇。"},{"c":9,"n":50,"q":"全球暖化潛勢（Global Warming Potential, GWP）是衡量溫室氣體對全球暖化的影響，以何者為比較基準？","o":["CO 2","CH 4","SF 6","N 2 O"],"a":1,"e":"全球暖化潛勢以CO₂為比較基準（GWP=1）。"},{"c":9,"n":51,"q":"有關建築之外殼節能設計，下列敘述何者錯誤？","o":["開窗區域設置遮陽設備","大開窗面避免設置於東西日曬方位","做好屋頂隔熱設施","宜採用全面玻璃造型設計，以利自然採光"],"a":4,"e":"全面玻璃造型會增加日照熱，不利節能。"},{"c":9,"n":52,"q":"下列何者燈泡的發光效率最高？","o":["LED 燈泡","省電燈泡","白熾燈泡","鹵素燈泡"],"a":1,"e":"LED燈泡的發光效率最高。"},{"c":9,"n":53,"q":"有關吹風機使用注意事項，下列敘述何者錯誤？","o":["請勿在潮濕的地方使用，以免觸電危險","應保持吹風機進、出風口之空氣流通，以免造成過熱","應避免長時間使用，使用時應保持適當的距離","可用來作為烘乾棉被及床單等用途"],"a":4,"e":"吹風機不可用來烘乾棉被，容易過熱引發火災。"},{"c":9,"n":54,"q":"有關無風管空氣調節機的能源效率的描述，下列何者正確？","o":["冷氣季節性能因數（CSPF）越高越好","能源效率比（Energy Efficiency Rate ）越低越好","能源效率等級為 5 級時，最省電且對環境也較友善","廠商銷售此類產品時，無須張貼能源效率分級標示圖"],"a":1,"e":"冷氣的CSPF越高越省電。"},{"c":9,"n":55,"q":"為了避免漏電而危害生命安全，下列「不正確」的做法是？","o":["做好用電設備金屬外殼的接地","有濕氣的用電場合，線路加裝漏電斷路器","加強定期的漏電檢查及維護","使用保險絲來防止漏電的危險性"],"a":4,"e":"保險絲是防止過載短路，不能防止漏電，應使用漏電斷路器。"},{"c":9,"n":56,"q":"用電設備的線路保護用電力熔絲（保險絲）經常燒斷，造成停電的不便，下列「不正確」的作法是？","o":["換大一級或大兩級規格的保險絲或斷路器就不會燒斷了","減少線路連接的電氣設備，降低用電量","重新設計線路，改較粗的導線或用兩迴路並聯","提高用電設備的功率因數"],"a":1,"e":"換大規格保險絲會使線路過熱，有火災風險。"},{"c":9,"n":57,"q":"政府為推廣節能設備而補助民眾汰換老舊設備，下列何者的節電效益最佳？","o":["將桌上檯燈光源由螢光燈換為 LED 燈","優先淘汰 10 年以上的老舊冷氣機為能源效率標示分級中之一級冷氣機","汰換電風扇，改裝設能源效率標示分級為一級的冷氣機","因為經費有限，選擇便宜的產品比較重要"],"a":2,"e":"汰換10年以上老舊冷氣為一級機種，節電效益最大。"},{"c":9,"n":58,"q":"依據我國現行國家標準規定，冷氣機的冷氣能力標示應以何種單位表示？","o":["kW","BTU/h","kcal/h","RT"],"a":1,"e":"國家標準規定冷氣能力以kW標示。"},{"c":9,"n":59,"q":"漏電影響節電成效，並且影響用電安全，簡易的查修方法為","o":["電氣材料行買支驗電起子，碰觸電氣設備的外殼，就可查出漏電與否","用手碰觸就可以知道有無漏電","用三用電表檢查","看電費單有無紀錄"],"a":1,"e":"驗電起子可以簡易檢查設備外殼有無漏電。"},{"c":9,"n":60,"q":"使用了10幾年的通風換氣扇老舊又骯髒，噪音又大，維修時採取下列哪一種對策最為正確及節能？","o":["定期拆下來清洗油垢","不必再猶豫，10 年以上的電扇效率偏低，直接換為高效率通風扇","直接噴沙拉脫清潔劑就可以了，省錢又方便","高效率通風扇較貴，換同機型的廠內備用品就好了"],"a":2,"e":"10年以上的老舊風扇效率低，直接換成高效率通風扇最節能。"},{"c":9,"n":61,"q":"電氣設備維修時，在關掉電源後，最好停留1至5分鐘才開始檢修，其主要的理由為下列何者？","o":["先平靜心情，做好準備才動手","讓機器設備降溫下來再查修","讓裡面的電容器有時間放電完畢，才安全","法規沒有規定，這完全沒有必要"],"a":3,"e":"關掉電源後稍等，讓電容器放電完畢再檢修，比較安全。"},{"c":9,"n":62,"q":"電氣設備裝設於有潮濕水氣的環境時，最應該優先檢查及確認的措施是？","o":["有無在線路上裝設漏電斷路器","電氣設備上有無安全保險絲","有無過載及過熱保護設備","有無可能傾倒及生鏽"],"a":1,"e":"潮濕環境最應優先確認有無裝設漏電斷路器。"},{"c":9,"n":63,"q":"對於使用冷氣如何節能的描述，下列何者錯誤？","o":["冷氣溫度設定範圍以 26-28℃為宜","開冷氣同時開啟窗戶有助於省電","冷氣房內配合電風扇使用，可適度調高溫度以節省用電","加裝設自動溫控設備，可以避免過冷而浪費能源"],"a":2,"e":"開冷氣時開窗會使冷氣外洩，更耗電。"},{"c":9,"n":64,"q":"家庭用電最大宗來自於","o":["冷氣機","電腦","電視","吹風機"],"a":1,"e":"冷氣機是家庭最大宗的用電。"},{"c":9,"n":65,"q":"冷氣房內為減少日照高溫及降低空調負載，下列何種處理方式錯誤？","o":["窗戶裝設窗簾或貼隔熱紙","將窗戶或門開啟，讓屋內外空氣自然對流","屋頂加裝隔熱材、高反射率塗料或噴水","於屋頂進行薄層綠化"],"a":2,"e":"開冷氣時開門窗會使冷氣外洩，增加耗電。"},{"c":9,"n":66,"q":"有關電冰箱放置位置的處理方式，下列何者正確？","o":["背後緊貼牆壁節省空間","背後距離牆壁應有 10 公分以上空間，以利散熱","室內空間有限，側面緊貼牆壁就可以了","冰箱最好貼近流理台，以便存取食材"],"a":2,"e":"冰箱背面離牆10公分以上，以利散熱。"},{"c":9,"n":67,"q":"下列何項「不是」照明節能改善需優先考量之因素？","o":["照明方式是否適當","燈具之外型是否美觀","照明之品質是否適當","照度是否適當"],"a":2,"e":"燈具外型美觀與節能無關。"},{"c":9,"n":68,"q":"醫院、飯店或宿舍之熱水系統耗能大，要設置熱水系統時，應優先選用何種熱水系統較節能？","o":["電能熱水系統","熱泵熱水系統","瓦斯熱水系統","重油熱水系統"],"a":2,"e":"熱泵熱水系統效率最高，最節能。"},{"c":9,"n":69,"q":"如下圖示為","o":["省水標章","環保標章","奈米標章","能源效率標示"],"a":4,"e":"圖示為經濟部的能源效率分級標示。","img":"img/q993.jpg"},{"c":9,"n":70,"q":"台灣電力公司電價表所指的夏月用電月份（電價比其他月份高）是為","o":["4/1〜7/31","5/1〜8/31","6/1〜9/30","7/1〜10/31"],"a":3,"e":"台電夏月為6月1日至9月30日。"},{"c":9,"n":71,"q":"屋頂隔熱可有效降低空調用電，下列何項措施較不適當？","o":["屋頂儲水隔熱","屋頂綠化","於適當位置設置太陽能板發電同時加以隔熱","鋪設隔熱磚"],"a":1,"e":"屋頂儲水會增加結構負荷，也可能孳生蚊蟲，較不適當。"},{"c":9,"n":72,"q":"電腦機房使用時間長、耗電量大，下列何項措施對電腦機房之用電管理較不適當？","o":["機房設定較低之溫度","設置冷熱通道","使用較高效率之空調設備","使用新型高效能電腦設備"],"a":1,"e":"機房溫度設太低會大幅增加空調耗電。"},{"c":9,"n":73,"q":"有關省水標章之敘述，下列何者正確？","o":["省水標章是環境部為推動使用節水器材，特別研定以作為消費者辨識省水產品的一種標誌","獲得省水標章的產品並無嚴格測試，所以對消費者並無一定的保障","省水標章能激勵廠商重視省水產品的研發與製造，進而達到推廣節水良性循環之目的","省水標章除有用水設備外，亦可使用於冷氣或冰箱上"],"a":3,"e":"省水標章鼓勵廠商研發省水產品，推廣節水。"},{"c":9,"n":74,"q":"透過淋浴習慣的改變就可以節約用水，下列何者正確？","o":["淋浴時抹肥皂，無需將蓮蓬頭暫時關上","等待熱水前流出的冷水可以用水桶接起來再利用","淋浴流下的水不可以刷洗浴室地板","淋浴沖澡流下的水，可以儲蓄洗菜使用"],"a":2,"e":"等熱水前流出的冷水用水桶接起來，可以再利用。"},{"c":9,"n":75,"q":"家人洗澡時，一個接一個連續洗，也是一種有效的省水方式嗎？","o":["是，因為可以節省等待熱水流出之前所先流失的冷水","否，這跟省水沒什麼關係，不用這麼麻煩","否，因為等熱水時流出的水量不多","有可能省水也可能不省水，無法定論"],"a":1,"e":"家人連續洗澡，可以減少等待熱水時流掉的冷水。"},{"c":9,"n":76,"q":"下列何種方式有助於節省洗衣機的用水量？","o":["洗衣機洗滌的衣物盡量裝滿，一次洗完","購買洗衣機時選購有省水標章的洗衣機，可有效節約用水","無需將衣物適當分類","洗濯衣物時盡量選擇高水位才洗得乾淨"],"a":2,"e":"選購有省水標章的洗衣機，可以有效節約用水。"},{"c":9,"n":77,"q":"如果水龍頭流量過大，下列何種處理方式錯誤？","o":["加裝節水墊片或起波器","加裝可自動關閉水龍頭的自動感應器","直接換裝沒有省水標章的水龍頭","直接調整水龍頭到適當水量"],"a":3,"e":"換裝沒有省水標章的水龍頭無法省水。"},{"c":9,"n":78,"q":"洗菜水、洗碗水、洗衣水、洗澡水等的清洗水，不可直接利用來做什麼用途？","o":["洗地板","沖馬桶","澆花","飲用水"],"a":4,"e":"清洗過的水不可以飲用。"},{"c":9,"n":79,"q":"如果馬桶有不正常的漏水問題，下列何者處理方式錯誤？","o":["因為馬桶還能正常使用，所以不用著急，等到不能用時再報修即可","立刻檢查馬桶水箱零件有無鬆脫，並確認有無漏水","滴幾滴食用色素到水箱裡，檢查有無有色水流進馬桶，代表可能有漏水","通知水電行或檢修人員來檢修，徹底根絕漏水問題"],"a":1,"e":"馬桶漏水會持續浪費水，應立即處理。"},{"c":9,"n":80,"q":"水費的計量單位是「度」，一度水的容量大約有多少？","o":["2,000 公升","3000 個 600cc 的寶特瓶","1 立方公尺的水量","3 立方公尺的水量"],"a":3,"e":"1度水 = 1立方公尺 = 1,000公升。"},{"c":9,"n":81,"q":"臺灣在一年中什麼時期會比較缺水（即枯水期）？","o":["6 月至 9 月","9 月至 12 月","11 月至次年 4 月","臺灣全年不缺水"],"a":3,"e":"台灣枯水期約為11月至隔年4月。"},{"c":9,"n":82,"q":"下列何種現象「不是」直接造成台灣缺水的原因？","o":["降雨季節分布不平均，有時候連續好幾個月不下雨，有時又會下起豪大雨","地形山高坡陡，所以雨一下很快就會流入大海","因為民生與工商業用水需求量都愈來愈大，所以缺水季節很容易無水可用","台灣地區夏天過熱，致蒸發量過大"],"a":4,"e":"蒸發量過大不是台灣缺水的直接主因。"},{"c":9,"n":83,"q":"冷凍食品該如何讓它退冰，才是既「節能」又「省水」？","o":["直接用水沖食物強迫退冰","使用微波爐解凍快速又方便","烹煮前盡早拿出來放置退冰","用熱水浸泡，每 5 分鐘更換一次"],"a":3,"e":"提早拿出來在冷藏室慢慢退冰，最節能又省水。"},{"c":9,"n":84,"q":"洗碗、洗菜用何種方式可以達到清洗又省水的效果？","o":["對著水龍頭直接沖洗，且要盡量將水龍頭開大才能確保洗得乾淨","將適量的水放在盆槽內洗濯，以減少用水","把碗盤、菜等浸在水盆裡，再開水龍頭拼命沖水","用熱水及冷水大量交叉沖洗達到最佳清洗效果"],"a":2,"e":"在盆槽中放適量的水清洗，可以減少用水。"},{"c":9,"n":85,"q":"解決台灣水荒（缺水）問題的無效對策是","o":["興建水庫、蓄洪（豐）濟枯","全面節約用水","水資源重複利用，海水淡化…等","積極推動全民體育運動"],"a":4,"e":"推動全民體育與解決缺水無關。"},{"c":9,"n":86,"q":"如下圖，這是什麼標章？","o":["奈米標章","環保標章","省水標章","節能標章"],"a":3,"e":"圖示為省水標章。","img":"img/q1010.jpg"},{"c":9,"n":87,"q":"澆花的時間何時較為適當，水分不易蒸發又對植物最好？","o":["正中午","下午時段","清晨或傍晚","半夜十二點"],"a":3,"e":"清晨或傍晚澆花，水分不易蒸發。"},{"c":9,"n":88,"q":"下列何種方式沒有辦法降低洗衣機之使用水量，不建議採用？","o":["使用低水位清洗","選擇快洗行程","兩、三件衣服也丟洗衣機洗","選擇有自動調節水量的洗衣機"],"a":3,"e":"只有兩、三件衣服也用洗衣機洗，會浪費水。"},{"c":9,"n":89,"q":"有關省水馬桶的使用方式與觀念認知，下列何者錯誤？","o":["選用衛浴設備時最好能採用省水標章馬桶","如果家裡的馬桶是傳統舊式，可以加裝二段式沖水配件","省水馬桶因為水量較小，會有沖不乾淨的問題，所以應該多沖幾次","因為馬桶是家裡用水的大宗，所以應該儘量採用省水馬桶來節約用水"],"a":3,"e":"省水馬桶設計上能沖乾淨，重複沖水反而浪費。"},{"c":9,"n":90,"q":"下列的洗車方式，何者「無法」節約用水？","o":["使用有開關的水管可以隨時控制出水","用水桶及海綿抹布擦洗","用大口徑強力水注沖洗","利用機械自動洗車，洗車水處理循環使用"],"a":3,"e":"用大口徑強力水柱沖洗耗水量最大。"},{"c":9,"n":91,"q":"下列何種現象「無法」看出家裡有漏水的問題？","o":["水龍頭打開使用時，水表的指針持續在轉動","牆面、地面或天花板忽然出現潮濕的現象","馬桶裡的水常在晃動，或是沒辦法止水","水費有大幅度增加"],"a":1,"e":"開水龍頭時水表本來就會轉動，不能據此判斷漏水；應在全部關閉時觀察。"},{"c":9,"n":92,"q":"蓮蓬頭出水量過大時，下列對策何者「無法」達到省水？","o":["換裝有省水標章的低流量（5〜10L/min）蓮蓬頭","淋浴時水量開大，無需改變使用方法","洗澡時間盡量縮短，塗抹肥皂時要把蓮蓬頭關起來","調整熱水器水量到適中位置"],"a":2,"e":"水量開大且不改變使用習慣，無法省水。"},{"c":9,"n":93,"q":"自來水淨水步驟，下列何者錯誤？","o":["混凝","沉澱","過濾","煮沸"],"a":4,"e":"自來水淨水步驟為混凝、沉澱、過濾、消毒，不包括煮沸。"},{"c":9,"n":94,"q":"為了取得良好的水資源，通常在河川的哪一段興建水庫？","o":["上游","中游","下游","下游出口"],"a":1,"e":"水庫通常建在河川上游，水質較好。"},{"c":9,"n":95,"q":"辦公室常見的設備其節能方式之描述，下列何者錯誤？","o":["影印機、印表機下班及假日關機可以減少待機耗能","飲水機可以加裝定時器或設定內部定時，降低下班、假日加熱耗能","電腦自己會休眠不需要關機","冷氣濾網定期清洗，可恢復冷卻能力節省用電"],"a":3,"e":"電腦待機仍然耗電，下班應關機。"},{"c":9,"n":96,"q":"台灣年降雨量是世界平均值的2.6倍，卻仍屬缺水地區，下列何者不是真正缺水的原因？","o":["台灣由於山坡陡峻，以及颱風豪雨雨勢急促，大部分的降雨量皆迅速流入海洋","降雨量在地域、季節分布極不平均","水庫蓋得太少","台灣自來水水價過於便宜"],"a":3,"e":"題庫判定「水庫蓋得太少」不是真正缺水的原因。"},{"c":9,"n":97,"q":"電源插座堆積灰塵可能引起電氣意外火災，維護保養時的正確做法是？","o":["可以先用刷子刷去積塵","直接用吹風機吹開灰塵就可以了","應先關閉電源總開關箱內控制該插座的分路開關，然後再清理灰塵","可以用金屬接點清潔劑噴在插座中去除銹蝕"],"a":3,"e":"清理插座前應先關閉電源分路開關，避免觸電。"},{"c":9,"n":98,"q":"溫室氣體易造成全球氣候變遷的影響，下列何者不屬於溫室氣體？","o":["二氧化碳（CO 2 ）","氫氟碳化物（HFCs）","甲烷（CH 4 ）","氧氣（O 2 ）"],"a":4,"e":"氧氣不是溫室氣體。"},{"c":9,"n":99,"q":"就能源管理系統而言，下列何者不是能源效率的表示方式？","o":["汽車－公里 /公升","照明系統－瓦特/平方公尺（W/m 2 ）","冰水主機－千瓦/冷凍噸（kW/RT）","冰水主機－千瓦（kW）"],"a":4,"e":"能源效率是「單位產出所耗能源」的比值，只有千瓦（kW）無法表示效率。"},{"c":9,"n":100,"q":"某工廠規劃汰換老舊低效率設備，下列何種做法不恰當？","o":["可考慮使用較高效率設備產品","先針對老舊設備建立其「能源指標」或「能源基線」","唯恐一直浪費能源，未經評估就馬上將老舊設備汰換掉","改善後需進行能源績效評估"],"a":3,"e":"汰換設備前應先評估，不可未經評估就馬上汰換。"}],"prac":{"tests":[{"id":"01","name":"生命徵象測量","time":20,"must":true,"case":"陳太太睡醒後表示不舒服。請測量生命徵象（體溫、脈搏、呼吸、血壓），並登錄於紀錄表上。","zero":["操作過程中案主跌倒、摔傷等意外，本題以零分計。","任一項測量數值不正確而影響及格與否時，會安排複測一次。"],"secs":[{"h":"準備工作","pts":20,"items":[["向案主解釋測量生命徵象的原由",2],["指甲需修短並脫除手錶及手上飾物（若無法脫除則以膠帶固定）",2],["將衣袖捲到肘關節上方2吋",1],["打開水龍頭，沾濕雙手，關水龍頭，按壓1～2滴洗手乳在手上",2],["雙手互相摩擦搓揉，搓手心、手背、手指縫、指背、大姆指、指尖及手腕上2吋（每個部位至少搓洗5～10下）",5],["打開水龍頭，雙手置水龍頭下，以交互搓揉沖洗的方式洗淨雙手",2],["雙手捧水將水龍頭開關沖洗乾淨並關閉開關",2],["以擦手紙擦乾雙手，將擦手紙丟入腳踏式的垃圾桶內",2],["準備用物：耳溫槍一支、耳溫套、記錄單、筆、臂式電子血壓計",2]]},{"h":"體溫測量法（耳溫槍）","pts":17,"items":[["檢查耳溫槍外觀",2],["按一下耳溫槍上的按鈕開關，確認電力充足",2],["套上耳溫套",1],["告知案主並檢視耳道是否耳垢過多，如果有，則先清除乾淨後再測量",2],["告知案主並固定案主頭部，並輕輕地將耳朵往後上方拉",2],["告知案主並將耳溫槍槍頭伸入案主耳道並以手指按壓「測量鍵」約1秒鐘，待「嗶」響後放開按鍵",6],["正確讀出並記錄測量的溫度，取下耳溫套並丟棄",2]]},{"h":"脈搏測量法","pts":17,"items":[["將案主手置於床上、桌上或椅子扶手，確定手臂有適當支托",3],["指出並使用食、中、無名三指觸摸案主橈動脈",7],["測量一分鐘",5],["正確測量及記錄",2]]},{"h":"呼吸測量法","pts":12,"items":[["手指仍保持按在手腕上，觀察案主胸、腹起伏，算出呼吸次數",5],["測量一分鐘",5],["正確測量及記錄",2]]},{"h":"電子血壓測量法","pts":25,"items":[["使案主姿勢舒適，手放平並捲起袖子或整平袖子",2],["置血壓計於適當位置使其手臂與心臟成一水平",2],["打開血壓計之『電源』開關，確認電力充足",2],["觸診肱動脈找出脈搏搏動點",2],["將壓脈帶平置於上臂離肘彎2至3公分處，再將壓脈帶上的記號標示點對準肱動脈後，纏繞於手臂上（鬆緊度以2手指平放可伸入為原則）",5],["按下『加壓』鍵，即開始充氣並偵測血壓值",2],["正確記錄收縮壓及和舒張壓之數據及單位",2],["如欲測量第二次血壓，需略活動肢體",2],["取下壓脈帶並放下病人衣袖",2],["關閉『電源』開關",2],["收妥壓脈帶放入血壓計內",2]]},{"h":"事後處理","pts":3,"items":[["收拾用物",1],["工作後洗手",1],["記錄，並將各項測量結果告訴案主",1]]},{"h":"其他","pts":6,"items":[["注意儀表態度，測量過程能與案主真誠互動",2],["注意案主隱私",2],["動作輕柔，注意案主舒適及安全",2]]}]},{"id":"02","name":"成人異物哽塞急救法","time":5,"case":"王老先生坐在有扶手的椅子上吃午餐，突然噎住、說不出話但意識清楚。請將哽嗆模型移到沒有扶手的椅子上，以坐姿執行成人異物哽塞急救法。","zero":["操作前洗手者本題零分（洗手會延誤急救時效）。","案主跌倒、摔傷等意外，本題零分。","模擬異物因模型傾斜而掉出者，需重新操作。"],"secs":[{"h":"坐姿（成人坐姿腹戳法）","pts":45,"items":[["施救者由案主背後向前方上腹部環抱",10],["手部位置在案主劍突與肚臍中間處",15],["一手握拳，拇指與食指側頂往上腹部，另一手覆蓋於拳頭上",10],["瞬間用力，向內往上緊壓數次",10]]},{"h":"急救結果","pts":45,"items":[["反覆實施，直至噎住物（模擬異物）噴出",45]]},{"h":"急救後處理","pts":10,"items":[["將案主抱回原座椅，安慰案主",4],["告訴案主或家屬應小心進食，以防哽塞發生",3],["洗手",3]]}]},{"id":"03","name":"成人心肺甦醒術","time":6,"case":"早上進入陳太太臥室時，發現久病在床的陳太太嘴唇發紫，好像沒有呼吸。請執行成人心肺甦醒術。","zero":["操作前洗手者本題零分（洗手會延誤急救時效）。","案主跌倒、摔傷等意外，本題零分。"],"secs":[{"h":"評估意識","pts":6,"items":[["輕拍案主肩膀並呼叫（如：陳太太你好嗎？），同時目測是否有正常呼吸",6]]},{"h":"求救","pts":6,"items":[["自己或呼叫他人求救（撥119），並口述儘速取得AED",4],["將案主安全搬運平躺於地板上（口述）",2]]},{"h":"快速胸部按壓","pts":19,"items":[["找出正確位置：手指沿肋間下緣滑向劍突上兩橫指，另一手掌根放在前手上；或兩乳頭連線中點（胸骨下半段）",6],["姿勢：雙手固定於胸骨不彈跳移動、雙臂打直、身體不搖擺、五指不完全貼胸",5],["用背部及肩膀力量垂直下壓5～6公分，壓力平穩；放鬆時讓胸廓充分回彈，但手掌不離開胸骨",4],["以每分鐘100～120次速率按壓30次（需亮綠燈）",4]]},{"h":"呼吸","pts":22,"items":[["以壓額抬下巴法打開呼吸道，並口述清除口腔異物",4],["維持呼吸道通暢：一手置前額、一手抬下巴",5],["捏緊案主鼻子，嘴部與案主口部密合",4],["吸氣後給予兩次人工呼吸（每次吹氣1秒）",4],["觀察胸部起伏；若無起伏，重新暢通呼吸道再吹氣或排除口腔異物（口述）",5]]},{"h":"重複壓胸與換氣循環（持續五循環）","pts":29,"items":[["頸動脈無搏動→施行30：2；按壓位置正確",6],["施救者姿勢正確（雙臂打直、不彈跳、身體不搖擺）",5],["下壓深度5～6公分，充分回彈、掌根不離胸骨",4],["以每分鐘100～120次速率按壓30次（需亮綠燈）",4],["監測器亮綠燈，按壓與人工呼吸比率30：2（口令數數掌握節奏）",6],["約2分鐘做完五個循環",4]]},{"h":"急救後檢查成效","pts":12,"items":[["檢查脈搏，並口述呼吸跡象（呼吸、咳嗽）、身體四肢有無移動",4],["若無脈搏，繼續心肺復甦術（口述）",4],["若有脈搏但無呼吸，繼續人工呼吸每分鐘12次，直到出現呼吸（口述）",4]]},{"h":"急救後處理","pts":6,"items":[["案主若無意識，採復甦姿勢（口述並示範）",4],["保暖送醫，並密切評估呼吸及脈搏（口述）",2]]}]},{"id":"04","name":"備餐、餵食及協助用藥","time":40,"must":true,"case":"孫奶奶獨居、牙齒少、咀嚼困難、視力不良；血糖與血壓都高，近日刷牙牙齦出血，醫囑三餐飯後各給1顆維生素C（200mg）。早餐已給康魯納、脈優及維生素C。吞水易嗆到，需經鼻胃管給藥。請準備魚菜粥作為午餐、協助以口進食，並在飯後經鼻胃管灌午餐後的藥物。","zero":["案主跌倒、摔傷、燙傷等意外，本題零分。","烹煮結束未關閉爐火（危及居家安全），本題零分。","進場前須穿好圍裙，否則不准進場。"],"secs":[{"h":"準備工作","pts":4,"items":[["向案主說明將為其準備餐食",2],["脫除手錶及飾物（無法脫除以膠帶固定），以洗手乳洗淨雙手",2]]},{"h":"備食","pts":15,"items":[["以流動水洗滌食材及器皿，符合清潔原則",2],["詢問案主的烹調習慣（喜好）",2],["調味符合低鹽原則",2],["依序烹煮：飯→魚（板豆腐）→菜",3],["魚、菜切碎，飯煮成黏稠狀",2],["以其他餐具試嚐味道",2],["將魚菜粥盛於碗中，外觀乾淨清爽，並符合案主食量（約八分滿）",2]]},{"h":"協助進食（餵食）","pts":17,"items":[["協助案主圍上圍兜",2],["先測試食物溫度",3],["做出餵食動作並口述互動語言（餵食後的粥置於另一空碗）",5],["注意避免案主嗆到",3],["餵食後協助案主清潔口腔",2],["飯後避免立刻平躺（口述）",2]]},{"h":"膳後清理","pts":2,"items":[["殘渣丟入加蓋垃圾桶；洗淨廚具餐具歸位；清理水槽、擦拭桌面",2]]},{"h":"協助用藥","pts":41,"items":[["正確備藥（午餐飯後只給維生素C 1顆）",2],["用藥時間正確（飯後）",3],["確認藥物的安全性（有效期限、外觀）",2],["以正確的服藥溶液（開水；切勿用菜湯、茶或果汁）",1],["藥丸磨成粉、倒入小藥杯並確認研缽無殘留→加開水溶解→灌藥前反抽確認鼻胃管在胃中→依重力灌入，沖到無殘留後再給水至少30cc",28],["必要時反摺鼻胃管，避免空氣灌入胃部",5]]},{"h":"其他","pts":21,"items":[["個人衛生：不用圍裙或抹布擦手，不抓頭摸臉",4],["食品清潔：不用手直接碰觸煮熟的粥",3],["餐具廚具衛生：不用抹布擦餐具，保持乾淨",3],["節約用水用紙：不讓水龍頭空流",2],["操作熟練流暢，注意安全原則",9]]}]},{"id":"05","name":"洗頭、衣物更換","time":40,"case":"王奶奶多年前中風，左側肢體癱瘓臥床，多日未洗頭，平日有潤髮習慣。請執行床上洗頭及更換上衣。","zero":["進場前須穿好圍裙，否則不准進場。"],"secs":[{"h":"準備工作","pts":20,"items":[["向案主說明將為其洗頭、更換上衣的目的及步驟",5],["穿圍裙，脫除手錶、手鍊等飾品（若無法脫除則以膠帶固定）",3],["洗淨雙手",5],["準備洗頭用具",5],["準備案主衣物",2]]},{"h":"床上洗頭","pts":47,"items":[["準備用水，並以手腕內側測量水溫至適當溫度",4],["放置洗頭槽（先以塑膠袋及大毛巾舖在洗頭槽下）於頸部下方，並予適當支托患肢",2],["洗頭槽排水口超出床沿",2],["將一水桶置放在洗頭槽排水端下方",2],["先淋一點水在案主頭髮上，並詢問案主水溫是否適當",4],["以適量洗髮精清洗頭髮後，並以潤髮乳滋潤頭髮",5],["進行洗頭時，以指腹輕揉案主頭部",5],["留意不讓水流入案主耳朵或眼睛",5],["觀察案主頭皮是否有異樣",4],["確實將頭髮清洗乾淨",10],["讓案主採臥姿，使用吹風機吹乾頭髮梳理整齊",4]]},{"h":"更換上衣","pts":17,"items":[["維護隱私",4],["從健肢開始脫掉上半身衣服，並適當支托患肢",5],["從患肢開始穿上衣，並適當支托患肢",5],["扣上衣服扣子，擺整妥當，蓋上蓋單",3]]},{"h":"事後處理","pts":2,"items":[["物品歸位整理環境（必要時擦乾地板）",2]]},{"h":"其他","pts":14,"items":[["動作熟練順暢，溫柔輕巧，並注意不能將案主的床及衣服弄溼",3],["能隨時注意案主安全與舒適（如過程中給予案主左側患肢適當支托，依案主反應進行水溫調整）",8],["能留意案主的需要，給予適當回饋，並營造愉快的氣氛",3]]}]},{"id":"06","name":"會陰沖洗及尿管清潔","time":25,"case":"抽籤決定情況A或B。A：王奶奶中風、左側癱瘓臥床，長期使用導尿管。B：張老先生中風、左側癱瘓臥床，長期使用導尿管。請執行每日例行的會陰沖洗及尿管清潔。","zero":["案主跌倒、摔傷、燙傷等意外，本題零分。","進場前須穿好圍裙，否則不准進場。"],"secs":[{"h":"準備工作","pts":20,"items":[["向案主說明將清潔會陰及尿管",2],["脫除手錶、手鍊等飾物（無法脫除以膠帶固定）",3],["洗淨雙手",4],["準備用具及用品，注意有效日期",3],["準備用水及適當水溫",3],["保護案主隱私",5]]},{"h":"會陰清潔－情況A 女性（32分，與B擇一）","pts":32,"items":[["協助抬高臀部，放置防水中單於腰臀以下",2],["脫去右側褲管拉向另一側並支撐患側，右下肢以大浴巾覆蓋保暖",3],["放置便盆於腰臀以下",3],["準備姿勢：墊高頭頸部，健側膝略彎曲",3],["觀察記錄會陰分泌物的量、顏色、氣味",3],["戴清潔手套，由棉枝末端打開沖洗棉枝包",3],["沖洗壺壺嘴朝床尾，以棉枝依序清洗：尿道口→遠側小陰唇→近側小陰唇→遠側大陰唇→近側大陰唇",7],["另取棉枝依序擦乾：小陰唇→大陰唇→會陰部周圍",5],["過程中逐步告知步驟，注意保暖、防溼",3]]},{"h":"會陰清潔－情況B 男性（32分，與A擇一）","pts":32,"items":[["協助抬高臀部，放置防水中單於腰臀下方",2],["脫去健側褲管拉向另一側並支撐患側，下肢以大浴巾覆蓋保暖",3],["放置便盆於腰臀下方",3],["準備姿勢：墊高頭頸部，健側膝略彎曲",3],["觀察記錄會陰分泌物的量、顏色、氣味",3],["戴清潔手套打開棉枝包，棉枝以沖洗壺沾溼再抹香皂",3],["一手握住陰莖，做出包皮往後推的動作並口述，露出龜頭以棉枝清洗",4],["以潤溼毛巾沾肥皂清洗陰莖、陰囊及肛門",3],["以沖洗壺、方巾沖洗至所有部位清潔並擦乾",4],["過程中逐步告知步驟，注意保暖、防溼",4]]},{"h":"尿管處理","pts":38,"items":[["觀察尿液的量、顏色、氣味及沉澱物",3],["輕拉尿管約0.5公分；以棉枝分別用優碘及生理食鹽水，由尿道口往下環形清潔尿管約5公分",10],["更換尿管膠布的固定位置",3],["移動尿袋時保持在膀胱以下",5],["尿袋開口隨時關閉，避免污染",3],["檢查尿管通暢，避免受壓扭曲",5],["移去便盆並擦乾臀部（由會陰往臀部擦），脫除手套",4],["觀察、報告及記錄異常：阻塞、滲尿、沉澱物、尿量過少、尿管滑脫等",3],["穿整衣褲，保持床單平整乾燥",2]]},{"h":"事後處理","pts":10,"items":[["物品歸位整理環境",1],["動作熟練順暢",5],["隨時注意案主安全",2],["洗手",2]]}]},{"id":"07","name":"協助上下床及坐輪椅","time":20,"case":"王先生90歲，左側軟弱無力，臥床休息後想坐輪椅到戶外曬太陽。請協助下床、坐入輪椅並推動10公尺，再折返床邊協助臥床休息。","zero":["進場前須穿好圍裙，否則不准進場。"],"secs":[{"h":"準備工作","pts":16,"items":[["與案主討論協助安全坐入輪椅過程",3],["檢查輪椅是否安全可用",5],["將輪椅放在案主臥姿之健側，與床平行或呈45度角",3],["固定輪椅，收起腳踏板",3],["洗手",2]]},{"h":"準備案主","pts":4,"items":[["將蓋被褪至床尾",2],["將案主雙手置於適當位置（如：交叉置於腹部）",2]]},{"h":"協助案主下床坐輪椅","pts":47,"items":[["站在案主所需移向的一側床邊，面對案主",2],["托住頭，將枕頭先移動至要移動的一側，將案主安全地移向照顧服務員，並隨時注意案主安全",5],["將案主扶起，協助坐於床緣，隨時保護案主的安全",6],["注意其安全，觀察其臉色，並測量脈搏及呼吸，確認其臉色、脈搏及呼吸穩定（口述）",6],["面對案主，鼓勵案主用右健側支托左患側，並保護案主移位時的安全。照顧服務員可利用身體力學的原理搬運案主，以預防職業傷害",5],["安全地將案主移到輪椅，觀察其臉色，並測量脈搏及呼吸，確認其臉色、脈搏及呼吸穩定（口述）",8],["將案主雙手安全舒適放妥，雙腳置於腳踏板上",3],["確定案主坐姿舒適，衣著平整，穿妥外套及鞋襪，並注意身體保暖情形",8],["解開輪椅固定開關推動前進10公尺並與案主互動，再將案主推回床邊",4]]},{"h":"協助案主上床","pts":29,"items":[["固定輪椅並收腳踏板",3],["協助坐穩於輪椅，脫除外套，隨時保護案主的安全",8],["面對案主，鼓勵案主用右健側支托左患側，並保護案主移位時的安全。照顧服務員可利用身體力學的原理搬運案主",5],["安全地將案主移到床上，觀察其臉色，並測量脈搏及呼吸，確認其臉色、脈搏及呼吸穩定（口述）",8],["扶住肩部，讓案主上半身先躺下，再平移雙腳並脫除鞋子，使案主舒適臥床",5]]},{"h":"事後處理工作","pts":4,"items":[["將床邊物品收放整齊，輪椅收好並固定",2],["洗手",2]]}]}],"sets":{"甲":["01","02","04","05"],"乙":["01","03","04","07"],"丙":["01","02","04","06"]}},"ver":{"17800":"178004A13（115.08.17公告）","90006":"900060A18","90007":"900070A17","90008":"900080A16","90009":"900090A11","tech":"178004B19"}};